INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('cbe488bc-db9b-589f-a09c-6637de4141e9', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 20, 20, ''),
  ('2a4548cd-758d-52f2-a773-daf128a599e2', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 21, 21, 'የሠጠሁትንም ሕጌ ከተደፋፈርክ ስምህን አጠፋለሁ ትእዛዜን ለጠበቀ ሁሉ እወደዋለሁ።'),
  ('e48e9c6c-8585-5e57-aa1b-f764dad071d1', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 22, 22, 'ቃሌን የሚጠላና የማይጠብቀው እኔ አይደለሁም የምኮንነው ያ ከሱ ፊት ሲነገር የኖረው ቃሌ ይፋረደዋል ምክርም ይሆንበታል በግሉ ዕዳ መጸሀፍም ይፃፍበታል ካህን የሆነ ሁሉ ምድራዊቷን በሰማያዊቷ ኢየሩሳሌም ሥርዓት አስመስሎ ቤተክርስቲያን በአለቆች ፊትና በሰውም ሁሉ ፊት ይፈዕም።'),
  ('955b1db2-16dd-53bb-ad50-3e2b53af0ba9', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 23, 23, 'ጌታችን ኢየሱስ ክርስቶስ ከኛ ከሐዋርያት ተለይቶ ወደሰማያት ሥርዓት አስተምሮናል ከማረጉ አስቀድሞ የቤተክርስቲያንን ወደሰማይ በአየር ላይ የሚገነትን መላእክት አስተምሮአቸዋል።'),
  ('58f560d6-cb8a-55cf-adc5-3ff23ab69681', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 24, 24, 'በዳግም ዕለትም ሊቃነመላእክትን አስተማራቸው እነሱም ሰገዱለት በሱም አመነ ጌታቸው መሆኑንም አምነው አወቁት መላእክት ከኛ የለበሰውን ሥጋ እንደለበሰ አዩት ከዚሁ ሥጋ ጋር አርጓልና በሦስተኛ ጊዜ አጋእዝትን አስተማራቸው እነሱም አምነው ስገዱለት ከኛ ለብሶት ያረገውንም ሥጋ እንደለበሰ አዩት።'),
  ('3e16da7b-3177-5ec8-a9d8-cd5748ff195b', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 25, 25, 'በአራተኛው ዕለት ከኛ የለበሰውን ሥጋ ይዞ ሲያርግ አይተው መናብርት አመነ ስገዱለትም በአምስተኛው ዕለት ኃይላትን አስተማራቸው እነሱም ከኛ የለበሰውን ሥጋ ይዞ ሲያርግ በማየታቸው ጌታቸው መሆኑን አምነው ወደሱ ሰገዱ ።'),
  ('bec76c3c-fa29-54fd-a094-fd830aaa01da', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 26, 26, 'በስድስተኛው ቀን ሊቃናትን አስተማረ እነሱም ወደሱ ሰገዱ እሱ ጌታቸው መሆኑንም አመኑ ከኛ የለበሰውን ሥጋ ለብሶ አይተውታልና በስድስተኛው ዕለት ኪሩባውያንን አስተማረ። እነሱም እሱ ጌታቸው እንደሆነ አውቀው ሰገዱለት አመኑም የለበሰውንም ሥጋ አዩ።'),
  ('d9395ee3-6ebb-5ac6-a854-dcf476c1563d', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 27, 27, 'በስምንተኛው ቀን ሱራፌልን አስተማራቸው እነሱም ጌታቸው እንደሆነ አመኑ ሰገዱለትም።'),
  ('0a1f1f54-19c0-5fa8-a0e6-7b125a2d4da7', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 28, 28, 'በዘጠነኛው ቀን መኳንንትን አስተማራቸው እነሱም አመነ ሰገዱለትም ከለበሰው ሥጋ ጋር አይተው ጌታቸው መሆኑን አውቀዋልና።'),
  ('3e36716f-2eb9-5972-a37b-f8b959f34fc7', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 29, 29, 'ሊቃነ መላእክት በየነገዳቸውና በየማደርያቸው በየወገናቸው ሁነው ከዚያ ከኛ ከነሳው ሥጋ ሁኖ ሲያርግ አስተማራቸው ካስተማራቸውም በኋላ በአሥረኛው ቀን በመለኮቱ ተቀመጠ ባባቱ ቀኝም ተቀመጠ ከዚሁ ቀጥሎ በዚሁ ዕለት መንፈስ ቅዱስን ላከልን እሱም ይመራናል ጥበብንና የአእምሮን መንፈስንም ያሳድርብናል።'),
  ('d3e39743-346c-5259-a146-90f0817528b5', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 30, 30, 'በመንፈስቅዱስም ያንጊዜ በብሄሮች ሁሉ ቋንቋ መናገር ቻልን ዓለምንም ሁሉ ወንጌልን እንሰብክና እናስተምር ዘንድ ተበታተንን መንፈስቅዱስም ሲወርድልን አንድ ላይ ተሰባስበን እንገኝ ነበር። የቤተክርስቲያንንም ሕግና ሥርዓት ሠራን።'),
  ('24de7626-09ea-51f7-aa73-9855812f628d', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 31, 31, 'የምናስተምረውም ሕገቦች እኛ በምንመሠርተው ሥርዓት እየተመሩ እንዲኖሩ ለቤተክርስቲያንም እንዲተጉ ቤተ እግዚአብሔርም በነሱ እንድትገለገል እናደርጋለን ሕዝቦች ለቅድስና ሥራና ለፀሎት የተጉ እንዲሆነም እናደርጋልን።'),
  ('0f423518-d003-5e71-a21c-8f0d5adbbdcc', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 32, 32, 'ከአሴር ወገን የሆነችው የፋኑኤል ልጅ ሀና ፀሎት ከማድረስ በፍፁም አታርፍም በከንፈርዋ እግዚአብሔርን ስታመሰግን ትኖር ነበር። ሐና ሌት ተቀን ከእግዚአብሔር ምስጋና አታቋርጥም ከንፈሮቿ ሲላወሱ (ሲንቀሳቀሱ) አይታይም ለመሐይምናንም እንዲሁ መሆን ይገባቸዋል መሐይምናን የሚፀልዩትም ስለነፍሳቸው ነው።'),
  ('a92f5319-caad-53d0-a372-7552befc448d', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 33, 33, 'በንፁሕ ልቦና ወደእግዚአብሔር የሚፀልይ እግዚአብሔር ለወዳጆቹ ያዘጋጀውን መልካም ሰማያዊ ሕይወትን ያገኛል።'),
  ('91f32961-cb33-551e-a288-0d7b974c0ab4', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 34, 34, 'ልጄ ቀለሚንጦስ ሆይ የምነግርህን ስማኝ የእግዚአብሔርን ቃል ችላ የሚሉ ሁሉ ከቅድስት ቤተክርስቲያን ዕድል የላቸውም ቤተክርስቲያን የሐዋርያት ስለሆነች የሰማያዊቷ ኢየሩሳሌም ምሳሌናት እሷ ሰማያዊትናትና በሷም ላይ ብርሃን ከሩቅ እንደፀሐይ ይታያል እሱም የማሕበር መድበልን ይመስላል።'),
  ('2938cd74-477e-5db2-a6fd-1050492af32a', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 35, 35, 'ነቢያት ቤተክርስቲያንን በገዳም ውስጥ ሁና አይተዋታል በተራሮች ላይ ሁናም እጅግ ስታምር ተመልክተዋታል በተለያዩ የመንፈሳዊ ክብሮችም የበላይ ትሆነን ዘንድ አደረግን ጌታችን እንዳዛዘንም በሷ ላይ ሥርዓትን ሠርተናል።'),
  ('e812650a-75a8-5617-adbb-679af78ad23e', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 36, 36, 'ጌታችን ባዘዘን መሠረትም ለሰማያዊው ሙሽራ እንድትሆን አዘጋጀናት የሷም ሽልማቶች በመጀመሪያ ነቢያት ቀጥሎ እኛ ሐዋርያት ከኛ ቀጥለው ሊቃውንትና ለቤተክርስቲያን በደሴቶች በብሄሮችና በአገሮች ላሉ ሕዝቦች ሁሉ ትሰጣለች ሕዝቦቹም በሷ ይደሰታሉ።'),
  ('7964abc1-f3e1-5014-af42-ac69b9c70788', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 37, 37, 'ቤተክርስቲያን የኛ ገንዘብናት መድሐኔዓለም ክርስቶስ በደሙ ቀድሶና በዕፀመስቀሉ ባርኮ መለመኛና መስገጃ የሐጢአትም ማስተሠሪያ ትሆን ዘንድ ሠጥቷታልና ።'),
  ('e75b35d7-fb25-5ae2-a277-679f870cc2b4', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 38, 38, 'ቤተክርስቲያን ጭንቅን ታቀላለች የተቸገረውንም ትረዳለች እኛም የሷን ሥርዓት በጥንቃቄ እንጠብቅ መንፈሳዊውም ሁሉ በሷ እንዲሟላ እያደረግን እንኑር የመንፈስቅዱስ ፍሬም በሷ እንዲያፈራ እናድርግ ይህም በመድኃኒታችን አንድ ወልደ እግዚአብሔር ምስጋና ነው እኛ በሷ እንደሰት የኛንም ሥርዓት ጠብቀው በሷ የሚኖሩ እንደኛ ይደሰቱ ቤተክርስቲያን በሕዝብ ዘንድ ናት ቤታችን አደባባይሽን ተመልከቺ በሕዝብም ደስ ይበልሽ ብሏልና በንሥሐ ሕይወታቸውን አስተካክለው የተገኙትም ሁሉ በሷ ይደሰታሉ ።'),
  ('db2422cd-1c15-59e9-a602-6a05181d045f', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 39, 39, 'ቤተክርስቲያንና በሮቿ አይታወቁም የቤተክርስቲያን በር ራሱ ጌታችን ኢየሱስ ክርስቶስ ነውና በሱ አማካይነት ወደቤተክርስቲያን ይገባል በሯም እሱ ነው ቤተክርስቲያን መንግሥተሰማያት ናት የእግዚአብሔርን ትእዛዝ እየጠበቅን በሷ እንኖራለን።'),
  ('0da457fd-53eb-538d-a3db-5ab7402ad49d', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 40, 40, 'እሱ ራሱ እውነተኛ በር እኔነኝ ብሏል በኔ በኩል ካልሆነ ከአብ ዘንድ ማንም አይደርስም እኔን የሚያውቅ አባቴንም ያውቀዋል እኔን የላከኝ እሱ ነውና እሱ የንፁሐን የማደርያቸው ነው በር እኔነኝ ብሏል ወደኔ የገባ የሚሰማራበትን ያገኛል እየተደሰተም መካ ይገባል።'),
  ('c91b653e-851a-5e61-ad86-905b7736efe8', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 41, 41, 'ደግሞም የዕውራንን ዓይን የማበራ እኔነኝ በትርም እኔነኝ አጋንንትም እያረገፍኩ አባርራቸዋለሁና የአሳማ መንጋዎችንም ወደ ባሕር አሰጥማቸዋለሁ አለ።'),
  ('41fcff81-3889-58e4-a9e3-ca5e55f5d021', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 42, 42, 'እንዲህም አለ እኔ ሕይወት ነኝ አልአዛርን መቶ ከተቀበረበት በዐራተኛው ቀን አስነሳሁት የሕይወት ዕፅ እኔነኝ የወይን ቦታም እኔ ነኝ ። ውሃውን ወይን አደረግሁት በሠርግ የተሰበሰቡትም ብዙ ሕዝብ ከወይኑ ጠጥተው ረኩ የሕይወት እንጀራም እኔ ነኝ ። ከሰማይ የወረድኩ የሕይወት እንጀራም ስለሆንኩ በአምስት እንጀራ አምስት ሺ ሰቦችን አጠገብኩ።'),
  ('3b9fb881-47a7-570a-a97c-a748738d10f9', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 43, 43, 'የውሃምንጭ እኔ ነኝ ። የተጠማ ይምጣና (ወደኔ) ይጠጣ የእውነት ፀሐይም እኔ ነኝ ። የኔ ፀሐይነት በአማንያን መሐይምናን ልብ ውስጥ ያበራል ፀሐይዋስ ወጥታ ትጠልቃለች ክርስቶስ ግን የማይጠፋ ፀሐይ ነው።'),
  ('05c46d80-fdfb-554f-a602-889ac86cb40f', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 44, 44, 'ደግሞም እንዲህ አለ መድሐኒትና ሕይወት እኔ ነኝ ። ልቡ የጨለመበትን ሰው የማበራለት እውነተኛ ፋና እኔ ነኝ ። ትእዛዜን የሚጠብቁ፡ ሁሉ ልቡናቸው ይበራል ዲያብሎስ ትእዛዜን እንዳይጠብቁ ይፈታተናቸዋል።'),
  ('a291aafb-b163-579e-a858-e89152c712db', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 45, 45, 'እንዲህም አለ ህይወት እኔ ነኝ ። እኔን የሚያምን ቢሞትም እንኳ ይድናል እኔም በኃለኛዋ ዕለት በክብር አነሳዋለሁ እናንተም ትእዛዜን ጠብቁ እናንተ የቤተክርስቲያን አለቆች ትእዛዜን ጠብቁ የጨለማንም ሥራ እንዳይሠሩ ነፃ አውጡአቸው የጨለማ ስራ ወደሞት ይመራል ሞትም ወደሲኦል ያወርዳል።'),
  ('3dee1b9b-fcc6-5673-ac93-1720f15c3b1c', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 46, 46, 'ልጄ ቀሌሚንጦስ ሆይ አንተም ጠብቅ ህዝብም ከዝመት እንዲጠበቁ ንገራቸው ገዝመት ነፍስንና ሥጋን ያረክሳል ስለዚህም ወንድማችን ጳውሎስ በስተውጭ ሐአትን የሚሠራ ሰው በሥጋው ከፍተኛ በደልን ይፈፅማል ብሏል የመሐይምናን እናታቸው ቅድስት ቤተክርስቲያን ስትሆን አባታቸው እግዚአብሔር ነው ።'),
  ('a1aa6703-53cc-50ca-a4b9-6101272d6a17', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 47, 47, 'ሁላችን ክርስቲያኖች የክርስቶስ ሥጋና ደም ተቀብለናል ስለዚህ ሁላችን ወንድምና እህት ነን ይህ ሁኖ እያለ ወንድሞች ከእህቶች ጋር ሥጋቸውን ማርከስ ይገባልን ባንድ ቃልኪዳን በመሆን ለመጋባትና ለመዋለድ ሲባል ከዝሙት በራቀመንገድ መገባት ተፈቅዷል።'),
  ('64a0014b-1c37-5624-a188-74eb74f7eee9', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 48, 48, 'ስለዚህ እግዚአብሔር ዝሙትን ጠላ ህዝቦች በቅድስት ቤተክርስቲያን ብቻ እንዲፀኑ እንድናስተምራቸው አዞናል ። ዝሙትን የሚወዱ እንዳይሆነ እናስተምራቸው ፍቅረዝመትና ፍቅረ መብል ወደሠይጣን ወጥመድ የሰውን ልጅ ታስገባለች።'),
  ('da2819d2-d342-5ed5-a7cd-624bbe9ec206', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 49, 49, 'በመብል ፍቅር አባታችን አዳም ከወጥመድ ገባ ወደተረገመችም ምድር እንዲወርድ ተደረገ ስለአዳም ምድር ተረግማለች ስለዚህም እግዚአብሔር ከልዑል መንበሩ ወደምድር ወረደ ከቅድስት ድንግል ማርያምም ስጋ ለብሶ ነቢያት እንደሰብኩት በቤተልሔም ተወለደ።'),
  ('2dc0af50-202f-577d-adaa-e3097e9634fd', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 50, 50, 'በምድር ተመላለሰ በግልዕም ታየ ጥምቀትንም ለሐጢአት ሥርየት አስተማረ በካህን ዮሐንስ እጅ ተጠመቀ ከዚያውም በኋላ በሽተኞችን ፈወሰ የዕውራንንም ዓይን አቦራ አንካሳዎችንም አዳነ ለምፃሞችን ከለምፃቸው እንዲነፁ አደረገ መስማት የተሳናቸውንም እንዲሰሙ አደረገ ዲዳዎችን አናገረ ባሕርንም ዳሰሳትና ሰዎች በየብስ እንደሚጓዙ ተጓዘባት ።'),
  ('4134470b-99e4-5cbe-a561-e57f6a8e3f8d', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 51, 51, 'አልአዛርን ከመቃብር አስነሳው ነገር ግን አይሁድ ብዙ ሕዝብ ከሚጠፋ አንድ ሰው ቢሞት ይሻላል እስከማለት አመት ይህን የነሱ ሊቀካህናት የሆነው ቀያፋ ይህንን ትንቢት ተናገረው ቀያፋ ትንቢት እናገራለሁ በማለት የተናገረው ሳይሆን ጌታችንን ለመግደል ብሉ ነው በሁለተኛው መንገድ አይሁድ ይህ ጥበብ ከማን ተሠጠው የጠራቢው ዮሴፍ ልጅ አይደለምን በማለት አሙት።'),
  ('71cdf8ca-44c2-5a06-a9a7-601be263e766', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 52, 52, 'እናቱ ከይሁዳ ነገድ የሆነች ማርያም ናት እኛ ግን ሌዋውያን ነን ስለዚህ ላበታችን ሌዊ ክህነት ከእግዚአብሔር ተሠጥቷል እኛም ወደ ቅድስተ ቅድሳት እየገባን ግብረ ክህነትን እንፈፅማለን ለዚህ ሰው ክህነት ከማን ወገን ተሠጠው አሉ ስለሰንበትም ብኑ ክርክር አነሱበት እንዲህም አሉ ይህ ሰው ከእግዚአብሔር የተላከ አይደለም በመሆነም ሰንበትን አያከብርም ህገኦሪትንም አይጠብቅም አሉ ጌታችን ኢየሱስ ክርስቶስ ግን በሰንበት ሥራውን እየሠራ ያስቆጣቸው ነበር።'),
  ('2add15dc-e364-5016-a68c-5564b9f94497', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 53, 53, 'ቅድስት ኦሪት እግዚአብሔር ሥራውን ሁሉ ፈፅሞ በዕለተሰንበት ዕረፈ ትላለች ይህም ሰባተኛው ዕለት ነው ሰንበትን ይሠራ በመጣጊዜ ግን ዕዳዋን ከፍሏል ሥራዋንም ትሠራለች በዚችው ዕለት ሥራውን ሠራ በዚሁም አይሁድ ጌታችን ከመጣ ጀምሮ በጭቃ ዓይነሥውሩን አዳነ።'),
  ('463befec-d507-59bf-abe1-7add6521d854', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 54, 54, 'በሰንበት ዕውርን አዳነ ሰላሳስምንት ዓመት የታመመውንም በዕለተሰንበት አዳነው ጋነን አድርባት የታመመችውንም ሴት በእለተ ልጅ ሰንበት አድኗታል። የኢያኤሮስንም ሴት በዕለተሰንበት ከታመመችበት በሽታ አድኗታል።'),
  ('975bc12a-9361-5c3c-ae6c-ff694e90a3f7', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 55, 55, 'ብዙ ተአምራትን መንክራትን በሰንበት አድርጓል ይህንንም በዕለተ ሰንበት ሥራን መሥራት (መልካም ሥራን መሥራት) እንደሚቻል አረጋገጠ። በመጀመርያ ሰማይንና ምድርን ሲፈጥር ሰንበትን ከፍ አድርጓታል አይሁድ ስለሰንበት በተከራከሩት ጊዜ እሱም እንዲህ አላቸው አባቴም ምሕረትን ያደርጋል። እኔም የአባቴን ሥራ እሠራለሁ በዚህ ጊዜ አይሁድ እጅግ ተቆጡት በዚሁም ክቡሩን አምላክ በገንዘብ አሳልፈው ሰጡት።'),
  ('cb84b94b-415a-565e-a71a-770fe683720f', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 56, 56, 'በወንጌል እንደተፃፈው አይሁድ ያዙት ስለኛም ሐጢአት ተሰቀለ በሦኛው ዕለትም ተነሳ ሥርዓቱንና ህጉንም አስተማረን ከዚያ በኋላ ማመዓልትና ፵ሌሊት ከኛ ጋር ኖረ።'),
  ('4b1a8dcb-914b-531e-a3f7-a2adae1cba62', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 57, 57, 'ጌታችን እንዲህ ሲልአስተምሮናል ሥርዓቴን ጠብቁ አስተምሬአችሁ አለሁና ልብ ብላችሁም እንድትረዱት አእምሮአችሁ ከፍየላችሁ አለሁና ሰነፎችን ልባሞች አድርጉዋቸው ያዘነትንም አስደስቱ ሐጢአተኞችን አዕድቁ የወደቁትን በንሥሐ መልሱ። ያዘነትንም አስደስቱ ሐጢአተኞችን አፅድቁ የወደቁትን በንሥሐ መልሱ ያዘነትን አጽናኑ አረማውያንን አስተምራችሁ ወደክርስትና መልሱ።'),
  ('27fd2c69-6865-59c4-a251-f29a2f13ec9c', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 58, 58, 'እኔ የሠራሁላችሁን ህግ ትእዛዝ አታቃልሉ እኔ እስከዓለም መጨረሻ አልለያችሁም ቃሌንም በሚሰማችሁና በሚከተላችሁ ሁሉ አኖራለሁ አባቴ ያልሳበው ወደኔ ሊመጣ አይችልም የሕይወትን ቃል ሰምቶ የሚሄድ ይኖራል እናንተ የምትሰብኩት የመለኮት ቃልነው። የናንተን ቃል የማይቀበል ካለ ወደሲኦል ይወርዳል።'),
  ('bb2e7f0e-1838-57a6-ad96-7455b929d9c4', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 59, 59, 'ሕጌን ጠብቁ ከሥርአቴ የምታቃልሉት አይኑር በቅድስት ድንኳን ይህ አድሬ እናንተን የማፅናናበትን ኃይሌ ሠርቻለሁ እሷ መነፀኛና የሐጢኣት ሥርየትን መሥጫ ናት።'),
  ('0f600b7b-c10e-5552-ae81-d22db2fae067', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 60, 60, 'እሷ ጭንቅን ታቃልላለች የተቸገረውንም ትረዳለች እሷ እንግዳን የምትወድ ናት ለለመነ ይቅርታን ታሠጣለች የደስታ ማደርያ ናትና ።'),
  ('0dcbd875-d507-5785-a961-cb4ce0d3d967', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 61, 61, 'እሷን የሚመረኮዙ አይፍገመገሙም መሠረቷ የፀና ነውና የፀናውም በኢየሱስ ክርስቶስመስቀል ነው እሱ በደሙ አድኗታልና በዕፀመስቀሉም ባርኳታልና የሐጢአትማስተሠርያ ትሆን ዘንድ ።'),
  ('b69db8da-bdba-5e41-a6a5-8a643dd38e51', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 62, 62, 'ልጄ ቀሌሚንጦስ ሆይ የሠጠሁህን ሥርዓት ለቤተክርስቲያን ሹማምንት በአደራነት አስረክባቸው እነሱም በዚሁ እየተመሩ ቅዱሱን የእግዚአብሔር ሥርዓት ይጠብቁ ይህሥርዓት በእውነተኛው ድንኳን ተሠርቷል እቺም ድንኳን በሰማያዊቷ ኢየሩሳሌም ትመሰላለች ሰማያዊቷ ኢየሩሳሌም አእለፋት አእለፈ አእላፋት መላእክት ኃይላትም ማሕበረ በኩር በሚባል የሚታወቁትም ሁሉ ለአምላክ ተገዢነታቸው የሚገልፁባት ናት የሁሉም ስም በሰማያዊቷ ኢየሩሳሌም ተፅፏል።'),
  ('1ad45813-f108-565d-a165-9899b4c2f1b0', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 63, 63, 'እቺ ሥርዓት ወደእግዚአብሔር ታደርሳቸዋለች ትዕግሥተኞች በውስጧ ስለሚኖሩ ልጆቼ ትላቸዋለች እነዚህ ትዕግሥተኞች በተቀደሰው ትጋታቸው ሌትተቀን እግዚአብሔርን ለማገልገል ይተጋሉ እነሱ እናንተ በምትሠጡዋቸው ሥርዓት ይመራሉ። በቅድስት ቤክርስቲያን አማካይነትም መንግሥተ ሰማያትን ይወርሳሉ ለአባቶቻቸው ምሎላቸዋልና ።'),
  ('0c2288a6-3d11-53f5-a207-7ba4b5977cac', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 64, 64, 'ልጄ ቀላሚንጦስ ሆይ የተመረጠውን ሥርዓት ጠብቅ ይህም ከእግዚአብሔር በእጅህ የተቀበልከው ነው እኔ የመንግሥተሰማያትን ቁልፍ ተረክቤአለሁ አንተም ይህንኑ ከኔ ትረከባለህ ይህንኑን አንተም ጠብቀህ ካንተ በኋላ ለሚነሱ የቤተክርስቲያን አስተባባሪዎች አስረክባቸው እነዚህም አንተ የበታቾችህን አድርገህ የምትሾማቸው ናቸው የቤተክርስቲያንን ሥርዓት ይጠብቁ ዘንድ አደራ በላቸው።'),
  ('db4ce18d-782c-5d37-ad11-ba049190f0e9', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 65, 65, 'እነሱም እንደሚገባ አድርገው ሕግን ይሥሩ ሕጉም ለዲያቆናት ለንፍቀዲያቆናት ለሕዝብ ለወንድና ለሴቶች ለሕፃናት የሚስማማ ይሁን እነሱም በእውነት መንገድ ይራመዱ። ሐዋርያት ለቤተክርስቲያን ሥርዓትን ሠሩ። ይህም እኛ ባዘዝነው መሠረት የተሰራ ነው ይህ ሥርዓት ይወጣ ዘንድ አስቀድመን አዘናል ባወጣነውም ህግ መሠረት የጳጳሳት የካህናት አለቆች የቀሳውስት የዲያቆናትና የአናጉንስጢስ የመቆምያ ቦታ ወስነናል።'),
  ('e00c0a26-465d-5174-af9b-b11c1353236c', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 66, 66, 'እንዲሁም ለሕዝባውን ለሽማግሌዎች ለሕፃናትና ለተመሰገነ ሴቶች ለደናግል ለመዓስባን ባልቴቶችን የሙት ልጆችን ዲያቆናዊቷን ሌሎችም ቤክተርስቲያንን የሚጠብቁትን መቆምያቸው እየራሳቸው እንዲሆኑ ይገባል።'),
  ('0711597c-14ed-5392-a092-f49ac9853e05', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 67, 67, 'ዲያቆናት የክርስቲያኖችን የመኖሪያ ቤት ወዳለበት ሁሉ እየዞሩ የተቸገሩትን ሁሉ ይጎብኙ ችግራቸውንም ይመልከቱ ጥዋትም ሆነ ማታ ምእመናኑ በስንፍና እንዳይያዙ ለመንፈሳዊ አገልግሎት እንዲተጉ ያነቃቁዋቸዋል። በሠርክ በጧትና በማታም ወደቤተክርስቲያን ሁልጊዜ እየሄዱ ያመስግኑት እግዚአብሔር የዕለት ብርሃን ነው ሁሉንም ይረዳል ።'),
  ('5c7dcc19-cc4b-5fb8-a1c4-8a3495f2b8db', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 68, 68, 'በንጋት እግዚአብሔርን ያመስግኑት የሌሊቱን ጨለማ ስላሳለፈ ዕረፍትንም ስለሠጣቸው ንጋት በትንሣኤሙታን ትመስላለች እንቅልፍ ደግሞ በሞት ትመሰላለች ።'),
  ('7149a19c-34fa-5c45-abef-1440a35a2950', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 69, 69, 'ስለዚህ ክርስቲያን ጧት ማታ ወደቤተክርስቲያን ይገሰግሱ ዘንድ በቀኖና አዘናል ክርስቲያን ጧት ማታ ቀንና በየሰዓቱ ወደቤተክርስቲያን መገሥገሥን እንዳያቋርጡ ስለራሳቸውና ስለሹማምንት። ስለባልንጀሮቻቸው። ስለባሕር። ስለወፎች። ስለእንስሳትና እግዚአብሔር ስለፈጠራቸው ፍጥረታት ሁሉ በትጋት ያለስንፍና በአንቀዕድዎ ያለቸልተኝነት እንዲፀልዩ አዘናል።'),
  ('24f2a16b-6edd-5a11-a8cf-99d2457bb9e4', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 70, 70, 'ይህን ትእዛዝ የተሠጠው ክርስቲያኖች ስለራሳቸውና ስለባልንጀሮቻቸው እነዲጸልዩ ነው ጧትና ማታ ወደቤተክርስቲያን ሲሄዱም ባንድልብ ባንድ ሐሳብ በመሆን ፍቅርን በማፅናት ነው ትሕትናም ይኑራቸው የስብቀት ነገርንም አይስሙ ።'),
  ('327d0b02-3530-5827-af0c-965fff1154d6', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 71, 71, 'ክርስቲያን በራሱ ላይ በደል ቢደርስበትም አጥፍቼአለሁ ይቅርበሉኝ ይበል ይህ አካሄድ በክርስቲያኖች የተለመደ መሆን አለበት ሰዎች በሱ ላይ ዘለፋ ቢያሰሙ እንኳ እንደበደለ ሁኖ ይቅርታን ይጠይቅ ጌታችን ኢየሱስ ክርስቶስ በግብር ይህንን አስተምሮናል ።'),
  ('a5286628-b8a2-51e7-a201-10c94468086f', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 72, 72, 'እሱ የቤተክርስቲያንን ህግ ፈፅሟል እኛም እሱን መሠረት አድርገን የቤተ ክርስቲያንን ህግ ሠርተናል ህጉም እግዚአብሔርን አምነው በቅድስት ቤተክርስቲን የድካማቸውን ዋጋ ይሠጣቸው ዘንድ ይህን ሠርተናል ።'),
  ('d17e4889-8eb5-525c-a7eb-dffdc6ae5d60', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 73, 73, 'በሰማያት ተሰፋ ያገኝ ዘንድ በዚህ ዓለም ሕመምንና ችግርን የሚታገሥ ስለሱ የቤተክርስቲያንን ቀኖና ሠርተናል።'),
  ('d8dc4f38-21e9-542d-a4e9-39340c057755', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 74, 74, 'በባለእንጀራው ላይ በደል የፈፀመ ካለ የባለንጀራውንም ገንዘብ የቀማ ካለ ወይም አልወሰድኩም ብሉ ከካደ በአደራነት የተቀበለውንም የካደ ቢኖር ለባለንብረቱ ዕጥፍ አድርጎ ይክፈል ማንም ክርስቲያን ግን በዚሁ መገኘት የለበትም ።'),
  ('ffda484e-0b21-59cd-a54a-3132b8c15c18', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 75, 75, 'በቅድስት ቤተክርስቲያን ማሕበር የታዘዘው ክርስቲያን ራሱን ከፍ እንዳያደርግ ነው በባለንጀራው ላይ እንዳይታበይ የተከዙትን እንዲያስደስታቸው ሐዘንተኞችን እንዲያፅናናቸው ሰላምንና ፍትህን በመካከላቸው እንዲያሰፍን የተቸገሩትን እንዲረጻ በዐመፁ የባለንጀራውን ንብረት የማይቀማ ይሁን ።'),
  ('acdf7df3-1335-5b2e-ad9d-528b3a0eb046', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 76, 76, 'ካንተ በታች ላሉ የቤተክርስቲያን ሹማምንት ይህን እንዲፈዕመ እዘዛቸው። ከሁሉ በላይ ወደሆነችው ቅድስት ቤተክርስቲያን ለሚሄዱ ሁሉ ጎብኛቸው ደስም አሰኛቸው የታመመች በግም ብትኖር አትናቃት እጅና እግሮቿም ቢሠበሩ አሥረህ እንድትጠገን አድርግ የጌታህን ግልገል አታጥፋ ።'),
  ('4d54d784-f9be-5c81-a4ba-8af8850f86f8', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 77, 77, 'የታመመችውን በግ በትከሻዎችህ ተሸክመህ በመውሰድ ወደጌታህ ቤት አድርሳት ከጤናማ በጎችም ለመጨመር ህክምና አድርግላት የቆሰለውን አካልዋ በወይንና በጨው እጠበው የሚያስፈልገውም ከሆነ ብጣው እንደገናም ጨውንና ወይን በቁስሉ ላይ አፍሥስበት በጨውና በወይን በሽታ ሁሉ ይነቀላል። እቺ የታመመች በግ ስትድን ለጌታህ መዝገብ የምታስገባውን ፍሬ አታውቅም ።'),
  ('e5e11b6e-7f8f-57a7-ab85-15d951ce6545', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 78, 78, 'የሰው ሕይወት ጣዖትን በማምለክ ብትደክም ከሐጢአት አንፃት በንሥሐም አካሄድዋን እንድታስተካክል አድርግ ለጌታህ እግዚአብሔር መዝገብ ንፁሕ ሥንዴ ሁና እንድትቀርብ በክሕደት ይሁን በእምነት በፆም ይሁን በጸሎት በማነኛውም ሁኔታ ብትገኝ በተሠጠህ ሐላፊነት ከእግዚአብሔር ጋር ያላትን ግንኙነት እንድታስተካክል አድርግ ከነፍስ ሕመም ፈውሳት በዚህ ጊዜ ንፁሕ ስንዴ ሁና ወደጌታ መዝገብ ትገባለች እንክርዳድ ሁና ወደእሳት አትጣልም ።'),
  ('28c1347c-0028-598d-a9ed-b0dc7090fbd1', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 79, 79, 'እንክርዳድ ማለት በንሥሐ ወደቅድስት ቤተክርስቲያን የማይመለስና በሷ እየተመራ የእግዚአብሔር ቤተሰብ ለመሆን የማይፈልግ ማለት ነው። አንተ ግን የቤተክርስቲያንን ዕለቆች የሕዝብን አለቆች ይመክሩዋቸውና የእግዚአብሔርን አካሄድ ለሕዝብ ያስተምሩ ዘንድ እዘዛቸው የሕዝብ አለቆቹም ሳይፈሩ በጥብአት ነገሥታቱንና መኳንንቱም ያስተምሩ ።'),
  ('de89d53d-41d5-5c66-a639-902a82964edf', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 80, 80, 'በህግ የተሠራላቸውን ምዕመናን ይከተሉ ዘንድ ንገሩዋቸው አስረዱዋቸውም አንተም ልትሠማው የሚገባህን የእግዚአብሔር ቃል ከመስማት ወደኋላ አትበል። የቤተክርስቲያን መሪዎች የሚሠጡህን ትምህርት በትሕትና ተቀበል ሰውን አትፍራ ትዕቢትና ትዝሕርት አይደርብሕ እግዚአብሔር እንዳይቆጣህ ቂምን በልቡናህ አትያዝ ነፍህን ለማዳን ከመምህራን ስለሚደርስብህ ተግሣፅ ቅሬታ አይኑርህ።'),
  ('27c824b7-eb1d-50b0-a3e1-7d1896e9db48', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 81, 81, 'አንተ ንጉሥ ብትሆን ባለህ የመንግሥት ሥልጣን ልክ ቃለእግዚአብሔርን ውደድ ይህ ከሆነ ነው መምህራን የሚነግሩህን ልትረዳ ምትችለው ሥልጣን አለኝ ብለህ መምህራንን ችላ አትበላቸው እንደነፍስህ ውደዳቸው እንጂ። በምድራዊ ሥልጣንህም አትክበዳቸው እግዚአብሔር በመዓቱ እነዳይቆጣህ።'),
  ('93fad058-467a-5bbf-ac25-a0ef07332631', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 82, 82, 'ነፍስንና ሥጋን አንድ ላይ የሚኮንነውን ፍራው ከመምህራን የተነገረህን ቃለእግዚአብሔር አታርቅ ቃለእግዚአብሔርን ችላ የሚል ሁሉ ዕድሜው አጭር ይሆናል እግዚአብሔርም የገዛራሱን መጥፎ ንግግር በአክአብ በሳኦልና በኦዝያን ላይ እንደፈፀመው ሁሉ ያደርግበታል።'),
  ('bbc4011e-c2ef-5f34-ad98-0c56218987b2', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 83, 83, 'እነሳኦል ከእግዚአብሔር የተሠጣቸውን ሥልጣነ መንግሥት እንደግል ሥልጣን በመቁጠር ቃለእግዚአብሔርን ችላ አሉ ምግባራቸውን አላሳመሩም ከፍ ያረጋቸውን እግዚአብሔርን ችላ አሉ ምግባራቸውን አላሳመሩም ከፍ ያደረጋቸውን እግዚአብሔር ራሱ የበታቾቻቸውን በቅንነት አልመሩም እግዚአብሔር ግን አደራነትን ሠጥቶአቸው ነበር።'),
  ('0a16d936-5354-5e7b-a899-96d0288b78f0', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 84, 84, 'በአደራነት የተሠጡዋቸውን የእግዚአብሔር መንጋዎች ካጠፉ በሐላፊነት እግዚአብሔር ይጠይቃቸዋል። ነፍሳትንም በከንቱ ካጠፉ ዕዳቸው ብዙ ነው በዋነኛነት ነፍሳትን የመጠበቅ ሐላፊነት ያላቸው ግን ጳጳሳት ናቸው።'),
  ('f5d40d5a-62b5-5278-ab28-9e44598d24b5', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 85, 85, 'ንጉሥ ሆይ አንተ ሥጋዊውን ሥራ ትጠብቃለህ ስለዚህ አንተና ጳጳሱ የእግዚአብሔር በጎች እንዳይጠፉ ተግታችሁ ጸልዩ ።'),
  ('4da9ef6e-87d3-515f-a422-35a461319548', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 86, 86, 'አንተ ንጉሥ ከመልካም አያያዝ ጋር ሰዎችን ከሚታገሉዋቸውና ፍርድን ከማይጠብቁ ትዕቢተኞች በፅናታቸውም ከሚታበዩ አድናቸው።'),
  ('3a7af4b9-b3bc-5d71-ae65-d5927977f2ae', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 87, 87, 'ንጉሥሆይ ከበደለኞችና ከሐጢአተኞች እጅ ባልቴቶችንና የሙትልጆችን አድናቸው። ከሊቃነጳጳሳት ጀምሮ ያሉ በውስጣቸው ያሉትን ሙት ልጆች ያስተዳድሩ ዘንድ ድጋፍን አድርግላቸው። ለሠይጣን እንዳይሸነፉም አበረታታቸው። ጳጳስ ሆይ ከዲያብሎስ ጠብ ምዕመናንን አድናቸው በዚህ እግዚአብሔር ደስ ይለዋል እግዚአብሔር መንጋዎቻቸውን ስለጠበቁ ደስ ይለዋል።'),
  ('e4d0a2e4-7262-51e0-a31f-7c2e2be4173e', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 88, 88, 'መንጋዎቻችሁን ጠብቁ ይህንንም ቃል እየሰማችሁ ለመጠበቅ ትጉ። የእግዚአብሔርን መግቦት ችላ አትበሉ እናንተንም የሚመግብ እሱ ነውና መጋቢነታችሁም ችላ አትበሉ። ይህንን ባታደርጉ እግዚአብሔር በኃላፊነት ይጠይቃቹኋል ባለማስተማራችሁና ባለመገሠፃችሁ የሚሰሙአችሁንም ባለማስተማራችሁ ይሰቀላችኋል።'),
  ('3a60131e-c178-5ef0-a2df-9b0a2cc23a62', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 89, 89, 'ትምህርታችሁን ሰምተው ያመኑትን መልሳችሁ ወደቤታቸው አትላኩዋቸው ወደአረማውያን ቤተሰቦቻቸውም አይጨመሩ ሃይማኖታቸውን እንዳያጠፉ ሃይማኖታቸው እስክትፀና ድረስ በቅርብ እየተከታተለችሁ አፅኑዋቸው እንጂ በፍጥነት ወደዘመዶቻቸው ከሄዱ ግን እምነታቸውን ዘመዶቻቸው ሊያበላሹባቸው ይችላሉ።'),
  ('5da90d25-5a67-5b0f-a085-7c4afff5151f', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 90, 90, 'አንተ ቃለእግዚአብሔርን ሰምቶ ካመነ በኋላ ወደአረማዊያኑ ቤተሰቦቹ መልሰህ ከላክከው ከቀድሞ በበለጠ ክህደቱ ሊብስ ይችላል።'),
  ('8f2b877a-786c-5d7c-ac73-ca685c616ec4', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 91, 91, 'በወንጌል በእግራቸው እንዳይረግጡት ተመልሰውም እንዳይነክሱአችሁ የተቀደሰውን ለውሾች አትሥጡ ዕንቁዎቻችሁንም በእርያዎች ፊት አትጣሉ ተብሎ ተፅፏል። ያሳመናችሁዋቸውን ሰዎች መልሳችሁ ወደቤተሰቦቻቸው አትላኩ። ከሐዲማለት ያለህግ በአመንዝራነት የሚኖር ሰው ማለት ነው።'),
  ('4dda93f5-49f9-5f8f-adb9-6f33606e1bad', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 92, 92, 'አረማውያን የባለእንጀራቸውን ገንዘብ እንደውሾች ይናጠቃሉ አሳማዎች የተባሉትም ህግ የለሾች ሁነው የረከሱ አለማውያን ናቸው እነዚህ የድሕነት ተስፋ ፈፅሞ የሌላቸው ናቸው ጌታችንም ለፍርድ ያቀርባቸዋል። የነሱ ነፍስ ከሥጋዋ እንደተለየች ወደኩነኔ ትወሰዳለች።'),
  ('5cd17bfa-ff6a-5cb3-a038-6745a6dd7a23', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 93, 93, 'ስለዚህም ረሲአን ከደይን አይነሱም ሐጢአተኞችም ከፃድቃን ምክር አይጨመሩም ከዚህም በተነሳ ጌታ በተቀደሰው ቦታ አያቆማቸውም የመዳንና ምሕረትን የማግኘት ዕድልም የላቸውም ።'),
  ('b48949e6-5460-597a-ab95-bcb9c7c2374d', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 94, 94, 'እነዚህ ህግ የለሾች ወገኖች ተስፋቸውንና ተድላደስታቸውን ሥጋዊ ስሜታቸው በሚመራቸው ብቻ እየተመሩ በምድር ጨርሰዋል በፈቃዳቸው እንጂ በፈቃደእግዚአብሔር አይሄዱም ስለዚህ ፍዳ መከራና ሀዘን ብቻ ይጠብቁዋቸዋል እንጂ ወደቅድስና አይገቡም።'),
  ('ca0c16cf-b0f8-5ac8-ae96-cbc3d0ddbf42', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 95, 95, 'የቤተክርስቲያን አለቆች ሆይ ከእግዚአብሔርና ከኛ የተረከበችሁትን ሥርዓት ይዛችሁ ለመጓዝ ትችሉ ዘንድ።'),
  ('112c1ffa-183a-5882-aeaa-1d87b8b47f66', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 96, 96, 'ሰዎች የቤተክርስቲያንን ሐብት ለግላዊ ተግባራቸው እንዳያውሉ በቀኖና ቤተክርስቲያን ተወስኗል ከማንኛው የቤተክርስቲያን ኅብት በፈቃዳቸው አይውሰዱ የቤተክርስቲያን ገንዘብ የእግዚአብሔር ገንዘብ ነው ከቤተክርስቲያን ሹማምንት ፈቃድ ውጭ ገንዘብን የወሰደ እግዚአብሔርን ችላ ብሏል።'),
  ('d8bc8c65-260b-5e8e-a4f2-e304d88033cb', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 97, 97, 'የቤተእግዚአብሔርን ንብረት የሚቀስጥ ሰው ከዚች ምድር ዘር አልባ ሁኖ ይነቀላል። በሰማያዊው ዓለምም እስከ ዘለዓለም ከማይወጣበት ገሐነም ይከተታል የቤተክርስቲያን ሹማምንት ገንዘቡን የት አደረሱት ተብለው መታማት የለባቸውም እነሱ የተቸገረውን እያዩ ይረዱበታልና የቅድስት ቤተክርስቲያን ኃላፊነት በሙሉም ከነሱ ራስ ላይ ነው የተጣለው ።'),
  ('f767eaf8-51d3-5df3-acfb-71446f552132', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 98, 98, 'እግዚአብሔር የመንግሥተ ሰማያትን ቁልፍ የሠጠው ካህን በዚህ በሚያልፈው ዓለም ገንዘብ እንዴት አይታመንም ።'),
  ('7c17e0d0-89b7-5975-ab2b-52df711ce57c', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 99, 99, 'የቤተክርስቲያንን ሥርዓት በውስጥም ሆነ በውጭ በነፍስና በሥጋ በድብቅ የሚሠራው ሁሉ ሙታንንና ሕያዋንን ሊገዛ ክርስቶስ በተገለጠ ጊዜ በሠርጉ አደባባይ ደስተኞች ሁናችሁ እንድትቆሙ ያደርጋቹኋል።'),
  ('b0fea79b-7b3f-5b3e-affd-599152434aeb', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 100, 100, 'ክርስቶስ ለፃድቃን የድካማቸውን ዋጋ ይሠጣቸዋል ለሐጥአን ደግሞ የሱ ፈቃድ ሳይፈፅሙ ቀርተዋልና የሐጢአተኝነት ዋጋቸውን ይከፍላቸዋል ግራና ቀኝ ሳትሉ እኛ ሐዋርያት ያዘዝናችሁን ሁሉ ፈፅሙ።።'),
  ('3f440ac1-5b46-5765-ab76-bee3775edd74', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 101, 101, 'በተቀደሰችው ድንኳን ሊፈፀም ያለውን ሥርዓት አፈፃፀማችሁ ካልተስተካከለ እግዚአብሔር ይወቅሳቹኋል እኛ ያዘዝናችሁን ሁሉ ከፈፀማችሁ ግን ጌታችን ኢየሱስክርስቶስ በገባልን ቃል መሠረት ከሱራፌል መንበር ተቀምጠን ስንፈርድ ከበታቾቻችሁ ላይ አብራችሁን ትፈርዳላችሁ።'),
  ('24d4720f-ae5a-51a5-abab-669c7395ee89', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 102, 102, 'የናንተን ትምሕርት ሰምተው ለማይመለሱ የነደእሳት ኩነኔ ይጠብቃቸዋል ይህም እስከዘለዓለም ነው እናንተ ግን ከናንተ በታች ያሉትን ከማስተማርና ከመንገር አትቦዝኑ እናንተም አመራራችሁን አስተካክሉ ይህንንም እስከዕለተሞታችሁ የፀና ይሁን በሙሽራው ሠርግ ደስተኞች ትሆኑ ዘንድ ።'),
  ('78950fd0-c2f9-5d1e-ae60-b41e35073984', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 103, 103, 'በዛንጊዜ እኔ እግዚአብሔር ከሰጠኝ ልጆቼ ጋር በመሆን አለሁ ትላላችሁ ከመንፈሳውያን ልጆቻችሁ ጋርም ትደሰታላችሁ በመንግሥተስማያት በዛን ጊዜ እናንተ እነሱና እኛ በሕብረት እግዚአብሔርን እናመሰግነዋለን እናንተ የቤተክርስቲያንን ሥርዓት መሠረት አድርጋችሁ ከተመራችሁ ባለቤቱ ይረዳቹኋል።'),
  ('2dcb3d5d-d832-5089-a2e6-5a2b152d5586', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 104, 104, 'ልባችሁን ንፁሕ አድርጉ ማእበል አያውካችሁ የነፋሶች ነውጥም አያውካችሁ ከአጋንንት ሐይልም ተጠበቁ ከዚሁም አልፋችሁ ከሚታየውም ሆነ ከማይታየውም ሁሉ ተጠበቁ።'),
  ('008d07cf-cf4c-5228-a440-3e9a02f98d84', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 105, 105, 'ከእግዚአብሔር እምነት ውጭ የሆነ ፍርሐት መቅሠፍትን ያስከትላል (ከእግዚአብሔር ዘንድ) ጥቅምን የሚያስገኘው እግዚአብሔርን መፍራት ብቻ ነው። እግዚአብሔርን የሚፈራ ሰው ሊመጣ ካለው ጥፋት ሁሉ ይጠበቃል ጥፋት በተግባር በቃል በሌላም የዚህን ዓለም ሁኔታን በማሰብም ይመጣል።'),
  ('a5bbbfc5-5089-5233-a8de-f3111e0583ef', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 106, 106, 'አንተ የእግዚአብሔርን ፈቃድ ለመፈፀም ጥብአት ይኑርህ የሐጢአት ማሥተሥረያ ትሆን ዘንድ በደሙ ገንዘብ ላደረጋት ደብተራ ተላላኪ እንድትሆን እግዚአብሔር መርጦሀል የቤተክርስቲያን ሹማምንትንም በትዕግሥት አመካኝቶ ገና ያላደጉ ሕፃናትን የእግዚአብሔርን መንገድ ሳያውቁና ሚስቱንም የሚተው ቢኖር።'),
  ('6bc0a4f1-0303-581f-a17d-1e72b2480d3e', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 107, 107, 'ሴትም ትዳርዋን ትታ እመንናለሁ ብትልና በማደግ ላይ የሚገኙትን ሕፃናት ልጆቿን ትታ ብትመጣ የቤተክርስቲያን ሹማምንት እንዳይቀበሉዋቸው እስጠንቅቃቸው በዚህ መንገድ ከቤተሰባቸው የሚለዩ ሁሉ እግዚአብሔር ምነናቸውን አይቀበላቸውም ምነናን የፈለገ ሰው ሳያገባ በትንሽነቱ መመነን አለበት ትዳር መሥርቶ ከወለደ በኋላ ግን መመነን አይቻልም (ቤተሰቡን ሜዳላይ ማፍሰስ የለበትም)።'),
  ('f7155a63-ad55-523e-a536-b8580671b8c4', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 108, 108, 'ትዳር መሥርቶ ልጆችን ከወለደ በኋላ የእግዚአብሄርን መንገድ እያሥተማረ ያሳድጋቸው በመልካም አስተዳደግም እየቀጣና እየተቆጣጠረ ያሳድጋቸው የእግዚአብሔርን መንገድ ይከተሉ ዘንድ እስከዕለተሞታቸው ድረስም በንስሐ ይገሠፁ ንሥሐ ከገባ በኋላ እንደገና ቢበድል የቀድሞው ንሥሐው ለዳግም ጥፋቱ አያገለግለውም ።'),
  ('47df5a4a-11bb-53b6-a84d-4172b62d0e3e', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 109, 109, 'አንተ ክርስቲያኖች በንፅሕና ሥጋቸውን ይጠብቁ ዘንድ እዘዛቸው የክርስቲያን ልጆች ከሐጢአት ሥራሁሉ ማለትም ከዝሙት የሞተውንና የበከተውን ከመብላት የባለንጀራውን ደም ከመጠጣትና የወንድሙን ሥጋ ከመብላት የሰውን ደም በተንኮል ከማፍሰስ እንዲሁም ከሐሜት እንዲታቀቡ ከሌሎችም የክፉዎች ሥራ እንዲጠበቁ አድርጋቸው።'),
  ('7667cdfc-55ec-5525-a04f-53f56dc0d75c', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 110, 110, 'ከመጠን ያለፈ መጠጥን ከመጠጣት ክርስቲያኖች ይታቀቡ የሚያሠክርን መጠጥ አብዝቶ የጠጣ ሰው ልቡናውን ይረሳል በተለይ በክህነት የታቀፉት ኤጴስቆጶስ ቄስና ዲያቆን ወይንን በመጠጣት ጊዜን ማባከን የለባቸውም ዐይንን ማብላዛት ልቡናን አጨልሞ ከነውረኝነት ይከታልና ።'),
  ('66d964cb-37e9-5336-ae8e-0ef57e64614e', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 111, 111, 'ካህናት በሥካር ከተጠመዱ ከክህነታቸው ይወገዱ ከመዓርጋቸውም ይባረሩ ህዝብን መገሠፅና ማስተማር አይቻላቸውምና ሰክረው ከታዩ በኋላ የነሱ መወገድ ለሌሎችም ትምህርት ሊሠጥ ይችላል በዚሁ ብቻ ብዙዎች ከስካርና ከዝሙት ሊታቀቡ ይችላሉ ።'),
  ('b28d5a86-db6d-58ce-a417-3ec565a12c63', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 112, 112, 'ስካር የሰውን ልቡና ያጨልማል ሕሊናንም ያደክማል ሰውን የዲያብሎስ ማደርያ ያደርገዋል ከእግዚአብሔር በረከትም ይርቃል መንፈስቅዱስ አይጠጋውም ከዚህም በተያያዘ ቤተክርስቲያን አገልጋዮች ከቁጣ የራቁ እንዲሆኑ እዘዛቸው የሰው ቁጣ የእግዚአብሔርን ክብር መግለጫ ሳይሆን ሰዎችን ተስፋ በማስቆረጥ ከቤተክርስቲያን የሚያርቅ ነው።'),
  ('7cbc0ba4-08fb-5c8b-a2b8-edc244cd36c6', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 113, 113, 'ከካህናት መካከል መቆጣትን የሚያዘወትር ካለ ከክህነቱ ይመተር ከህዝባውያን ውስጥ በባለንጀራው ላይ በሐሰት የሚመሠክር ካለ ከሐጢአቱ እንዲመለስ ምከረው ለመመለስ ፈቃደኛ ካልሆነ ግን ለሌሎች ክርስቲያኖች መጥፎ አርአያ ከመሆኑ አስቀድመህ ከቤተክርስቲያን ልጅነት ይሠረዝ ።'),
  ('fd2d85fe-01d3-5ab5-a828-942e820e3d3d', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 114, 114, 'ሳታመነዝርና በዝሙት ሳትያዝ በትዕቢት ሚሰቱን የሚፈታ ሁሉ ሕዝባዊም ሆነ ሌላ ከቤተክርስቲያን ለሰባት ዓመት ይከልከል እግዚአብሔር አንድ ያደረጋቸውንና አንድ ሥጋ መሆናቸውን የተናገረላቸውን እሱ እንዲለያዩ አድርጓልና። ሌሎችም ሕዝባውያን ሚስቶቻቸውን በግፍ እንዳይፈቱ አስተምሩአቸው።'),
  ('b52eca64-308a-53c5-a5bb-049cd60b574d', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 115, 115, 'ሚስቱን ፈትቶ ሲያበቃ በትምህርትና በቀኖና አልመለስም ካለ ከቤተክርስቲያን አባልነትና ልጅነት ተመትሮ ይባረር።'),
  ('daa7554d-e6a1-54c1-a5d6-6705c4a82a8a', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 116, 116, 'አባቱንና እናቱን የማያከብር ካለ በቤተክርስቲያን ካህናት ይመከር ይገሠፅም አልመለስም ካለ ከቤተክርስቲያን ይባረር ።'),
  ('0ac6ce2c-11b8-5b38-adfd-8cb2d76ca4c5', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 117, 117, 'ነገርግን በዚህ በደል የተገኘ ሰው ከቤተክርስቲያን ከመባረሩ አስቀድሞ ለአሥራሁለት ዓመት ከምእመናን ተለይቶ በውጭ ይቆይ ።'),
  ('9c13122b-c762-5cdd-affd-28cb02da3062', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 118, 118, 'ቤት ሁና ባልዋን በሥራይ ወይም በመርዝ የገደለች ብትኖርና ይህንንም አድራጎቷ ከታወቀ እስከመጨረሻው ከሥጋወደሙ ትከልከል እስክትሞትም እንደተባረረች ትቅር'),
  ('012a54ac-fdc1-5ec1-a2b4-4faa0c497255', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 119, 119, 'በንሥሐ መመለሷን ካረጋገጠች ግን ከቅቤ ከወተትና ከመሳሰሉት ጥሉላት መባልዕት ተከልክላ ደረቅም ግብን በዘጠኝ ሰዓት እተመገበች እስከዕለተሞቷ ትኑር እግዚአብሔር ይቅር ይላት ዘንድም በዕለተሞቷ ፀሎተንሥሐ ይደገምላት (ለተመልካችም ተብሎ)'),
  ('29ae6adc-2363-510f-aa2b-ac38307bed3f', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 120, 120, 'ነገሥታትንና መኳንንትን በቤተክርስቲያን ህግ እንደሌላው ተራ ህዝብ መሆናቸውን እስኪረዱ ድረስ ትምህርትን ሥጡአቸው በትዕቢትና በትዝሕርት ወደቤተክርስቲያን እንዳይመጡም አስተምሩአቸው ከምድራዊ ሥልጣን ጋር የተያያዘ እንዳይታበዩም አድርጉ ኦዝያን በትዕቢቱ ለምፃም ሆነ'),
  ('424868ea-36eb-531c-a256-7e303073f589', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 121, 121, 'ኢሳይያስ ነቢይ ኦዝያን ንጉሥ በመሆኑ ስላልገሠፀው በሱ ላይ አድሮ የነበረውን ሐብተትንቢት ተሠወረበት ኦዝያን ከሞተ በኋላ ግን ለኢሳይያስ ሐብተትንቢቱ ተመለሰለት።'),
  ('99c0d319-c84d-5318-a7bb-b39382ed1dbe', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 122, 122, 'ስለዚህም ኦዝያን በሞተበት ዓመት ሕያው እግዚአብሔርን በልዑል መንበሩ ላይ ሆኖ አየሁት መንበሩ ረጂም ነው ምሥጋናውም ምሉዕ ነው ሱራፌልና ኪሩቤልም ያመሰግኑታል ምስጋናውንም መስማት እጅግ አስገራሚና የሚደነቅ ነው አለ።'),
  ('dfe5e665-86bd-59db-a539-9eeaf3d18c3d', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 123, 123, 'ኢሳይያስ አዝያንን ሳይገሥፀው በመቅረቱ እግዚአብሄር እንዴት እንደተቆጣው ተመልከቱ ይህንን በመገንዘብ እናንተም ነገሥታትንና መኳንንትን ሳትፈሩ ገሥዑዋቸው ወደመካነምሥዋዕ በትዕቢት ሲመጡ ዝም አትበሉዋቸው ።'),
  ('4f90f33d-5095-5e3d-a07c-2dd7c03116ae', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 124, 124, 'ዳግመኛም ስለመጥፎተግባራቸው እየተከታተላችሀ ቀናመንገድን እንዲይዙ አድርጉ አትፍሩዋቸውም የእግዚአብሔርን ትእዛዝ በተመለከተ እነሱን ከመገሠፅ ወደኋላ አትበሉም ከነሱ በበለጠ ታላቅ ግርማ ያለው አምላክ መኖሩን አትርሱ ።'),
  ('782f5463-83c9-58a9-a511-b39bba802f63', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 125, 125, 'እናንተም ነገሥታት ና መኳንንት ለምን ቃለእግዚአብሔርን አትሰሙም ለምን የካህናትን ምክር አትቀበሉም ካህን ማለት የእግዚአብሔር አፍ ማለት ነው ካህናትን አታቃልሉዋቸው በመንግሥተሰማያት ያለች አገር በርከፋቾች እነሱ ናቸው ።'),
  ('d4023fb6-6e2b-5b35-a1ec-e6d2607a8554', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 126, 126, 'ዮሐንስ ለኢየሱስ ክርስቶስ ከፍጡሮቹ አንዱ ነው ነገር ግን ፈጣሪውን ለማጥመቅ ቻለ ስለዚህ መኳንንት የሆናችሁ ሁሉ የቤተክርስቲንን መምህራን አትናቁዋቸው ተገቢውን ክብር ስጡአቸው እንጂ እናንተም ካህናት ሰዎች ሓጢአትን እየሠሩ እያያችሁ ዝም አትበሉ ገሥፁዋቸው እንጂ ።'),
  ('dc307ec7-5a4d-571e-ab5f-7fffe54d68b1', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 127, 127, 'ከቤተክርስቲያን ሐላፊዎች ሹማምንት ሥእለትንና ብፅአትን ተቀብሎ ከተቀበለው የብፅአትና የሥእለት ገንዘብ በቤተክርስቲያን ለወደቁ ነዳያን የማያካፍል በአንፃሩ ለቤቱ ጥቅም የሚያውለው ከቅድስት ቤተክርስቲያን ሥልጣነ ይባረር ማነኛውም ከቤተክርስቲያን የተላለፈውን ውግዘት የሚያቃልል ወይም ተወግዞ የተለየውን ሰው የሚቀበል ከሱ ጋር ውግዘቱን ይቀበላል።'),
  ('3dca3627-16a9-52df-af50-1c22d91850fa', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 128, 128, 'የተኮነነው ወይም ከሥልጣኑ ሊወገድ የቻለው በግፍ መሆነን ከገለፀ በይግባኝ የጳጳሳት ጉባኤ ካሉበት ይሂድ ጳጳሳቱም የቤተክርስቲያንን ቀኖና በሚያዘው መሠረት ፍትሐዊና መንፈሳዊ ዳኝነትን በማስተላለፍ ይወስኑለት በግፍ ከሥልጣነ ከተባረረ ይመልሱት።'),
  ('a18e24ec-2145-551e-a544-1a8ad2f3cac4', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 129, 129, 'ቄስ ዳግም ሁለተኛ ጋብቻን ወደሚፈፅሙ ሰዎች ቤት አይሂድ ይህን ካደረገ የእግዚአብሔር መቅሰፍት ያገኘዋል ቄስ የሐጢአተኞችን ግብዣ አይቀበል ከነሱ ጋርም አይቀላቀል። በዓላቸውንም አይባርክ የነሱንም ልጆች ለክህነት አይምረጥ ልጆች እንደወላጆች ናቸውና።'),
  ('631c84a7-e7bd-5c27-a827-ec488fd40a38', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 130, 130, 'ሥንዴንና ዕጣንን ይዘው ወደ ቤተእግዚአብሔር ቢያመጡ የነሱ መባ የረከሰ ነውና አትቀበሉዋቸው እግዚአብሔር ይህን የመሰለ መባ አይቀበልምና ሰዎች መባ ከማምጣታቸው አስቀድመው ራሳቸውን ንፁሕ ያድርጉ ዘንድ አስተምሩአቸው ከዝሙት ከሌላ ርኩሳት ይራቁ ልጆቻቸው ይባረኩ ዘንድ ።'),
  ('b8542c83-7944-50ff-ab8a-709c27f785b7', '196e6892-cf23-5486-af59-d73af2a2fd2b', '985b8fe7-9173-595a-a533-5cc1afbe685d', 131, 131, 'እናንተ ካህናት ግን የመልካሙ መንግሥተ ሰማያት ሕይወት ተሳታፊዎች ትሆኑ ዘንድ ያስተማርናችሁ ናችሁ ገሥፀንም የመድሐኒት መንገድ ወደሆነችው ቦታ አስገብተናቹኋል።'),
  ('21ef7965-491a-5784-aa86-debc441c3c87', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 1, 1, 'በዝሙት የተገኘ ቢኖር ትዳር ያላትን ሴት ያማገጠ ወይም ደግሞ በድንግልና የሚገኙትን ሴቶች ለጥቅም ብሎ አሳልፎ ለመት የሚሠጥ ከዚሁ ጋር በተያያዘ መንገድ ከአመንዝራ ጋር በመገኛኘት ልጅን የወለደ ሲገኝ ድርጊቱን ካመነ አመነ ካላመነ ደግሞ ሃይማኖት ያላቸውን ሰዎች በሚሠጡት ምሥክርነት።'),
  ('a18dc0ae-ef76-543b-ac69-e566f2c2848c', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 2, 2, 'በቤተክርስቲን ያለው አባልነት እንዲቋረጥ ያደርጉ ዘንድ ለካህናት ንገራቸው።'),
  ('6ec73f3c-cda5-5728-aac7-9e231784b77b', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 3, 3, 'በሰማያትም መግቢያ እንዳይኖራቸው የመንግሥተሰማያት ቁልፍ ለኛ ሠጥቶአል ስለዚህ በኛ ሥልጣን ይከለከላሉ በቃላችንም ዐመፀኞች ሁሉ ይወገዛሉ የቤተክርስቲያንን ሥርዓት አልጠበቁምና በብርሃን በር ርቀው የተጣሉ ይሁኑ።'),
  ('e36d526a-d9fa-5efc-a4c1-227925619fe3', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 4, 4, '(ሀ) እኔ ጴጥሮስ መንፈሳዊ አባታችሁ ነኝ በዚህም የሾመኝ ጌታችን መድሐኒታችን ኢየሱስ ክርስቶስ ነው አለት ተብየ በሱ ዘንድ ተሾሜ አለሁ እናንተ በኔ መሠረትነት ትታነፁ ዘንድ እኔም በተሠጠኝ ችሎታ ይህንን ሠራሁ ቤተክርስቲያንን እንዳትደፋፈሩዋት እሷ የጌታየና አምላኬ ኢየሱስ ክርስቶስ ናትና።'),
  ('2ddb316a-f4d8-5bf2-af29-f44708590f54', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 5, 5, '(ለ) ልጄ ቀሌሚንጦስ ሆይ የሠራሁልህን ስርዓት በጥንቃቄ ጠብቅ አእምሮ ለሌላቸው የጠለቀውን ምሥጢር አትግለዕላቸው የእግዚአብሔርን ቃል መዘባበቻ እንዳያደርጉት ያልሆነውን ትርጉም እየሠጡ የተሠጣቸውን ስለአምላክና ስለቤተክርስቲያን ትእዛዝ በክብር መከተል ፈቃድ የላቸውም።'),
  ('e0b50ddc-66f3-57cb-aa18-7aea750386b7', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 6, 6, 'መሠርዩ ሲሞንን በእግዚአብሔር ኃይል እንዲወድቅ አደረግሁት የወይኑን ሺያጭ ያታለለ ሐናንያንም እኔ ረገምሁትና ወድያው መልአክ የኔን ርግማን ተቀብሎ መታው እሱም ባንድ ጊዜ ሞተ ሚስቱም ከሱ በኋላ ሞተች።'),
  ('adaf27d5-6b9f-5c50-afce-771b8cf2d7cf', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 7, 7, 'እነሲሞን የቅድስት ቤተክርስቲያንን ሥርዓት ስለ ተደፋፈሩ ሞቱ በንፁሕ ለሚመራ ኤጵስቆጶስ የእግዚአብሔር መልአክ አይለየውም ፈቃዱን ይፈፅምለታል።'),
  ('3c7e6536-6c41-54d3-a4c7-af5217b16b24', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 8, 8, 'ስለዚህ የቤተክርስቲያንን ልጆች በትክክል ምሩ በሥራቸው ሁሉ ለእግዚአብሔር እንዲገዙ ልቡና የሌላቸው ሰዎች ግን እግዚአብሔርን ቃል ያቃልላሉ።'),
  ('e12329e1-e13f-5994-af70-b8c233f3595b', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 9, 9, 'የቤተክርስቲያንን ሥርዓት በሰማያዊቷ ኢየሩሳሌም ምሳሌ አድርግ ሰማያዊቷ ኢየሩሳሌም መላእክተእግዚአብሔር ያለዕረፍት ምሥጋና የሚያቀርቡባት ናት እግዚአብሔር የተንኮለኞችን ነገር አይቀበልም'),
  ('81224582-bccd-5d14-afb8-6bff93a7f51b', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 10, 10, 'እግዚአብሔር ቅዱስ ነውና በቅዱሳኖቹ ይመሠገናል የተንኮለኞችን ምሥጋና አይቀበልም እሱ በቅዱሳኖቹ ብቻ ይመሰገናል በንፁሐኖቹም ይወደሳል በትጉሐንም ከፍከፍ ይላል የሐጥአንን መሥዋዕት አይቀበልም'),
  ('c1c347bd-a7e5-5fc6-ade8-b7b792abd6ff', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 11, 11, 'ኤጲስቆጶስ ሁኖ የጳጳስን መዓርግ ጳጳስሁኖ የሊቀጳጳስን መዓርግ። ዲያቆን ሆኖ የቄስን መዓርግ ንፍቀዲያቆን ሆኖ የዲያቆንን መዓርግ። አናጉንስጢስ ሆኖ የንፍቀዲያቆንን መዓርግ። ሕዝባዊ ሆኖ የአናጉንስጢስን መዓርግ። ዲያቆናዊት ሁና የሕዝባውያንን መዓርግ። ሴቶች ሆነው የዲያቆናዊትን መዓርግ። ደናግል ሁነው የሴቶችን መዓርግ። ልጃገረዶች ሁኖው የሴቶችን መዓርግ ፣'),
  ('ddfa3470-cb89-5571-aee7-84f053f7db44', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 12, 12, 'ከነዚህ ከዚህ በላይ የተዘረዘሩትን ሁሉ በድፍረት የፈፀመ የተወገዘ ይሁን ከቅድስት ቤተክርስቲያን የተረከበውንም መዓርግ ተቀምቶ ይቅር በማንኛው ቤተክርስቲያን አይገኝ።'),
  ('b4f423f6-fc43-5a39-aa25-9a2deae44f7f', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 13, 13, 'እኛ በነዚህ ዐመፀኞች ላይ ሥልጣን የለንም የእግዚአብሔር መልአክ ግን በሱ ላይ ቁጣውን ያሳያል እንደይሁዳም ያሳንቀዋል ይሁዳ በገዛራሱ ታነቀ ይህም ካባቱ ሠይጣን የተማረው ነው።'),
  ('d394339e-1f0a-5a1d-a4b7-a667743662d7', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 14, 14, 'ከሰው በአደራነት ገንዘብንም ሆነ እንስሳ። ወርቅም ይሁን ብር አልመልስም ብሎ ያመፀ ቢኖር በአደራነት ከተረከበው ዕጥፍ አድርጎ ይክፈል።'),
  ('d5171126-eeda-5d5f-a56f-b1a6eb4094c3', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 15, 15, 'በዚሁ አካሄድ የቤተክርስቲያንን ገንዘብ በዓመዕ ወስዶ ለግሉ መጠቀምያ ያዋለው አምስት ዕጥፍ አድርጎ ይክፈል። የበደለውም ግለሰብ ሳይሆን ቤተእግዚአብሔር ስለሆነ ይህን ቀኖና ሠርተናል አንዱ የሌላውን ገንዘብ እንዳይቀማም ቀኖና ሠርተናል ።'),
  ('7c75faa4-07fd-5dfb-a234-1aa611b31be8', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 16, 16, 'ኤጲስቆጶስ ሁኖ ወይምቄስ ዲያቆንም ይሁን በአራጣ ገንዘቡን እየሠጠ ዕጥፍ በማድረግ የሚቀበል ከሥልጣኑ ይመተር ከቤተክርስቲያን ሥልጣኑም ይወገድ ከኤጴስቆጶሳት ቀሳውስትና ዲያቆናት መካከል ባለንጀራውን በበደል ተነሳስቶ ወደነገሥትና ወደመኳንንት ቢከስ ካለበት የቤተክርስቲያን ሹመት ይውረድ ከአገልግሎቱም ይወገድ።'),
  ('3eee9b50-ea5b-5430-ae2c-15efc52f3742', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 17, 17, 'ሚስቱ አመንዝራ ሳትሆንበት የሚፈታና የተፈታችውም ያገባ ንሥሐውንእስኪጨርስ ድረስ ወደቤተክርስቲያን ከመግባት ይከልከል ክርስቲያን ሆኖ እያለ ዘፈን ወዳለበትና ሥካር። ዝሙት። መዳራት ወዳለበት ቤት ከሄደ ከክርስቲያንነትም ሆነ ከማናኛውም አባልነት ይሠረዝ ።'),
  ('c9bad1ff-560a-582d-a744-9192187ac83f', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 18, 18, 'ከክርስቲያን ወገኖች ወደ አይሁድና ወደአረማውያን ምኩራብ ገብቶ በነሱ የአምልኮት ሥርዓት የተሳተፈ ለበዓላቸው ከተሠዋውም መስዋዕት የበላ ከቤተክርስቲያን ይወገዝ።'),
  ('a6cf8096-0437-597d-a27e-dc4cccd22ac0', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 19, 19, 'ኤጲስቆጶሳት ከቀሳውስት። ከዲያቆናትና ከሕዝባውያን በኮከብቆጣሪዎች በጣኦት ማምለክ ከወደቁ ከቤተክርስቲያን ይባረሩ ይወገዙ ከተጠቀሱት ጋር ፍቅር ካላቸውም ይባረሩ በእሳት በውሃ በዛፍና በሌሎችም ከማምለክ ደረጃ ላይ ከደረሱ ከቅድስት ቤተክርስቲያን አባልነታቸው ተወግዘው ይለዩ ።'),
  ('eec4614a-aff6-5cb0-ad3c-f774e678bcc4', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 20, 20, 'ሕዝባዊው ብዙ ትምህርትን ካለማግኘቱ የተነሳ ይህንን ፈፅሞ ከሆነ ንሥሐ እስኪገባ ድረስ በሰቆቃና በልቅሶ በቤተክርስቲያን ዙርያ ይመለስ።'),
  ('bfbad5e1-9804-5ff7-ae0a-2fb38ba729bb', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 21, 21, 'ቤተክርስቲያን በመልካም ጥበበኛ ተሠርታ በመልካም ጥበበኛ እንደምትነዳና መዋግድ። ማእበላትና ነፋሳት ከክፉዎች ነገሥታት ጥፋት የተነሳ በማትሠጥም መርከብ ትመሰላለች ቤተክርስቲያን በምንም በምን የማትናወጥ የፀናች ናት።'),
  ('762d0651-f82a-5820-ab25-704e61ab1028', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 22, 22, 'ቅድስት ቤተክርስቲያን በሃይማኖት መስቀል ላይ የተመሠረተች ናት መሠረቷም ፅኑዕ ነው። በግራዋና በቀኝዋ ዋናተኞች ያጅብዋታል ከምትንሳፈፍበት ባህር አልፋ ወደመርሶ መድሐኒት እስክትደርስ ድረስም ከሷ አይርቁም የባሕር ምሳሌ አለም ነው በነፋስ በመዋግድና በማዕበል የተመሰሉት ደግሞ ጠንቋዮችና ሌሎችም ናቸው እነሱ ዓለምን የሚያውኩ ናቸው።'),
  ('5855fe65-3d77-5130-a72a-a87fa2046982', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 23, 23, 'እነዚህ ዐመፀኞች እነሱን እየተከተሉ ምክራቸውን ከሚሰሙና በነሱም ምክር የጥፋት ጎዳናን ከሚመርጡ ጋር ወደዘለዓለምጥፋት ይገባሉ።'),
  ('e6f819fb-6f18-53ab-ae17-0f0beccdcd7e', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 24, 24, 'የኛ መርከብ የሆነችውን የቤተክርስቲያን መንገድ የምንጠርግ እኛ ነን የልበዝንጉችንንም እሾህ ከቤተክርስቲያንና ባለእንጀራቸውን ወደጥፋት ከሚያስገቡ ጥፋተኞች የምንነቅል እኛ ነን ለጥፋት ሆን ብለው የተሠለፉ ሰዎች ብቻቸው አይጠፉም እግረመንገዳቸው ያልነቃውንና ከኛ ትእዛዝ ወደኋላ ያለውን ይዘው ይጠፋሉ እንጂ።'),
  ('cc754226-dd89-52ac-a0c5-4660530f13c2', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 25, 25, 'ከሐጢአት ሁሉ ጣዖትን ማምለክና ጥንቆላ በእግዚአብሔር ዘንድ ይጠላል ስለዚህ የቤተክርስቲያን መምህራን ሆይ የኛን ቀኖና ተመርኩዛችሁ አስተምሩ ሥሕተት ውስጥ የገቡትንም ሕዝበ ክርስቲያን ከመገሠፅ አትቦዝነ ይህን ካልፈፀማችሁ እግዚአብሔር ከፊቱ አቁሞ ይቆጣቹኋል።'),
  ('5334a68e-ddbf-59c2-ad15-fd7e27ab72ee', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 26, 26, 'እንድትሠሩባት እግዚአብሔር የወሰነላችሁን ሰዓት ሳታልፍ ኃላፊነታችሁን ተወጡ ተሠጣችሁ ሰዓት ባትሠሩ ለወቀሳና ለከባድ ቅጣት ትዳረጋላችሁ እያወቀ ላጠፋና የጌታውን ትእዛዝ ላልፈፀመ አገልጋይ ከባድ ቅጣት ሲጠብቀው ላላወቀ ደግሞ ቅጣቱ ጥቂት ነው።'),
  ('83675d1c-0f4f-508c-a14f-04ccf4ef5415', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 27, 27, 'የቤተክርስቲያን ልጆች ሆይ መንገዳችሁን አስተካክሉ የጌታችን ኢየሱስ ክርስቶስ ቃል መሠረት አድርገን የሠራንላችሁንም ጠብቁ ።'),
  ('92dd3921-8b68-544f-ab07-a54e9c33f70b', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 28, 28, 'እናንተ ጳጳሳት በሕዝብ ዘንድ ታአማኒነት የሌለውን ሰው በክህነት አትሹሙት ስለሚመረጠው (ለክህነት) ከሌሎች ብዙ መጠየቅና መረዳት ያስፈልጋቹኋል ነውር ካለበት ክህንነት አትሥጡት እንደበተርቱ ዕም መሆን አለበት ካልሆነ ግን እንዴት ያስተምራል ለምፃምንም ለክህነት አትመድቡ ሥጋወደሙን የሚቀበሉ ሕዝብ የመፀየፍ ሁኔታ እንዳያሳዩ ።'),
  ('49ce6ab4-37f4-54dd-afb4-cd7b2767de40', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 29, 29, 'አንድ እግሩ በሽተኛ ከሆነና ያለበትር መራመድ የማይችል ከሆነ ለክህነት አይገባም ያለበትር መራመድ የሚችል ከሆነ ግን ከክህነት አይከለከልም ካህን መልካም አንደበትና መልካም ተግባር ያለው ይሁን አዋቂና የሰከነ ዕውቀት ነሮት ቅዱሳት መጻሕፍትን መተርጎም መቻል አለበት መንፈሳዊ ሕይወቱንም አሟልቶ መምራት የሚችል ይሁን ሕዝበክርስቲያን በንሥሐ ከጌታችን መድሐኒታችን ኢየሱስ ክርስቶስ ጋር እንዲታረቁ የማድረግ ሐላፊነት የካህን ነውና።'),
  ('9bbf682a-0012-53d3-aaa1-6b5ae3664e79', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 30, 30, 'ከሕዝብ መካከል ከሐዲዎችና መናፍቃን ጥምቀትን ቢቀበሉ ትምህርትን እያገኙ ይቆዩ የቤተክርስቲያንን ሐላፊነት አይቀበሉ ይህ ከሆነ ማንነታቸው ሲጠና ሊረጋገጥ ይችላል የክርስቶስን በጎች ከሚነጥቁ ተኩላዎችም ተጠበቁ ።'),
  ('4ba2fa3f-ddcd-5c1a-ab57-c6a122b70d70', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 31, 31, 'መልካም እረኛ ስለበጎቹ ነፍሴን አሳልፎ ይሠጣል ጌታችን እኛ እንዳንያዝ እነሱን ተዋቸው ይሂዱ እኔ አለሁላችሁ ብሎ ስለኛ ራሱን አሳልፎ ሠጠ።'),
  ('efc392b7-52a1-5768-a2b9-d63c08aab8b1', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 32, 32, 'እኔ ጴጥሮስ ደካማ ነበርኩ የቃል እላፊም አዘወትር ነበር። ጌታችንን እኔ አልክድህም አልኩት ካንተጋርም እሞታለሁ አልኩት ይህንን ያልኩት የኢየሱስ ክርስቶስ መንጋዎች ሁነን ከሱ ጋር በነበርን ጊዜ ነው። እሱም በደሙ አዳነን።'),
  ('30486c80-558b-5a66-a193-eb70a54dce0c', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 33, 33, 'እሱ ግን ስለኛ በግዓመሥዋዕት ሆነ ስለሌሎችም ሐጢአተኞች ቤዛ ሆነ ነውር የሌለበት የበግ ጠቦትም ሁኖ ስለኛ ሞተ። ከተኩላም እኛን ለማዳን አንደበቱን ከፈተ እኛም ከኛ በታች ሁነው እንድንጠብቃቸው ስለተሠጡን በጎች ነፍሳችንን እንስጥ ለተኩላዎች አሳልፈን አንስጣቸው።'),
  ('0d9d9cd9-840d-5585-ae9c-a230f04f731c', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 34, 34, 'ትተናቸው ሳንሸሽ ወጥተን ወርደን በማስተማር ወደእግዚአብሔር እናምጣቸው የቅድስት ደብተራንም ሥርዓት ጠብቁ አብሲስ የተባለው መናፍቅ ተነስቶ ክርክርን እያነሱ ቤተክርስቲያንን በመቃወም የሚሠለፉ ብዙ ተከታዩችን ወስዷል የሱ ተከታዮች የክህደትና የዓመፅ ሰዎች ናቸው ስለዚህ ከነሱ ተንኮል ተበቁ።'),
  ('ef49f5ed-db1f-5f18-af3d-1b0e3258ffa9', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 35, 35, 'ክርስቲያኖች ሁነው ሳለ ይህን ከዚህ በላይ የታዘዘውን የማይፈፅሙ ካሉ ጳጳሳትና ካህናት ከስንፍና የተነሳ የማይፈፅም ካለ የታዘዘውን ሁሉ እስኪፈፅም ድረስ ከቤተክርስቲያን ይከልከል በስንፍና ያባከነውንም ገንዘብንም ሆነ ጊዜ በእጥፍ ይመልስ።'),
  ('70962438-5e17-5596-a9ea-9b83a09a5800', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 36, 36, 'ከጳጳሳት ከቀሳውስት ከዲቆናት መካከል የቤተክርስቲያንን ንብረት የሠረቀ ቢገኝ የሠረቀውም ከቅብዕና ከሰም (ከጧፍ) ወይም ሌላ ይህን የመሰለ ቢሆን የቤተክርስቲያን መምህራን በሚሠጡት ውሳኔ የሚገባውን ቅጣት ያግኝ ከነሱ መካከል ከአመንዝራ ሴቶች ልጅን ቢወልድ ከቤተክርስቲያን ተወግዞ ይባረር ወይም የወንድን ሚስት ቢያማግጥ ይባረር።'),
  ('b5856164-4525-5b21-a1eb-e2f4ea10e8ac', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 37, 37, 'ወንድ ሁሉ በሚስቱ ፀንቶ ይኑር ሴት ሁሏም በባልዋ ዐን።። ትነር የቅድስት ቤተክርስቲያን ማሕበር ተግባር ይህ ነው።'),
  ('51a6c7eb-71b3-53c7-aa06-bd36cbc340ca', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 38, 38, 'ባለትዳር ሁና ሌላ ወንድን በማፍቀር ብታመነገር ባልዋ ይፍታት ንሥሐዋንም እስክትጨርስ ድረስ መበለት ሁና ትቆይ ሚስቱ ከሌላወንድ ጋር ማመንዘርዋን እያወቀ ሊፈታት ካልፈቀደ ሁለታቸው ከእግዚአብሔር ተለይተዋል ስለዚህ ንሥሐቸውን እስኪጨርሱ ድረስ ሁለቱ ከቤተክርስቲያን ይለዩ።'),
  ('d72eaeb4-3097-5e4f-af67-fa39df2a08b9', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 39, 39, 'ንሥሐቸውን ጨርሰው ሲመለሱና ወደቀድመው ሕይወታቸው ቢወ፡ለሱም እንኳ ክትትል ያስፈልጋቸዋል ካህናት ሁነው ይህን ፈፅመው ቢገኙ ግን ባስቸኳይ ከክህነታቸው ይወገዱ ካህናት ማለት ሁልጊዜ በዓይነሕሊና እግዚአብሔርን የማየት ሥልጣን የተሠጣቸው ናቸው።'),
  ('18be25cf-d541-578e-a7a2-b71c1fd5bd09', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 40, 40, 'እግዚአብሔርም በካህናት መካከል ይናገሪል ምክንያቱም የካህናት ዓይነሕሊና ሁልጊዜ ወደእግዚአብሔር እንደተመለከቱ ናቸውና እግዚአብሔርን በዓይነህሊና አላየውም የሚል ካለ የንሥሐን። ምሥጢር አይረዳውም ከእግዚአብሔርም የሐጢአትን ሥር? ። አይለምንም ስለዚህ እንደወጣ ይቅር።'),
  ('3c38e0d8-4d6d-53c5-a715-b961e693386c', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 41, 41, 'ቴስቢያዊው ኤልያስ እኔ የቆምኩለት እግዚአብሔር ሕያው ነው እንዳለ ለነኤልያስ ለካህናት የተሠጠውን ምሥጢረ እግዚአብሔር አልተሠጣቸውም ለናንተ ለካህናት ግን ምሥጢረእግዚአብሔርን የመፈፀም ዕድል ተሠጥቶአችኋል እናንተም ፀጋውን ቀምሳችሁታል እናንተ ሕዝቡን የምትመግቡ ከዝሙትም እንዲርቁ የምታስተምሩ ናችሁ።'),
  ('57a4deb2-4209-567e-ab5e-b6a6b9fea993', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 42, 42, 'እናንተ ካህናት ሁናችሁ በኃጢአት ማጥ ውስጥ ከተዘፈቃችሁ እናንተን ማን ያስተምራል ማንስ ይገሥፃል በዚች ምድር ከናንተበላይማንም የለም ገሀነመእሳት ይጠብቃቹኋል መንገዳችሁን አስተካክሉ ሚስቶቻችሁም እግዚአብሔር ከማይገለገልበት መጥፎ ሥራ ሁሉ እንዲርቁ ገሥዑዋቸው።'),
  ('78bfbd5d-e045-5f60-a06e-99908b5b7a26', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 43, 43, 'እነሱ እንደነሱ ላሉት ሌሎች መሰሎቻቸው መምህር ይሁኑ የሚገሥፁም ይሁኑ ደግነታቸው የተስተካከለ ከሆነ ሌሎችን ሴቶች ደናግልንና የራሳቸውንም ሴቶች ልጆች ያስተምሩ ልጆቻቸውን ያልሆኑትንም በቤተክርስቲያን ህግ የሚሄዱ ልጃገረዶችን ወደመልካም መንገድ ለማስገባት ያስተምሩአቸው።'),
  ('0fdd65b4-506b-5245-a04e-45b2d974bf81', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 44, 44, 'የነሱን ምክር ለመቀበል ፈቃደኛ ያልሆኑ ቢኖሩ ለባሎቻቸው ነግረው የቤተክርስቲያንን ቀኖና ያሠጡዋቸው። ክርስቲያን የሆናችሁ ሁሉ ለፅድቅ ቀናተኞች ሁነ። ከትንሽነታችሁ እስከትልቅነታችሁ ከዚሁ አትራቁ ሐዋርያው ለትልቋ ፀጋ ቅኑ ብሏልና ዕውቀት ያላቸው ሴቶችም ባለንጀሮቻቸውን መክረው ከመጥፎ ሥራ ያስወግዱዋቸው።'),
  ('3472b0d7-914d-5095-a1f4-dd3005be535a', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 45, 45, 'ሴቶች የነቢዪቷ የፋኑኤል ልጅ ሓናን ፈለግ መከተል አለባቸው ሓና ሌትተቀን ያለማቋረጥ እግዚአብሔርን ታመሰግን ነበር። አንደበቷ ከፀሎትና እግዚአብሔርን ከማመስገን አያቋርጥም ነበር። ሴትም ትሁን ያገባችም እግዚአብሔር ከዘማዊነት እንዲጠብቃት በሙሉ ልብ እግዚአብሔርን የምታገለግልበት መንገድ ትለምን።'),
  ('b1df7491-cc7c-56ea-a041-5e94a6ead1cc', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 46, 46, 'በመሐይምነት የተጠመዱ ሴቶች የዛሬውን በማስታወስ እግዚአብሔር የትናትና የዛሬ እሱ መሆኑን በመገንዘብ እግዚአብሔር እኛ ያንተባሮች ነን ደካማዎች ሁነን እያለ ትእዛዝህን ጠበቅን ስለዚህ ድካማችንን ተመልክተህ ከተቀደሱ በጎችህ ጋር ጨምረን እንድትሉትና እግዘአብሔርም እናንተ ሕሊናችሁን ጠብቃችሁ ሥጋችሁን ንፁሕ ያደረጋችሁ ናችሁ ይህንንም ስለከበረውና ታላቅ ስለሆነው ስሜነው እንዲላችሁ ።'),
  ('ab4cffd0-37b0-57cf-ab89-604a6cfaa253', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 47, 47, 'ጌታችንም ስለሴቶች እንዲህ ሲል አዞናል ትእዛዜን ጠብቁ ሴትን ከወንድ አትለዩ አይሁዳዊ። አረማዊ ባርያ ጌታ ብላችሁ ልዩነትን አትፍጠሩ። ሁሉም ቅድስት ጥምቀትን ከተቀበሉ በኋላ በኔ ዘንድ አንድ ናቸው እኛም ይህንን መሠረት አድርገን ጋብቻቸውን አክብረው ለሚኖሩም ሆነ ድንግልናቸውን ጠብቀው ለሚኖሩ ሥርዓትን ሠርተናል ወንድማችን ጳውሎስም እኔ ለሴቶች ከእግዚአብሔር በተነገረኝ ሳይሆን ከራሴ እንዲህ እላቸውአለሁ አለና ገን።'),
  ('68032a34-c909-5f19-addf-e931ad7e0d56', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 48, 48, 'ደናግልና መዓስባት በትዕግሥት ከዝሙት ተጠብቀው ይኑሩ 204 መታገሥ ካልቻሉ ግን ያግቡ ከዘማዊነት አግብቶ መኖር ይሻላልና።'),
  ('530ea90f-e89c-5085-a2f5-469cc8d1d41b', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 49, 49, 'ራሳቸውን ጠብቀው ይኖሩ ዘንድና ከባሎቻቸው ውጭ አንዳይሆኑ ታዟል።'),
  ('cb9cbd84-c6a9-5d13-aeaf-f4d880fdbeb6', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 50, 50, 'አንቺ እርሻ ራስሽን ጠብቂ ሌላ ዘርን አትጨምሪ የሚያጽናናሽና ከሐዘንሽ የሚያረጋጋሽ ባልሽ ብቻ ነው።'),
  ('3e35201b-c94e-59cc-a319-b0655abb968e', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 51, 51, 'ይህ ሁሉ ከእግዚአብሔር ዘንድ ሆነ እናንተም የእግዚአብሔርን ትእዛዝ ጠብቁ የተጻፈውንም ሁሉ አንብቡ። በጥንቃቄም አስተውሉ ሳትማሩና መፃሕፍትን ሳታነቡ የምታገኙት እውቀት አይኖርም ከሊቃውንት ተማሩ የመፃሕፍትንም ቃል አድምጡ ።'),
  ('7e1af002-2068-5109-acce-876b3eeab7d3', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 52, 52, 'የመለኮትን ቃል ከልባችሁ ውስጥ አስቡ፥ የመምህራችሁ ቃልንም አትርሱ ባለንጀራችሁ እንደራሳችሁ ውደዱ መፅሐፍ ይገድላል መንፈስግን ያድናል መጽሐፍ የተባለው ኦሪት ነው መንፈስ የተባለው ግን ወንጌል ነው።'),
  ('cde39e8c-b0fd-5f54-a332-97a3d2497210', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 53, 53, 'በወንጌል መንገድ ሂዱ። ትድኑ ዘንድ የቀኖናንም ሥርዓት ጠብቁ ከእግዚአብሔር ፈቃድ በተመሠረተ መልካም ሥራን ትማሩ ዘንድ የመፃሕፍትን ቃል ከመስማት ወደኋላ አትበሉ የመለኮት መጻሕፍት በቃላቸው ይታወቃሉ ።'),
  ('9c8c6577-b7b0-5a3e-a694-1fba2e257120', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 54, 54, 'የመለኮት መጻሕፍት ከቃላቸው ስለሚታወቁም የሐሰት መጻሕፍት ከነሱ ጋር እንዳይጨመሩ ቅድስት ቤተክርስቲያን ታስጠነቅቃለች መጥፎ ነገር ካለና ከደሕና ነገር ከተጨመረ ጀሮላይም ከገባ መልካሙን ልብ ያደፈርሰዋል።'),
  ('9434b82e-5165-5aee-a2f7-10f23a887e37', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 55, 55, 'ተጠራጣሪዎች አትሁኑ የቅድስት ቤተክርስቲያንን ቀኖና ጠብቁ እንጂ ከዚህ ዓለም ካለው መጥፎ ሥራንም ራሳችሁን ጠብቁ፡ ሞት ሳይመጣባችሁ ለመልካም ሥራ ተሽቀዳደሙ በክፉ ቦታ እያላችሁ ከሞታችሁ ወደሲኦል ትወርዳላችሁ ይህ ሁሉ የሚያገኛችሁ የቅድስት ቤተክርስቲያንን ሥርዓት ካልጠበቃችሁ ነው።'),
  ('fe7da876-084f-5b23-ab96-b316e1f2058a', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 56, 56, 'ከሥካር ተጠበቁ ሙሴ በኦሪት ዘሌዋውያን እንዳይሠክሩ አዟቸዋል እንዲሁ እናንተ ኤጴስቆጶሳት ቀሳውስትና ዲያቆናት መጠጥን ከማብዛትና ከሥካራ ተጠበቁ መዳራት፣ዝሙት፣ ስግብግብነት ሰውን መስደብና ማስቀየም መታበይ፣ በሐሰት መማል፣ ብዙ ቁምነገሮችን መዘንጋትና ሌሎችም ከሥካር የሚመነጩ ናቸውና።'),
  ('d45821b9-a46d-5387-a428-aeaf4c61deef', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 57, 57, 'ከሥካርና ወይንን ከማብዛት ተጠበቁ ቃለእግዚአብሔር የሠፈረባቸውን መጻህፍት መጠጣትን አዘውትሩ እንጂ ሁላችን አንድ ሥጋንና አንድ መንፈስን ጠጥተናል ስለዚህ በቤተክርስቲያን ሕግ መሠረት ከተጠበቅን በሕብረት ከጌታችን ፊት እንቆማለን ።'),
  ('d10f91c5-27ed-57a6-a6bf-3f8399f10752', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 58, 58, 'ዲያብሎስና ጭፍሮቹ ማንም ሰብአዊ ፍጡር እንዲድን አይፈልጉም ከተሳካላቸው ሁሉም ሰው እንዲጠፋ ነው ፍላጎታቸው።'),
  ('a7289a53-8459-5293-a2dd-0e171827f423', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 59, 59, 'መሐይምናን ካላቸው ንብረት ለድሆችም ምፅዋትን ይሠጡ ዘንድ እዘዛቸው ይህን ካደረጉ እግዚአብሔር ይባርከዋል። ምንም የሌለው ድሐ ቢሆን እንኳ ካለችው የዕለት ጉርሱ ከፍሎ ይመፅውት ።'),
  ('19dbaeb2-634c-57ad-a5ab-a138c4056953', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 60, 60, 'ይህን ከፈፀመ እግዚአብሔር በዚህ ዓለም እያለ ካለበት ደረጃ ከፍ ያደርገዋል በወድያኛው ዓለምም ከማሕበረቅዱሳን ጋር ይጨምረዋል ከሞት ወደሕይወት ለመሻገር ትችሉ ዘንድ መልካም ሥራን ችላ አትበሉ ከዕልዋን ጋርም አትቀላቀሉ።'),
  ('30e23f1c-cc14-5a27-a618-7cb1f465c02c', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 61, 61, 'እናንተ የክርስቲያን ልጆች የነገርናችሁን ነገር ወደኋላ ችላ አትበሉ። ሕዝቦቹ ለናንት የሠጠነውን ሥርዓት ጠብቀው ይኖሩ ዘንድ እዘዙዋቸው ።'),
  ('4a366bd9-7b7b-5957-ab58-efb97dcb6e72', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 62, 62, 'ይህንን የሠጠናችሁን ሥርዓት የማይቀበልና የማይመራበት ሰው ካለ ከቅድስት ቤተክርስቲያን መዓርጉ ይወድቃል።'),
  ('bff8cc2e-de59-55ac-a4f9-639395cd5450', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 63, 63, 'የቤተክርስቲያንን ሥርዓት ጠብቁ እሷ የጌታችን መድሐኒታችን ኢየሱስክርስቶስ ናትና ይህንን ማድረጋችሁ በሰማያት ላለው አባታችሁ ልጆች እንድትሆኑ ነው። እሱ ለደግ ሰዎች ደገኛ አምላክ ነውና ።'),
  ('1777d2a6-8ccd-5627-a0ab-8389d2387a89', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 64, 64, 'እግዚአብሔር ለደገኞች ደግ ነው ሐጢአተኛን ስለሐጢያቱ ችላ አይለውም ሁሉ ለሱ ነው ሁሉም ከሱ ዘንድ ነው ሁሉ በፈቃዱ ይሆናል ሁሉ ከፊቱ ተዘርግቶ ይታያል ሁሉም ከሱ ዘንድ ግልፅ ነው። የቤተክርስቲያንን ሥርዓት ጠብቁ ከሷም አትራቁ ከሷ ካልራቃችሁ ስትወጡና ስትገቡ ፍፁም ደስታ ይሰማቹኋል።'),
  ('6194257e-7a8f-5529-ac5d-8ecae3f609ec', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 65, 65, 'ጌታችን ኢየሱስ ክርስቶስ ለኛ ለአሥራሁለት ሐዋርያት ሕዝቦቹን በእውነትና በቅንነት እንመራ ዘንድ አዞናል በቤተክርስቲያን ቀኖና መሠረት እንጂ በሌላ ምክንያት ለሰው ፊት በማዳላት ቅጣትንም ሆነ ሌላ በሰው ላይ እንዳናስተላልፍም አዞናል ስለዚህ ከቤተክርስቲያን ቀኖናና ሥርዓት ውጭ በሆነ መንገድ ሕዝቦችን አንቀጣም።'),
  ('fd7b283a-7290-5fe1-a2b1-d4040e583ecd', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 66, 66, 'በሌላ ምክንያት ከቤተክርስቲያን ቀኖና የሚወጡ አሉ የምድር ገዢዎች ፈቃዳቸውን እንፈፅም ዘንድ ሌላ ትእዛዝ ያዙናል የቤተክርስቲያንን ሥርዓት በጥንቃቄ ልንከታተል አንችልም በማለት ብዙ የተለያየ ምክንያት ያቀርባሉ ።'),
  ('0fd14cd2-b175-54ac-acde-83989b341cd3', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 67, 67, 'ይህንንም ምክንያት መነሻ እያደረጉ የእግዚአብሔርን ሥርዓት ችላ ይላሉ እግዚአብሔርም ይወቅሳቸዋል ።'),
  ('06b82f05-77dc-5744-a1b3-b40093f07869', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 68, 68, 'ነገሥታትና መኳንንት በቤተክርስቲያን እንደማንም ተራዎች ናቸው ስለዚህ ስለነፍሳቸው በትክክል የቤተክርስቲያንን ሥርዓት ይጠብቁ።'),
  ('4e7a224b-fd05-5a81-a6d7-a3c06c16a7f2', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 69, 69, 'ለሥጋ ከማድላት ለዘዓለማዊቷ ነፍስ ማድላት ይሻላል ለስጋ ብቻ የሚያስቡ ለሰው እንዲያደሉ በራሳቸው ይገደዳሉ ለእግዚአብሔር ማድላትን የመረጡ ግን በረከተነፍስንና በረከተሥጋን አያጡም።'),
  ('370d5926-bc82-5173-a39a-0802c576d4a4', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 70, 70, 'እግዚአብሔር ራሱ በቀና መንገድ እንዲጓዙ ይመራቸዋል ወደሱም ዝንባሌአቸው እንዲሆን ያደርጋቸዋል የሱንም ትእዛዛት ጠብቀው እንዲኖሩ ያደርጋቸዋል ።'),
  ('de66e23b-6112-55fc-ae3c-dc2318091d48', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 71, 71, 'የቤተክርስቲያንን ሥርዓት አፍርሶ የክርስቲያን ዓለቆች ጥፋቱን በመመልከት ጥፋተኛ ሆኖ ስላገኙት ቢቀጡትና የነሱንም የቅጣት ውሳኔ ለመቀበል ፈቃደኛ ሳይሆን ቀርቶ ወደሥጋውያን ዳኞች በመሄድ የቤተክርስቲንን አለቆች ቢከስና ከቤተክርስቲያን ቀኖና ውጭ ቢሆን ።'),
  ('4a34577d-517b-550b-aba3-1244d9b3c1dc', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 72, 72, 'ይህን የመሰለ በደለኛ ከቤተክርስቲያን መራቅ ይገባዋል ከማሕበረምእመናን ጋርም አይካፈልም ንሥሓውን ሲጨርስ ካልሆነ በቀር ወደቤተክርስቲያን እንዲገባ አይፈቀድለትም ።'),
  ('d344130c-dfa3-5703-a837-e7581baddd1c', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 73, 73, 'ከካህናትና ከሕዝባውያን መካከል የተወገዘውን ሰው ተቀብሎ ቢገኝ ከተወገዘው ሰው ጋር ከቤተክርስቲያን ተለይቶና ተወግዞ ይባረር።'),
  ('9e46b84e-7697-5f8c-ab62-4b2b7461017e', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 74, 74, 'ለካህናት ሐጢአተኞችን ለንሥሐ ያለአድልዎ መቀበል ይገባል ንሥሐን እናቀልልሃለን ብለው ከተነሣሂ መማለጃን አይቀበሉ። ይልቁንስ የሐጢአቱን ክብደትና ብዛት በመመልከት ተገቢውን መንፈሳዊቅጣት ይሥጡት ጣኦትአምላኪ ከሆነ ንሥሐውን ያክብዱበት በእግዚአብሔር ዘንድ ከባዱ ሐጢአት ጣዖትን ማምለክ ነውና።'),
  ('423403c4-c709-5d8f-a702-905d6c9b778e', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 75, 75, 'በመልካም ምግባረሠናይ የሚኖሩትንና መላ ሕይወታቸው ለፅድቅ ሥራ ለሚያውሉ መሐይምናን ሕዝበክርስቲያን የተሠጠውን ቀኖና ጠብቁ እነሱ በንሥሀ ሕይወታቸውን ከጥፋ በደሙ ካዳናቸው ጌታችንና መድሐኒታችን ኢየሱስክርስቶስ ጋና ሁነው እስከዘለዓለሙ ይደሰታሉ ።'),
  ('cfb5b3f3-55b0-56f6-ac23-dbf3eaabd241', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 76, 76, 'ክርስቶስ በተሠቀለ ጊዜ ጎድኑ በጦር ተወጋና ከጎድኑ ደምና ውኃ ፈሰሰ በዚሁ ውኃ ክርስቲያኖች ይጠመቃሉ። ቤተክርስቲያንንም በደሙ ቀድሷታል የሐጢአት ማስተሥሪያ ትሆን ዘንድ እሷ እኛን ነፃ አውጥታ በሰማያት እናታችን ትሆናለችና።'),
  ('76c209b0-2c52-545e-ae06-41a419091bd0', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 77, 77, 'የክርስቲያን ነፍስ የቤተክርስቲያን ሙሽራ ናት ነገር ግን ዓይናቸውን ወደሌላ ሴት የሚያዞሩና ሌሎችንም ለማሳሳት የሚሯሯጡ ሁሉ በደለኞች ስለሆኑ ከ ቤተክርስቲያን መንጋዎች አይቆጠሩም ።'),
  ('2ac59c67-c1f5-52ad-a3a2-c93824843ac1', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 78, 78, 'ጥንቆላን በቤታቸው የሚያካሂዱ ጣዖትንም የሚያመልኩ ዝሙትን የሚያፈቅሩ በቤታቸው ጭፈራንና ዳንኪራን የሚያዘወትሩ እንግዳን መቀበልና የሙትን ልጆችን መርዳት የማይፈልጉ ራስወዳዶች የሆኑ ባለንጀራቸውንም የሚንቁ ከህገቀኖና ቤተክርስቲያን የወጡና ፈፅመው የተለዩ ስለሆኑ ማንም ክርስቲያን ሊመሰላቸው አይገባም ።'),
  ('e14a95fe-3e84-543f-a484-d423eb0b6628', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 79, 79, 'ከላይ በተጠቀሱ የሐጢአት ዓይነቶች የወደቁ ሁሉ በንሥሐ ከተመለሱ ቅዱስ ወንጌልንም ከመማር የተነሳ መጥፎሥራቸውን ሁሉ ትተው በቅድስት ቤተክርስቲያን ውስጥ የነበራቸውን የቀድሞ ክብራቸው እንዲይዙ አድርጉ።'),
  ('a6e49bb5-6135-5f8d-ad29-546d31e56b33', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 80, 80, 'ትራሩለት የፈለጋችሁት ሰው ካለ ራሩለት ልትገሥፁት የምትፈልጉት ካለ ገሥፁት ከቤተክርስቲያን ልጅነት እንዲወገድ የምትፈልጉት ካለ አስወግዱት ብዙ ጥፋት ለፈፀመ እንደጥፋታቸው መጠን ንሥሐ ሥጡዋቸው በደላቸው ጥቂት ለሆነ ጥቂት ንሥሐ ስጡዋቸው።'),
  ('57eb9d85-d8d3-553a-a3f5-81ace5574297', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 81, 81, 'ይህንን ከፈፀማችሁ እግዚአብሔር ደስ ይለዋል የቤተክርስቲያን ልጆች የርሕራሄና የይቅርታ ሰዎች ናቸው ክፉ ሥራ የሚሠራውን ሰው ወደእግዚአብሔር ከተመለሰ ስለፈፀመው ሐጢአቱ ቁጥጥርን አታብዙበት እውቀት ያላቸውን ሰዎች ደግሞ በትንሽነታቸው ችላ አትበሉዋቸው።'),
  ('edcc8345-3174-52c8-a8bd-aa7e829d9bee', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 82, 82, 'አዋቂዎች ለመሆን የሚችሉ አረጋውያን ብቻ አይደሉም በዕድሜ ሳይገፉም ጥሩ መንፈሳውን የሚሆኑ አሉ። በዕድሜ መግፋት ብቻ ወይም ብዙ ዓመታትን በመኖር ብቻ ለትልቅነት አይደረስም ሰዎችን የውስጥ ሕይወታቸውን በመመርመር ህዝብን እንዲመሩ እዘዛቸው።'),
  ('7b8b481e-534f-5cde-aca5-08280b58f065', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 83, 83, 'ጥብዐት በተሞላበት አኳኋን ሰዎች ወደ እግዚአብሔር ከመጡ ወደቀድሞው የሐጢአት ቦታቸው እንዳይመሰሉ ካህናት ይጠብቁዋቸው እናንተም ራሳቸውን ከሐጢአት ለማዳን ለመጡት መልካም አርአያነትን ሥጡዋቸው በመልካም መንፈስዊ ትምህርትም እንዲታነፁ አድርጉ መልካም መንፈሳዊ ትምህርት በበራ ገፅ ወደእግዚአብሔር ታደርሳለች በዚሁ ትምህርት የታነፁ ምእመናንም ከቅዱሳን ፃድቃን ጋር ይደሰታሉ።'),
  ('d51a871c-d987-5cb2-addb-7c391d0e0225', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 84, 84, 'በግድየለሾችና በሐጢአተኞች መንገድ አትሂዱ እነሱ ንሥሐን አይወዱም በዚች ምድር እያሉ ነገ እንሞታለንና በሕይወት እያለን እንብላ እንጠጣ ይላሉ ስለሙታን መነሳትም እምነት የላቸውም የሞተ ሰው ሁሉ የሚጠብው መቃብር ውስጥ አመድ ሆኖ መቅረት ብቻ ነው ከጊዜ ብዛት የሰው አካል በመቃብር ውስጥ ጥሪኝ አመድ ይሆናል በእልፍ የሚቆጠር የሰው አካል ባንድ መቃብር ቢቀበር እጅ የሚሞላ አመድ አይገኝም ይላሉ ።'),
  ('16a12635-1a00-5a3c-a345-bcb10711b3ba', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 85, 85, 'በዚሁ ሁሉ ይስታሉ ባለንጀሮቻቸውንም ያስታሉ ወደኩነኔም ይመሩዋቸዋል እግዚአብሔር ግን የሰውን ፊት እይቶ አያዳላም በእውነታው ፍርዱ ሁሉን እንደየ ሥራው ይከፍለዋል እንጂ።'),
  ('3d082d22-e20f-5f4e-abd5-7b8216a461d5', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 86, 86, 'ሙታን ደግሞ እንደሚነሱ ለሙሴ በዕፀጳጦስ እግዚአብሔር በተናገረው ቃል ተገልቧል የሕይያዋን አምላክ ነኝ እንጂ የሙታን አምላክ አይደለሁም ብሎታልና ጻድቃን በእግዚአብሔር ዘንድ ሕያዋን እንጂ ሙታን አይደሉም ሐጥአን ዳግም ሞት ይጠብቃቸዋል ጻድቃን ግን ዳግም ሞት አይጠብቃቸውም ሕይወት ይጠብቃቸዋልና በመንግሥተሰማያትም ከእግዚአብሔር ጋር ሲደሰቱ ይኖራሉ ።'),
  ('ecbcb0b2-ffb0-50c4-a216-169af8b954ed', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 87, 87, 'ሐጢአተኞች በዚህ ዓለም እያሉም በነፍሳቸው የሞቱ ናቸው (በእግዚአብሔር ፊት) አዳም በገነት እያለ በነፍሱም በሥጋውም ሕያው ነበር። ከመላእክት ጋርም ይነጋገር ነበር። አውሬዎች ይሰግዱለት ነበር። የሰማይ ወፎችም ይታዘዙት ነበር። የእግዚአብሔርን ትእዛዝ ካፈረሰ በኋላ ግን በነፍሱ ሞተ ።'),
  ('f890ae5b-949b-5a98-a22e-9e57005dbb1d', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 88, 88, 'ያረጋጉትና ያጫውቱት የነበሩት መላእክት ያሳድዱት ጀመር ከገነትም አስወጡት አውሬዎችና ወፎች ጠላቶቹ ሆኑ ሥጋውንም ለመብላት ፈለጉ የማይታዘዙትም ሆነ ።'),
  ('4e81aefc-0745-58a3-a58e-2ab2184168b1', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 89, 89, 'እንደዚሁ ሐጢአተኞች በሙሉ ከጥምቀት በኋላ ሐጢአትን በመሥራታቸው በነፍሳቸው የሞቱ ናቸው በአካለ ሥጋ እያሉ እናንተ ይህንን ሁሉ እያስተዋላችሁ ሥጋችሁን ግደሉ እንጂ ነፍሳችሁን አትግደሉ ከዝሙትም በመጠበቅ የእግዚአብሔር ቤተሰቦች ሁነ ነፍሳችሁንም በእውነትና በመልካም ሥራ ለእግዚአብሔር አገልግሎት ዝግጁዎች ሁኑ ።'),
  ('cd7efed9-699e-51bc-ad6f-ec0c03e844cd', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 90, 90, 'ዳግመኛም ነፍሳችሁንም እግዚአብሔርን ከማገልገል አታርቁ ከነፍስ ጉስቁልናም ሁሉ ከክፋትም ሁሉ ራቁ ነፍሳችሁንና ሥጋችሁን አድኑ ከሞት ወደሕይወት ለመሸጋገር እንድትችሉም ቤተክርስቲያንን በትክክል አገልግሉ።'),
  ('455ae64a-bacf-5a37-a5c8-ab6d0011aba2', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 91, 91, 'እኔ የሐዋርያት አለቃ ጴጥሮስ በሥጋ እያላችሁ ነፍስ አባታችሁ ነኝ ይህንንም ሥልጣን የተረከብኩት ከአምላኬ ነው። የማዘዝ ሥልጣን ለኔ ተሠጥቷል እኔም ይህን ትእዛዝ ሁሉ ለልጄ ቀሌሚንጦስ አስረከብኩት ቀሌሚንጦስ በበኩሉ ለመስማትና ከሐጢአት ለመመለስ ዝግጆናዎች የሆኑትን ሁሉ በዚሁ መንገድ ያስተምራቸዋል ለመቀበል ፈቃደኞች ያልሆኑትንና አእምሮ ለሌላቸው ግን ቃሌ መዘባበቻ እንዳይሆን አይነግሩዋቸውም ።'),
  ('bc525a29-fb30-545a-ac0a-e7087a8d7a1f', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', '9dc3e748-75f3-51ae-a243-f3ab716dd3e0', 92, 92, 'በደብረዘይት ከሱጋር ሳለን ጌታችን ያዘዘን ይኸው ነው የእኔን ቃል ለመቀበልና እኔን ለመከተል ፈቃደኞች ላልሆነ ምሥጢራቴን ገልፃችሁ አትንገሩዋቸው መንገዱንም አትግለጹላቸው የተቀደሰውን ስሜ እንዳይሰድቡ ቃሌን መጠበቅ ያለባቸው ሐጢአተኞች ሳይሆኑ ቅዱሳን ብቻ ናቸው ለዚሁ በመ የተመረጡ ።'),
  ('f70ae537-7031-53b6-aee5-b6b76e901b3d', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 1, 1, 'ከዚህ ቀጥለን ቅዱስ ጴጥሮስ ለቀሌሚንጦስ ስለሰው ልጆች ስለመድሐኔታችን ኢየሱስ ክርስቶስ የገለፀለትን እንፅፋለን ቀሌሚንጦስ ተልሚድ ተብሏል ተልሚድ ማለት ተማሪ ማለት ነው።'),
  ('67ceba7f-1921-5f7f-aec2-f3a4e040038f', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 2, 2, 'ስለኛ ፍቅር ባባቱ ፈቃድ ምሥጋና ፍሬን በማብቀል ወደኛ መጣ በመልካም መዓዛነቱም ዓለምን አሳመረ። በኋለኛውም ዘመን ወደዓለም መጣና ከቅድስት ድንግል ማርያም ዘንድ አደራ ለራሱም መልካም ሥጋን አዘጋጀ።'),
  ('1caaadd0-3c03-571e-a7c9-f83f79644b47', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 3, 3, 'የአምላክ እናት ከተባለችው ድንግል ማርያምም ሥጋን ለብሶ የይሁዳ ክፍል ከሆነችው የይሁዳ ምድር ቤተልሔምም ተወለደ የሱም መወለድ በመላዋ ምድረ ይሁዳና ኤፍራታ ዘንድም ተሰማች ከሄሮድስም ሸሽቶ ግብፅ ደረሰ በደብረቁስቋምም ተቀመጠ እስክንድርያን ምሥርና ቁዝን ጨምሮ አገሪቷን ነፃ አወጣ።'),
  ('7ada087f-a5e0-5aa1-ab2e-d26dc109a1e2', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 4, 4, 'ሰነቢዩ ከግብፅ ልጄን ጠራሁት ተብሎ እንደተፃፈውም ከግብፅ ወደ ናዝሬት ተመለሰ ወደገሊላም ደረሰ የጥብርያዶስን ባሕር ጨምሮም እስከ ባህረኢያሪኮ ያሉትን አገሮች በመልካም መዓዛው አሳመራቸው።'),
  ('0716c6c8-001d-552f-a7be-094a96875376', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 5, 5, 'ዘካርያስ ነቢዩ ስለዚህ ትንቢት ሲናገር በዛንጊዜ የሕይወት ውሃ ከኢየሩሳሌም ይፈሳል ግማሹ ወደመጀመርያዋ ባህር ግማሹ ወደኋለኛዋ ባሕር ይፈሳል በዛን ጊዜ አንድ እግዚአብሔር ይባላል ስሙም አንድ ይባላል። የእግዚአብሔርን ስም በንፁህ ልቡና የሚጣራ ሁሉም ይድናል ብሏል ።'),
  ('58a0ca1b-df90-5b66-a124-1fa49f129f54', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 6, 6, 'በሱ መዓዛነት ሐዋርያት መልካም መዓዛነታቸው ከምሥራቅ ከ እስከምዕራብ ከሰሜን እስከደቡብ ያለውን ዓለሙን ሁሉ መልካም መዓዛ እንዲኖረው አደረጉ ።'),
  ('607abf1e-24a2-5a00-a827-c02e19ecf6db', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 7, 7, 'ይህን አስመልክቶ ሐዋርያ እንዲህ ብሏል እኛ የክርስቶስ መዓዛ ያስን ነን በክርስቶስ ቅዱስ መዓዛም ቅዱሳን በምነና ወደገዳም ይገባሉ። በክርስቶስ መዓዛም ሰማዕት ጥቡአን ሁነዋል ለሞትም ሥጋቸውን አሳልፈው ሠጥተዋል። ዘመድንና ልጅንም ትተው ክርስቶስን ብቻ ተከትለዋል የዚህንም ዓለም ጣዕም ፈፅመው ንቀዋል ።'),
  ('ed51e8a4-4864-5f07-aa47-ff3de685739a', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 8, 8, 'በክርስቶስ መዓዛ የመሃይምናን ልቡና ይሞላል መሬታውያን እያሉም ሰማያውያን ሆነ በምድር ሁነው እያለ ከሰማያውያን ጋር እንዳሉ ሁነው ታዩ የክርስቶስ መዓዛነት ካባቱ፡ ከሰማያት ከመሆኑ የተነሳ በቅድስት ድንግል ማርያም ከርስ አደረ ካባቱ ዘንድም ወደዓለም ተላከ ።'),
  ('5d48891e-31ed-5ff8-a362-c8ed6ed27c7c', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 9, 9, 'የክርስቶስ መዓዛነት ከሙዳይ ወደሙዳይ ተጨመረ ከነቢያት አንዱ ከሙዳይ ወደመዳይ ዕፍረት ከከንፈርህ ይጨምራል ብሏል ነቢዩ ፈሰሰ አላለም ስምህ ከመዳይ ወደመዳይ ተጨመረ አለ።'),
  ('c78b9f2a-a4a4-5466-a29c-9ccfbef204c6', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 10, 10, 'ይህም የመዓዛ መዳይ ዓለምን ሁሉ መልካም መዓዛ አድርጎታል ሙዳዩም የመልካም መዓዛ መዳይ ነው በመልካም መዓዛ የሰው አስምሮ መልካም መዓዛነቱን አይለቅም የክርስቶስ መዓዛም እንዲሁ ነው። እኛ መሐይምናን ሁላችን በሥላሴ የተጠመቅን ምእመናን ሁሉ የሱ መዓዛነት አለን ።'),
  ('bbc9f3f0-def7-591e-a39d-10d7870e316f', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 11, 11, 'ልጄ ቀሌሚንጦስ ሆይ ስማኝ ጌታችን ኢየሱስክርስቶስ የሰማያትና የምድር ጌታ ዓለምን ሁሉ የፈጠረ በኋለኛው ዘመን ብዙዎች ሃይማኖታቸውን እንደሚክዱ ፍቅርም በወንድማማች መካከል እንደምትጎድል ብዙ የሐሰት ነቢያትም እንደሚመጡና ሰውን ከቀናች ሃይማኖቱ በመጥፎ ተግባራቸው እያሳሳቱ እንዲርቅ እንደሚያደርጉ ይህንንም የሚደርጉት በረከሰው እምነታቸው እንደሆነ ነገረኝ'),
  ('3602f0ec-3793-5d83-ae04-aa459e0e3872', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 12, 12, 'የዓለም መጨረሻ ሲቃረብ እነሱ መጥፎ ሥራን ያመጣሉ ይህም ከቅድስት ቤተክርስቲያን ሥርዓት ውጭ ነው በዚህ ጊዜ ሠይጣን መግቢያ ያገኝና ሰዎችን የማሳሳት ተግባሩን ይቀጥልበታል እነሱንም መሣርያ እያደረገ ሰዎች እንዲሳሳቱ ያደርጋል በቃላቸውም መንገድ እያገኘ ይሄዳል የተሳሳቱም ያለቅሳሉ'),
  ('bec9810a-2682-59aa-aa01-91d35f86d13c', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 13, 13, 'የሚስቱት ብቻቸው አይደሉም ሌሎችንም ያሳስታሉ ተንኮለኛች ናቸውና በዚህ ጊዜ የእግዚአብሔርን መንጋዎች እንዲጠብቁ የተመደቡት እረኞች ካህናት መንጋዎቻቸውን የሚበትነና ከንሥሐልጆቻቸው ንሥሐን የማይቀበሉ ይሆናሉ።'),
  ('b03d3395-2743-5d7f-a323-8758a8131fc1', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 14, 14, 'ይህን በመሰለ አካሄድ ሕይወታቸውን ለሚመሩ ካህናት እግዚአብሔር ለፍርድ በሚመጣበት ጊዜ ከፊቱ በሚቆመበት ጊዜ ወዮላቸው ከሁሉ አስቀድሞ እግዚአብሔር ከገሠፃቸው በኋላ ወደዘለዓለም እሳት ያሰናብታቸዋል ከነሱ በኋላ ደግሞ ትእዛዙን ያልጠበቁትን ሁሉ ይገሥፃቸዋል ካህናቱን ተከትለው ገሐነመእሳት እንዲወርዱ ያደርጋል'),
  ('7fabeb72-496b-5c07-a404-bd278fc604ad', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 15, 15, 'በዚህ ወቅት ሥራው ክፋት ብቻ የሆነ ንጉሥ ይመጣል ከምዕራብ በኩል ፀሐይን ያወጣል ጨረቃን ደግሞ ከድርጊት ማውረጃ ያወጣል (ኤላም የድርጋት ማውረጃ ብሎታል መዝገበቃላቱ) በዚህ ጊዜዛብሎንና ንፍታሌም አንገታቸውን ያስረዝማሉ ቅፍርናሆም ትመካለች ኮራዚና ቤተሳይዳ ይደሰ።።ሉ ይህን በእከይ የተነሳው ንጉሥንም ክርስቶስ ነው ይሉታል በኋላ ግን ይህንን የጥፋት አካሄዳቸው ሲመለከቱ፡ እጅግ ያፍራሉ።'),
  ('34899256-303c-5589-a005-f550c2e31ae2', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 16, 16, 'ይህ የሐሰት ንጉሥ አመራሩ የተበላሸና በአድላዊነት የተበከለ ነው። በዚህ ጊዜ የሰው ሐጢአት ከመብዛቱ የተነሳ ተፈጥሮ ታምፃለች እግዚአብሔር ዝናምን ይከለክላል ክረምት ያደርቃል ምድር ያለጠልና ያለልምላሜ ትቀራለች በዝናም ምትክ በምድር ላይ አቧራና ትብያ ዓየሩን ይሸፍነታል።'),
  ('b2a02fd0-d3ac-50a5-a7b4-e03b222bc5b7', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 17, 17, 'የውሃ ምንጮች ውሃን አያመነጩም ባሕር ይደርቃል እነዚህ ክፉ ቀኖች ግን ያጥራሉ እነሱ ባያጭሩ ነፍስ ያለው ፍጡር ሁሉ ባልዳነም ነበር። ነገር ግን በእግዚአብሔር ስለተመረጡና በእግዚአብሔር ፈቃድ ሕይወታቸውን ስለመሩና ቅድስናውን ስላላረከሱ ቅዱሳን እነዚህ ዘመኖች ያጥራሉ ።'),
  ('293aa605-56d2-512c-a757-b8ce8abefdfe', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 18, 18, 'ይህ መሥሐቲ ንጉሥ አስቀድሞ የታላቁ ንጉሥ አገር በሆነችው ኢየሩሳሌም ላይ ምስሉን በማስቀመጥ ስገዱልኝ ይላል ቀጥሎ መሥዋእት በተፈፀመባቸው ሁሉ እንዲሠገድለት ሕዝቡን ያዛቸዋል ።'),
  ('8a9370b1-b97f-54a7-a497-94421aa1c4e8', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 19, 19, 'ከዚህ በፊት ያስቀመጥኩትን ትእዛዝ አንስቻለሁና ሠርዙት ይሳል ሐሳዊመሲህ ነውና በዚህ ጊዜ የክርስቶስ ወንጌልና ጳውሎስ። ግብረሐዋርያትንና የሕግ መጻሕፍትን እንደሻራቸው አልነገረንም በማለት የሱን ሐሳዊመሲሕነት ይረዱታል መጻፎቹን እንደሚደመስሳቸው ክርስቶስ አልነገረንም እስከማለት ይደርሳሉ።'),
  ('fc4e15cc-5c8c-595c-afca-a4f495118e33', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 20, 20, 'ይህንን የስሕተት ቃል አንሰማውም ይላሉ ከዚሁ ክህደት ለመራቅ ሌሎች ቤተሰቦቻቸውንና ዘመዶቻቸውን ትተው ወደየዋሻውና ወደየተራራው በመግባት ይደበቃሉ ለዚሁም መሠረት የሚያደርጉት ነቢዩ ኢሳይያስ ሕዝቤ ሆይ ሂድ ቤትህም ግና የእግዚአብሔር መዓት እስኪያልፍ ድረስም ለጥቂት ጊዜ ተደበቅ ያለውን ነው ሌሎች ደግሞ ፊትለፊት ተጋፍጠው አንገታቸውን ለሠይፍ ይሠጣሉ ሰማዕትነትንም ይቀበላሉ በዚሁ በወንጌል የተጻፈው ይፈፀማል።'),
  ('b57f8caa-1ba0-5ad8-ad27-53a35fe35af5', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 21, 21, 'ከወንጌል የተጻፈው የበለስ ቅርንጫፍ ከለመለመ በዛን ጊዜ ጊዜው እንደደረሰ እወቁ የሚለው ሲሆን የበለስ ቅጠል ብሎ የገለፃቸው እነዚያ የተሰደዱትና ሰማዕትነትን የተቀበሉ ደጋግ ናቸው።'),
  ('a95738c1-d2b5-51b4-aae9-93d2b088b27f', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 22, 22, 'ይህ ከሆነ በኋላ ሄኖክና ኤልያስ ከገነት ወርደው ይሰብካሉ ያንንም ከሐዲ የፅድቅ ጠላት የሐሰት ልጅ ያሳፍሩታል በዚሁም በሠይፍ ይቆረጣሉ ።'),
  ('3b22c6c4-85f0-5ad1-a1f1-7adf27ab5da5', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 23, 23, 'ሚካኤልና ገብርኤልም አንስተው ደስታ ወደተሞላበት ገነት ያስገቡዋቸዋል ከደማቸው ጠብታ አንዷ እንኳ አትነጥብም ።'),
  ('81e41cd2-1de1-5064-aa86-743cbddb6d49', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 24, 24, 'ኋለኛውን ጠላት ግን ወድያው ከመነሳቱ ሞት ይሽረዋል በዚህ ጊዜ እግዚአብሔር ከመረጣቸው ቅዱሳኖቹ ጋር ቃል ኪዳን የገባላትን ቃሉ ለመፈፀም ይመጣል መለከትም በመላእክት አለቃ ሚካኤል አፍ ይነፋል የሚነፋውም ሦስት ጊዜ ነው በመጀመርያው የመለከት መነፋት ወደትቢያነት የተለወጠው ሥጋ ሁሉ ይሰበሰባል በሁለተኛው የመለከት መነፋት ነፍሳት የሠፈሩባቸው አብያተመዛግብት ይከፈታሉ ነፍሳትም ከመዛግብቱ ይወጣሉ ከመዛግብቱ ወጥተውም ወደየራሳቸው ሥጋ ይገባሉ ከእግዚአብሔር ዘንድም ወደነሱ ጠለምሕረት ትወርዳለች።'),
  ('981aeb88-75db-5dc3-ae6f-ad122eddff1c', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 25, 25, 'ይህን ሲያመለክት ኢሳይያስ የጠል መነሻው ካንተ ዘንድ ነው ብሏል በሦስተኛው የመለከት መነፋት መታን እንደዓይን ቅፅበት ፈጥነው ይነሳሉ በጎችን በቀኝ ፍየሎችን በግደራ እንደሚያቆምም ከፊቱ ያቆማቸዋል በግራ ለቆመትና ትእዛዙን ላልጠበቁት ርጉሞች በማለት ዘልፎ ያሰናብታቸዋል ወደመከራና ወደጨለማ ቦታ ለመወሰድም እያለቀሱ አጋንንት ይረከቡዋቸዋል ።'),
  ('472f14a9-39ff-5144-a620-ab5add7d9f52', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 26, 26, 'ጻድቃን ግን በቀኝ ቁመው ፈጣሪያቸውን ካመሰገነ በኋላ ወደዘሰዓለማዊው ህይወት ይገባሉ ከዚሁ ደዌና ሕመም የለም ዳግመኛም በዚያ ሞት የለም ቦታው የተድላና ደስታ ቦታ ነው ደስታቸው አያልቅም ዘወትር እስከዘለዓለም ይኖራል እንጂ ።'),
  ('ea2abec9-bf8d-57cb-ad40-a4e3bb552559', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 27, 27, 'የሐጥአን ሥቃያቸውና መከራቸውም እስከለዓለም አያልቅም ዘወትር ያለመቋረጥ እያለቀሱና እየተሠቃዩ ይኖራሉ እንጂ ነፍሳቸውም ከስጋ አትለይም ።'),
  ('dfb46d2a-2191-5a11-a3cb-42eccf47015c', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 28, 28, 'ይህ ሁሉ የሚፈፀምባት ዕለት አሥፈሪ ዕለት ናት የልቅሶና የፍርሐት ዕለትም ናት ጻድቃን ስለሐጥአን የሚያለቅሱበት ዕለት ናት ሐጢአተኞች ደግሞ ስለሐጢአታቸው የሚያለቅሱበት እለት ናት የሰማይ መላእክትም ስለሐጢአተኞች የሚያለቅሱባት ዕለት ናት በዚች ዕለት ሁሉ ወደየርስቱ ይገባል መልካም የሠሩ የሰሩም ወደሕይወት ማደርያ የሚገቡበት ዕለት ናት ክፉ ወደዘላዓለምኩነኔ የሚገቡበት ዕለት ናት።'),
  ('6ebc8a33-19d0-54bf-ad26-ca107c43bab7', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 29, 29, 'ወንድሞቼ ሆይ ከዚህ በላይ የተገለጸውን አስቡ አስተውሉ ችላ አትበሉት ልቡናችሁም ለእግዚአብሔር ክፍት አድርጉት ይህንንም ስለስርዓተቤተክርስቲያን ስናስተምራችሁ ገልጸንላቹኋል ይህንንም ጌታችን ኢየሱስክርስቶስ ነው ያስተማረን ጌታችን እኔን ከሚያምነ ሁሉ አንዱን ትንሽ ነው ብላችኁ አታቃልሉት ብሉናል።'),
  ('2e957e38-9632-5cb6-aa6d-e4eb30eab046', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 30, 30, 'ጌታችን ኢየሱስክርስቶስ መላእክቶቼ በሰማይ ያለውን አባቴ ዘወትር ያዩታል ብሎናል መላእክት የተባሉት ካህናት ናቸው ልቡናና አእምሮ ያላቸው ካህናት እውነተኞች ካህናት ናቸው እነዚህ ካህናት መኳንንትና ነገሥት ስላስተማሩዋቸው ይንቋቸዋል ያቃልሉዋቸዋል።'),
  ('e832d9ca-7b99-50cc-a4d7-ef6476783fb8', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 31, 31, 'ካህናትን ያቃለሉ ሁሉ እኔ ወደኩነኔ አስገባቸዋለሁ። ካህናቱም ለጥፋታቸው ምስክሮች ይሆኑባቸዋል የካህናት ንግግር አታቃልሉ ነገራቸውን ተቀበሉ እንጂ ካህናት ያዘዙዋችሁን ሁሉ በትክክል ፈፅማችሁ የቅድስት ቤተክርስቲያን ልጅነታችሁን ከጠበቃችሁ ሐጢአት የለባችሁም።'),
  ('5381732c-03ef-53a0-a0e7-ca225f1fe073', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 32, 32, 'ካህናት ሁልጊዜ ሌት ተቀን ስለናንተ የሐጢአት ተግተው ይፀልያሉ እግዚአብሔርንም ከመለመን አያርፉም እናንተም ዲያቆናት እንደ እስጢፋኖስ ሁነ እስጢፋኖስ በመንፈስቅዱስ ልቡ የሞቀ ነው በድንጋይ ሲደበደብ ሰማይ ተከፍቶ ወልድ በአብ ቀኝ ተቀምጦ በማየቱ በደስታ ተሞላ።'),
  ('afa137a7-f9b6-5b63-a2e5-326be4cd59ec', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 33, 33, 'ዲያቆናት እንደእስጢፋኖስ ይሁነ እስጢፋኖስ የክርስቶስ የመጀመሪው ሰማዕት ሁኗልና ዳግመኛም እስጢፋኖስ በመጋረጃ ውስጥ ወዳለው መሥዋዕት ቦታ መንፈስቅዱስ ሲወርድ አይቶ አንፋጨ ዲያቆናትም ልበንፁሆች ሁነው የመንፈስቅዱስ ርደትን በማየት ለማንፋጨት እንዲበቁ ተግተው በትህትና ተልእኮአቸውን ያከናውኑ።'),
  ('2e0efd80-b85e-5765-a293-240986ed05c8', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 34, 34, 'ካህን የመንፈስቅዱስን ፀጋ ላክ ባለጊዜ በቤተክርስቲያን ውስጥ ለመስዋዕትነት በቀረቡ ፅዋዕና ሕብስት ላይ መንፈስ ቅዱስ ይወርዳል (ገፅ ፲፯ በብራናው) ዲያቆናት በቅድስና ሥጋወደሙን ለመለወጥ ሲወርድ ለማየት ይችላሉ። የዲያቆናት ክብር በዚህ ብቻ የተወሰነ አይደለም ቅዱስ እስጢፋኖስ በመንግሥተሰማያት ታላቅ የክብር ቦታ ከእግዚአብሔር ዘንድ ሊሠጠው እንደቻለ ለነሱም ይሠጣል።'),
  ('df9b6814-51ce-5725-a0c8-0d42bef0919b', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 35, 35, 'በዲቁና እንዲያገለግሉ የተሠጣቸውን ተልእኮ በንፅሕናና በቅድስና ሁነው ካላገለገሉ ግን ዕድል ፋንታቸው ዲያብሎስ ከተከታዮቹ አጋንንት ጋር ወዳለበት የጨለማ ቦታ ይገባሉ እስከዘለዓለምም በዚያ ይኖራሉና ።'),
  ('5d8723e4-26fd-5ad6-a29c-678895244da9', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 36, 36, 'ልጄ ቀሌሚንጦስ ሆይ የቤተክርስቲያን ካህናት የሆኑ ሁሉ በመጨረሻው ዘመን ሰው ሁሉ እንደሚቀርብና ይህንንም ህዝቦቹ ፈርተው ከክፉ እንዲጠበቁ ይመክሩዋቸው ዘንድ እዘዛቸው በቤቱ ጣዖት አስቀምጠ የሚያመልከው ካለ የተረገመ ነው እንዲሁም በወፍ የሚያሟርትና ሌላም ተመሳሳይ ጣዖት መንገድን የሚከተል ሁሉ የተረገመና የተወገዘ ነው።'),
  ('9a235a50-4ab4-55b5-a0da-6dfbaa8a4eb0', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 37, 37, 'አባትንና እናቱን አክብሮ የማይታዘዝና በፈለጉት ሁሉ ትእዛዛቸውን የማይፈፅም ልጅ የተረገመ ነው ወላጆች በልጆቻቸው ክፋት ወደእግዚአብሔር ይጮኻሉ እግዚአብሔርም ያዝንላቸዋል።'),
  ('61d49d64-64cf-5780-ac9c-2c0469ecbb31', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 38, 38, 'ዐይነሥውሩን ትክክለኛውን መንገድ ከማሳየትና ከመምራት ይልቅ ወዳልሆነ አቅጣጫ የሚመራ የተረገመና የተወገዘ ነው። መስማት የተሳነውንም አይሰማኝም ብሎ ያልሆነ ንግግርንና ስድብን የሚናገርም ርጉም ነው።'),
  ('ceaea988-6af8-53f9-ad5f-8f4ed572a68f', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 39, 39, 'ጌታችን ኢየሱስክርስቶስን የማይወድ። በአብ በወልድና በመንፈስቅዱስ እንዲሁም በቅድስት ቤተክርስቲያን የማያምን የማይቀበል የተረገመና የተወገዘ ነው።'),
  ('991316c7-7388-5bd6-a8f9-b4ef557f2965', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 40, 40, 'ሰማይንና ምድርን ባሕርንና የብስን በውስጣቸው ያለውም ሁሉ የፈጠረ እግዚአብሔር መሆኑን የማያምን እንዲሁም አብ 223 አባትመሆኑን ወልድም ከዓለም በፊት ጀምሮ ልጅ መሆኑን የማያምን የተረገመ ነው።'),
  ('a18b6e99-39ee-572f-a743-3a51caf96e2a', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 41, 41, 'ሦስተኛው አካል መንፈስ ቅዱስ ከአብ እንደወጣ ሦስቱ አካላት ባንዲት ምክር ሰማይንና ምድርን እንደፈጠሩ የማያምን የተረገመ ነው።'),
  ('6425be0d-4958-5b36-a445-2887e0c6b0a4', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 42, 42, 'በእግዚአብሔር ቃል ሰማዮች ፀነ በአፉ እስትንፋስም ኃይላቸው ሁሉ ቆመ ያለውን ስማ። እግዚአብሔር በመለኮቱ ሰማያትንና ምድርን የሞላ መሆኑንና ዘለዓለማዊ መሆኑን የማያምን የተረገመ ነው።'),
  ('de008ce0-4f72-5141-a37b-6a1df3535866', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 43, 43, 'እግዚአብሔር ባልተባረከ ቦታ አይገኝም የሚል ካለ እግዚአብሔር ሁሉን የሚቀድስ እንጂ የሚረክስ ወይም የሚያረክስ አይደለም የሚለውን አላስተዋለምና የተረገመ ነው።'),
  ('a02ab0b9-afd0-5605-a058-9c89712fee78', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 44, 44, 'ክርስቲያኖች ስሕተት መስለው የማይታዩትንም እንዳይፈፅሙ እዘዙዋቸው እነሱም በዓይን በማየት በጆሮ በመስማትና በእጅ በመዳሰስ የሚፈፀሙ ናቸው በንግግር የሚፈፀም ሐጢአትም ከነዚሁ ይቈጠራል እነዚህ ወደሐሰትና ወደሥርቆት ስለሚወስዱ በፈፀማቸው ላይ ርኩሰትን ያመጣሉ።'),
  ('77c75ee6-149b-5f63-acb2-5b9071a86f36', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 45, 45, 'ክርስቲያን ሁኖ ወደዘፈንና ወደ ጭፈራ ቤት ከገባ ለተወሰነ ጊዜ ወደቤተክርስቲያን እንዳይገባ ይከላከላል ከካህናት ንሥሐውን ከተቀበለ በኋላ ግን ወደቤተክርስቲያን ይግባ።'),
  ('44fbb775-5d2d-5a27-a973-65972a6ae4e8', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 46, 46, 'እግዚአብሔር በፍፁም ሕሊናቸው ለሚመለሱ ነሳሕያን 224 ጌታቸው እኔ ነኝ ። አለ። ሐጢአተኛው ንሥሐ ከገባ እቀበለዋለሁ አለ። ለመት ልጆችና ለድሖች ፍርድን የሚያጓድል እጅግ የረከሰ ነው ሰው ጥቃት እየደረሰው እያየ የማይገለግለው የተወገዘ ነው ኀጢአተኞችና አስገባሪዎችስ ነጣቂዎች ናቸው።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('f7c9cdd8-e22a-5ca0-ab2e-a260a78d019b', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 47, 47, 'ከቤተክርስቲያን ንብረት የሰረቀ ሰው ቢገኝ ከሠረቀው በአምስት እጅ አብልጦ ይከፈል ከዚያ በኋላ ንሥሐ ይግባና ወደቤተክርስቲያን ተመልሶ ከማሕበር አንድነት ይነረው። በአገልግሎት ሊቃውንትን የሚያቃልል ርኩስ ነው እነሱ ለቤተእግዚአብሐር የሚታዘዙ ናቸውና።'),
  ('4ed60b92-9595-505a-ad04-2e1e340f789c', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 48, 48, 'የካህናትን ሥልጣን ለማግኘት መማለጃ የሚሠጥ የረከሰ ነው ይህንን በማድረጉ ከቤተክርስቲያን ይባረር በንሥሐም ይመሰስ ቄስንና ዲያቆንን የሚደበድብና ሌላም በደል የሚፈዕም የረከሰ ነው።'),
  ('13769dc5-a2b8-5020-ac0d-aaaa2e35a7ac', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 49, 49, 'ቤተክርስቲያን መላእክት ከቅዱሳን ማሕበር ጋር ባንድነት እግዙአብሔርን የሚያመሰግኑባት ናት በሰማያዊው ሙሽራም ደስ ይሰኙበታል እኛም በሮቿንና መንገዶቿን በጥንቃቄ እንጠብቅ የሰማያዊው ንጉሥ ሙሽራ የክርስቲያን ነፍስ ትባላለች። ይህም በመከታተል ነቢያት ተናግረውታል ከዕዝራ ምሥጋና ከዳዊት ከበሮና መሰንቆ ለቤተክርስቲያን ተዘጋጅተዋል።'),
  ('95413e3a-5ee5-53a1-a8a7-50ae12a1bf79', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 50, 50, 'እኛም በቤተክርስቲያን ኃይል ልቡናችንን እንጨምር እንከተላት ሰላምም እንበላት ስለዚህም ጌታችን መድሐኒታችን ኢየሱስ ክርስቶስ እንዲህ ሲል አዞናል። በአሕዛብ መንገድ አትሂዱ ወደሳምር አገርም አትግቡ ሀገረሳምር ማለት እሥራኤሎች በናቡከደነፃር ተማርከው የተወሰዱበት አገር ነው እስራኤሎች ወደዚሁ ሲሰደዱ ከንጉሣቸው ጋርና ከካህናቸው ኤርምያስ ጋር ነው። ካህኑ ኤርምያስ ከሕዝበ እሥራኤል ጋር አብሮ የተሠደደው እስራኤሎች ቃለእግዚአብሔር እንዲያስታውሳቸው ነው።'),
  ('c56f8bd9-df8e-5b5a-a15b-d186cd040513', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 51, 51, 'ሕዝበ እሥራኤል ተማርከው ከተወሰዱበት አገር እንዲመለሱ እግዚአብሔር ፊቱ ስለመለሰላቸው እግዚአብሔር ይቅር ብሉናልና በኛ ላይም ነግሦ ካህናትን አማካሪዎች መኳንንትን እንደቀድመው ሊሠጠን ፈቅዷልና ሕዝባችን መርተህ ተመለስ ከሓዲዎችን ግን አታምጣ ባሉበት ይቅሩ በማለት አቤሜሌክና ባሮክ ከኤርምያስ ላኩለት።'),
  ('e2c6db67-58e3-584b-a163-fc51fc3a730c', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 52, 52, 'ልጆቻችሁን ለከሐዲዎች ልጆች ልትሰጡ የነሱንም ሴቶች ልጆች ለወንዶች ልጆቻችሁ አታጋቡ ይህን ካደረጋችሁ እግዚአብሔር ተቈጥቶ እንዳለፈው ጊዜ ሁሉ ለዳግም ስደትና ለዳግም መከራ ይዳርግናል።( ባሮክና አቤሜሌክ) ።'),
  ('8b0a2130-a6f6-5913-a7b5-d05eef8f358b', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 53, 53, 'ኤርምያስ ወገኖቹን ይሰብካቸው ጀመር እንዲህም አላቸው ከከለዳውያን ለልጆቻቸው ያገባቹኋቸውን ሴቶች ልጆች ተው ከከለዳውያን ሴቶች ልጆች የሠጣቹኋቸውንም ወንዶች ልጆች መልሱ።'),
  ('4a6739e5-303d-54f2-a754-6743f33b7af9', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 54, 54, 'ለጊዜው ለኤርምያስ እሺ አሉት ወደትልቁ ንጉሥ አገር ከምድረ ኤየሩሳሌም ለመመለስ ከምድረከለዳውያን ተነሱ። ከለዳውያንም ተነስተው ለሦስት ቀን እንደተጓዙ ከከለዳውያን ያገቡዋቸውን ሴቶች እንዳልተው ለኤርምያስ ተነገረው። በዚህ ጊዜ ኤርምያስ የእስራኤልን ልጆች ለምን የከለዳውያንን ሴቶች ይዛችሁ መጣችሁ በማለት ተቈጣቸው። በዚህም ጭቅጭቅ በመካከላቸው ተፈጠረ።'),
  ('57099680-d95e-5033-af8a-ef82a8e62c51', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 55, 55, 'ካህን ኤርምያስ ልጆቻችንና ሚስቶቻችንን እንተዋለን የምትሉና አንተውም የምትሉ ተለዩ አላቸው። በዚሁም ለሁለት ተከፍለው ቆሙ ማለትም ግማሾቹ ከልጆቻችንና ሚስቶቻችን ተለይተን አገራችን እንገባለን ሲሉ የቀሩት አንለይናም አሉ።'),
  ('8f025298-8c1a-50b2-a025-fba4f76ad72d', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 56, 56, 'ሚስቶቻቸውንና ልጆቻቸውን ለመተው ፈቃደኞች የሆነ ከኤርምያስ ጋር ወደኢየሩሳሌም ተመለሱ የቀሩት ግን ኤርምያስን ከወደድከን ከልጆቻችንና ከሚስቶቻችን ጋር ውደደን ካልሆነ ግን ከቤተሰባችን አንለይም ወደነበርንበት እንመለሳለን አሉት።'),
  ('dbbd740e-1226-5ff5-a568-bcd7c3fef9d1', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 57, 57, 'ይህንን ብለው ለኤርምያስ ከነገሩት በኋላ ተመልሰው ወደነበሩበት ምድረከላዳውያን ገቡ። ከላዳውያን የነሱን መመለስ ሲያዩ አገራችን ትተው የወጡ እስራኤል ተመልሰው ስለመጡ እንዳይገቡ እንከልክላቸው በማለት ጦርን በመያዝ እነሱን መልሶ ለማባረር ሆ ብለው ተነሱ። እንዲህም አሉዋቸው ቀድሞውን እኛ ሳናባርራችሁ ትታችሁን ሄዳችሁ አሁን ግን ተመልሳችሁ ብትመጡ አናስገባችሁም አሉዋቸው።'),
  ('b9347ee3-c8d7-5b8c-a6e9-67cd92148491', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 58, 58, 'ይህም ብለው መልሰው አባረሩዋቸው እነሱም ከኤርምያስ ጋር ለሶስት ቀን ተጉዘው ከደረሱበት ደረሱ በዚሁም ለመቀመጥ ወደዱ በዚሁም እቺ አገር ሀገረሳምር ተባለች።'),
  ('ccef5af3-4b50-5218-a130-5a77970c2e36', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 59, 59, 'ጌታችን ወደአሕዛብ አገር አትሄዱ ወደሳሞር አገርም አትግቡ ብሉ በወንጌል አዞናል ይህንንም እንሰብካለን የአሕዛብ መድ እጅግ ሰፊነው ወደጥፋትም ይወስዳል። እሱም ስስዕትን ዝሙትን መጠጥን። ስካርን በሐሰት መማልን ዘፈንንና ተውኔትን ጨምሮ ሌሎችንም ያጠቃልላል።'),
  ('ea79d90d-2010-57e7-a452-c5686bc8aa3e', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 60, 60, 'ጌታችን አሕዛብን እንድናስተምራቸው ያዘዘን ግን በጠበበወ መንገድ ይሄዱ ዘንድ ነው። እቺም ጠባብ መንገድ ወደሕይወት የምትወስድ ናት በሷም ውስጥ ትሕትና የዋህነት ይቅርባይነት ምሕረት ፍቅር ሰላም ጾም ፀሎት ድሃን መጐብኘት ምፅዋትን መመፅወት ጠላትን መውደድና ይህንንም ሁለ የመሰሉ የቅድስና መንገዶች ናቸው።'),
  ('d83f2b9f-f834-5ea5-a7e3-833080152474', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 61, 61, 'ይህ ፀባብ በር ወይም መንገድ ወደ ዘለዓለም መንገድ የሚመሪ ነው። የዘለዓለም ሕይወት ያለበት ቦታም ነው። የሰው ጠላቴ ሰው ነው። ባንድ ቤት ቤተሰቦች ቢኖሩ አንድ ጠባይ ስለሌላቸ እየራሳቸው ይለያያሉ።'),
  ('70562889-89b0-551b-a8a6-f1b458715bf4', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 62, 62, 'ጌታችን ላገር ሰላምን አላመጣሁም ያለው የሰዎ ከዘመዶቻቸው ስለስሙ መለየታቸውን መሠረት በማድረግ ነው።'),
  ('ddab8b16-0b40-55a3-a962-7221786f8b1e', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 63, 63, 'ጌታችን እኛንም እስከምድር ዳርቻ ድረስ እናስተምር ዘንድ አዞናል ከዚሁም ላይ ትምህርታችንን የሚቀበሉም ወደዘለዓለም ሕይወት ይገባሉ ትምህርታችንን አንቀበልም ያሉት ደግሞ ወደዘለዓለም ሥቃይ ይገባሉ መከራቸው በራሳቸው ላይ ናት በኋላ ዘመንም ወቀሳቸውን ተቀብለው ወደዘለዓለም ጨለማ ይገባሉ። ቃላችን ወልድ ካባቱ የነገረን ቃል ነው ተራንግግር ባዶ አይደለም።'),
  ('38d30296-17ff-503c-a19c-767905a80ec0', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 64, 64, 'ጌታችን ይህን አስመልክቶ አይሁድን እንዲህ አላቸው መጥቼ ባልነግራቸው ኑሮ በሚፈፅመት ስሕተት ለኩነኔ ባልተደረጉም ነበር። አሁን ግን መጥቼ ስለነገርኩዋቸው ላለማመነናቸወ ምንም ምክንያት የላቸውም ያለየርጥር ይኵነናሉ ልበዝንጉኦች ይህን ዓለም በዋዛ ፈዛዛ ስላሳለፉት የሚጠብቃቸው ገሐነመእሳት መውረድ ብቻ ነው።'),
  ('c6dd264b-994e-5213-a677-6d19817502f9', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 65, 65, 'ጌታችን ወንጌልን እንሰብክ ወደዓለም በላክን ጊዜ እናንተ የተቀበለ እኔን ተቀበለ እኔንም የተቀበለ ደግሞ የላከኝን ተቀበለ አባቴና እኔ አንድ ነንና እናንተ የምትሠጡትን ትምህርት የተቀበሉ ሁሉ እኔን ተቀብለዋል። ብሎናል ስለዚህ እኛ ተቀብለው ትምህርታችንን የሰሙ ሁሉ በመንግሥተሰማያ እንቆምላቸዋለን ቃላችንን ጠብቀዋልና።'),
  ('9b6ce529-bc15-5e1e-a8c7-9d696e39ef11', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 66, 66, 'እኛ የእግዚአብሔር ሥርዓት መጋቢዎች ነን። የእግዚአብሔ ልጆች ምዕመናንንም በኛ የተሠሩ (ሥርዓትን የተቀበለ 229 ይሆናሉ። እኛ ከአምላካችን በአደራነት ተቀብለናቸዋልና እግዚአብሔር ለሙሴ የቅድስት ደብተራን ዕቃዎች ለሌዊ ልጆች በአደራነት አስረክባቸው እንዳለው።'),
  ('1103945f-1f38-514f-a2f0-3934fbe8411e', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 67, 67, 'ዳግመኛም እግዚአብሔር ከሱ ጋር ለመናገር ይችሉ ዘንድ አርባ ቀንና አርባ ሌሊት ከፆመ በኋላ በደብረ ሲና ከተናገረው ባላነሰ ሁኔታ እግዚአብሔር መሴን አናግሮታል።'),
  ('e4dd88aa-7d30-570f-a0cc-3b28860e137c', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 68, 68, 'ሙሴ ራሱ እህል ሳልበላ ውሃ ሣልጠጣ አርባ ቀንና አርባ ሌሊት የእግዚአብሔርን ፍርድ ሳዳምጥ በፍርሐትና በድንጋጤ ቈየሁ በቅድስት ደብተራ እንዴት ለመኖር እንደምችልም ከእግዚአብሔር ትእዛዝ ተነግሮኛል እቺንም ድንኳን አስቀድሞ የሠራት ናት ።'),
  ('4485cef5-7c51-570b-ad92-afccfb8c6d63', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 69, 69, 'በቅድስት ድንኳን የምትመሰለው የክርስቲያኖች ነፍስ ናት እቺም የክርስቲያኖች ነፍስ እግዚአብሔር አብ በመሲሁ ደም የዋጃት ናት ዳግመኛም መሴ በደብረሲና ዕፀጳጦስ በእሳት ስትነድ አየሁ አለ እሳቱ ከዕፀጳጦሱ በስተ እግርጌ ይነድ ነበር።'),
  ('f78a458d-9cb6-57b9-ac93-6782fc521d8b', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 70, 70, 'እኔም አስፈሪነቱን ለመረዳት ካጠገቡ ቀረብኩ በዚህ ጊዜ ከዚህ እሳት ቃል ተሰማ ቃሉም ጫማህን ከእግርህ አስወግድ የምትረግጣትና የቆምክባት ምድር ቅድስት ናትና የሚል ነበር።'),
  ('dc1cb18c-8907-58ba-a9bb-40a555904ff9', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 71, 71, 'እሷም ቅድስት ቤተክርስቲያን ናት እዝራም በሴት አምሳያ አዝናና ተክዛ አይቷታል ባያት ጊዜ ግን ሴት አልነበረችም ስለልጆቿም ታለቅስ ነበር። እሷ ሀገር መንፈሳዊት እሷም ቅድስት ቤተክርስቲያን ናት ቅርንጫፎቿ የዘይት ቅርንጫፎች ሁነው በግራና በቀኝ ከበዋታል።'),
  ('533efc79-ca69-52d6-a566-fddc6362c698', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 72, 72, 'ዘካርያስ ተቅዋመማሕቶትን አይቷል እቺ ተቅዋም ሁለንትናዋ ወርቅ ነበረች ተቅዋመ ማሕቶት የተባለው መሽራው ክርስቶስ ነው እሱም የቤተክርስቲያን መሽራ ይባላል። መብራቶቿ የተባሉት ደግሞ ሐዋርያት ናቸው በግራና በቀኟ መቆማቸው ስብከታቸውን ሲያሳይ ቀኝ እጃቸው እንደምሰሶ መባሉ ክርስቶስን ሲሰብኩ መኳንንትንም ሆነ ነገሥትን አይፈሩም ለማለት ነው።'),
  ('26f39faa-b98e-5ebe-a350-b111ffa6e199', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 73, 73, 'በግርፋት። በሠይፍ በመቁረጥ በድንጋይ በመደብደብ ሐዋርያት የሥጋ መከራ ሲደርስባቸው ያነሱት ቀኝ እጃቸውን አላጠፉም ማለትም መከራውን በመፍራት ወደኋላ አላሉም ስለ እግዚአብሐር የቆሙ ናቸውና ሰማዕታትም የነሱን ፈለግ ተከትሏል።'),
  ('1d899082-40d4-5d10-a0d3-6f940d1e0522', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 74, 74, 'የዚህን ዓለም ጣዕም የማይንቅ ሰው ይህ ዓለም እንደሚያልፍ በግብር ለመግለፅ ያልቻለ ሰው ከቅድስት ቤተክርስቲያን አይደለም ከተቻላችሁ ስለሃይማኖታችሁ ሥጋችሁን ለመከራ አሳልፋችሁ ሥጡ በቅድስት ቤተክርስቲያን ህግም ፀንታችሁ ኑሩ።'),
  ('ff6955d2-41c1-5fd6-a8ad-a6c8c342d790', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 75, 75, 'እግዚአብሔር የቅድስት ቤተክርስቲያን ልጆች የሆኑ ሁሉ የእውነት ንሥሐን እንዲያደርጉ አዘዘ በሕይወት ዘመናቸው ከንሥሐ እንዳይርቁ አዟል ይህን ካደረጉ ከጌታችን ጋር ሲደሰቱ ይኖራሉ።'),
  ('89c654a0-a741-53a9-ad0b-d701eeac667d', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 76, 76, 'ምድረገነት በአበቦች መዓዛ ተሸልማ የተባለው አበቦቹ እንደዚህ ዓለም አበቦች አይደሉም የመዓዛቸው ጣዕም ከምድራዊ አበባ ሁሉ ልዩ ነው። የገነት ፍሬም ከማር ወለላ የበለጠ ጣዕም አለው። ይህን ለማግኘት የሚችሉት የቅድስት ቤተክርስቲያንን ሥርዓት የጠበቁ ብቻ ናቸው።'),
  ('4975e368-1274-549d-ab29-565ce9bd3ee8', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 77, 77, 'ሴቶች በባሎቻቸው ላይ አይታበዩ ባልቴቶችም መልካም መንፈሳዊ ለዛ ያለውን ንግግር ይናገሩ ከደግ ሰው መሥጠትንና መልካም ነገር መናገርን ይገኛሉ በንፁሕ ልቡና በብሩህ ገፅ ለድሆች ሥጦታን በማድረግ እግዚአብሔርን ማገልገል ይቻላል።'),
  ('519ea7ee-bda7-53c1-a890-c72e574538f7', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 78, 78, 'አንተም ደግ ሁን ወደሰማዕታት ማደርያ ትገባ ዘንድ እንዳንተ ሰዎች ልቡናቸውን በጥብአት ስለሞሉ ዓለም ሳይፈጠር እግዚአብሔር ወዳዘጋጀላቸው የሕይወት ማደርያ ሊገቡ ችለዋል አንተ ካሁኑ ጀምረህ በምትበልጠው ፀጋ ቅናት ይደርብህ ይህንን ካደረግህ ቅዱሳን ሰማዕታት ወደሚገቡበት የክብር ቦታ ልትገባ ትችላለህ።'),
  ('3f44b65a-2107-5237-a012-fef11c1e9f22', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 79, 79, 'የቤተክርስቲያንን ህግ ጠብቁ በእግዚአብሔር ትእዛዝም ነሩ። ከቤተክርስቲያን ውስጥ ገብቶ ሥርዓትን መጠበቅ ካልቻለ ዲያቆን ያስወጣው ይህን አይተው ለሌሎች እንዲጠብቁ ኤጲስቆጶስ ሁኖ በቤተክርስቲያን ከሚካሄደው ስብሐተ እግዚአብሔር ወደኋላ ካለ አቋርጦ መግባት የለበትም።'),
  ('21514ee5-3130-596e-a160-e5e9862f8323', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 80, 80, 'ቤተክርስቲያን የገባ ሁሉ ካህኑ ሳያሰናብት አቋርጦ መውጣት በዚ የተከለከለ ነው። እንዲሁም ቤተክርስቲያን ውስጥ ገብቶ ቃለ እግዚአብሔርን ማዳመጥ ሲኖርበት ሌላ ተራ ጨዋታ ከጓደኛውጋር የሚጫወት እግዚአብሔርን ማቃለሉ እንደሆነ ሊረዳ ይገባል በቤተክርስቲያን ውስጥ የሚነበብ ቃለእግዚአብሔር ከማር ወለላ የበለጠ ጣዕም አለው።'),
  ('7c1b4588-b921-5636-a16b-85a2460fd598', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 81, 81, 'ከመስጠት መልካም ቃል ይበልጣል ደገኛ ሰው ግን ሁሉንም አጠቃሎ ይይዛቸዋል። እግዚአብሔር ሁለቱንም ያጠቃለለ ሰው ይወደዋል ያከብረዋልም ልቡናው ደስ ሳይለው የሚመፀውት ሰው እግዚአብሔር ዘንድ እጅግ የተወደደ አይሆንም።'),
  ('4a3052f2-4b21-5b72-a651-310f224a6888', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 82, 82, 'በደስታ ከልቡናው በመነጨ መንፈሳዊነት ምዕዋትን ለሚሠጥ መንግሥቱ ሰማያት ትከፈትላታለች ችግረኞችን ባልቴቶችንንና የሙት ልጆችን በንቀት ሳይሆን በጓደኛነትና በፍቅር ይመለከታቸዋል እነሱም የመንግሥተሰማያትን የጣመ ፍሬ ወደ አፉ ያስገቡለታል።'),
  ('35c5d4e1-2d62-5ef4-a254-875651ae0f5a', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 83, 83, 'አንተም ሰማዕታት ወዳሉበት ቦታ የመግባት ዕድል እንዲኖርህ መንፈሳዊ ጥብአት ይደርብህ። ሰማዕታት እንዳንተ ሰዎች ናቸው ነገር ግን ለሥጋዊ ሕይወታቸው ምንም ሳይሳሱ እጅግ የመረረውን መከራ አልፈው ለሰማዕትነት በቅተዋል። ዓለም ሳይፈጠር እግዚአብሔር ያዘጋጀላቸውንም ቦታ ወርሰዋል አንተም በዚሁ ቅናት ይደርብህ።'),
  ('045f6883-9d4f-5513-a1e0-5268420157fa', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 84, 84, 'በሐጢአት ሥጋውን ያረከሰና ንፅሕና የሌለው ሰው ንሥሐ ክ 233 ሳይገባ ወደቤተክርስቲያን አይግባ። መሥዋዕት በሚያዘጋጁበትና ምሥጢራት በሚፈፀሙበት የእግዚአብሔር መንፈስ አይለይም በንፅሕና ሁኖ ስመእግዚአብሔርን የሚጠራ ሁሉ ይድናል። ፀሉትን የሚቀበል የእግዚአብሔር መንፈስ ከዚያ አለና ይህም የእግዚአብሔር መንፈስ መሥዋዕት አሳራጊዎችና በንፅሕና የሚፀልዩትን ይቀድሳቸዋል።'),
  ('bb494f54-8498-5fe9-a354-6a0959976c6c', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 85, 85, 'ከወንድሞቻችን መካከል በኃጢአት ቁራኛ የተያዘና በመጥፎ ሁኔታ የተበከለ ብታገኝ የባሰውን በተስፋ መቁረጥ እንዳይሞት አታቃልለው። እንድያውም እሱን ከወደቀበት የሐጢአት ማጥ እስክታወጣው ድረስና በእጅህ እስክታስገባው ድረስ ራስህን ሐጢአተኛ በመምሰል ግለፅለት በተቻለህ መጠንም ከሐጢአቱ ለማላቀቅ ሞክር ከሐጢአቱ እንዲላቀቅም ምከረው።'),
  ('c8b48d2b-03f1-5f84-a896-298cbfd47e08', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 86, 86, 'መልካም ትህትናንም እያሳየህ ወደካህን አድርሰው ካህኑም ንሥሐገብቶና ከልቡ ተፀፅቶ ወደቤተክርስቲያን በሚመጣው ተነሣሂ ላይ ከባድ የንሥሐ ቅጥጣትን አያሻክመው የተሠጠውን ቅጣት ከዓቅሙ በላይ ሁኖበት እኔን ትቶ ተመልሶ እንዳይሽሽ መጠንቀቅ ያሻል የተነሣሂ ሐጢአትን ይቅር የምል እኔ ነኝ ። ንሥሐ አልገባም ለሚልም የምበቀለው እኔ ነኝ።'),
  ('2cbe185b-62e0-5800-a42a-f390ec2a1675', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 87, 87, 'ጳጳሳትና ቀሳውስት ሆይ መንጋዎቻችሁን ጠብቁ ይህን ካላደረጋችሁ እግዚአብሔር ይቈጣቹኋል የነሱንም የጥፋት ደም ከናንተ ይከፈላል ዲያቆናትም ተልእኮዋቸውን በንፅህና ካላከናወኑ። ከእግዚአብሔር የሚጠብቃቸው ቅጣት ከባድ ነው።'),
  ('859699d7-b4fc-5984-a158-544f9753b434', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 88, 88, 'አንተ ግን ጠማማውን ልብ እንዲቀና አድርግ በዚሁም የእግዚአብሔርን መንጋ ጠብቅ በዝቅተኛ ደረጃ የምትገኝ ብትሆንም በመልካም አንደበትና በጣፈጠ አነጋገር ቃለእግዚአብሔርን በማስተማርህ ከፍ ትላለህ።'),
  ('81296d37-7a0d-5582-a695-302bfcb73dc9', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 89, 89, 'ቤተክርስቲያን የእግዚአብሔርን ህግ ለሚጠብቁ መሐይምናን እናታቸው ናት እግዚአብሔርም ክብርንና ምስጋናን ያጐናፅፋቸዋል።'),
  ('ecf77582-193d-52e3-a7ff-e347a6cfebd3', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 90, 90, 'የቤተክርስቲያን ሹማምንት ሆይ የእግዚአብሔርን ፈቃድ ለመፈፀም በሕይወት እያላችሁ ተሽቀዳደሙ ለማስተማርና ቃለ እግዚአብሔርን ለመናገር ትጉ ይህንን ካላደረጋችሁ ከሕይወት ማሕደር ትሠረዛላችሁ ወደመትሕተታሕቲትም ትወሰዳላችሁ ቅጣቱ ይህ ብቻ አይደለም አጋንንት እጅና እግራችሁን ጠፍረው በማሠር ወደዘለዓለም ኩነኔ ይወረውሩአቹኋል ከዚሁ እንድትድኑ ትጉ።'),
  ('bd9290fd-334b-5149-a2fa-69e726d5b516', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 91, 91, 'በቅድምያ ለሮም ጳጳስ ሁለተኛ ለኤፌሶን 3ኛ ለእስክንድርያ ዐራተኛ የሉቃስን መንበር ለተረከበ አንጾኪያ ያክብሩዋቸው። ከዚህ አራት መናብርተ ሊቃነጳጳሳት በየክፍሉ የሚኖሩ ቀሳውስትና ዲያቆናት ባመት አንድ ጊዜ በየዓመቱ ይሂዱ የነሱ የመሄድ ምክንያት አንደኛው ያስተማሩባቸውን መጻሕፍት ስሕተት እንዳይኖራቸው በጳጳሱ እንዲመረመሩ ለማድረግ። ሁለተኛ አባታዊ ምክርን ለመቀበል ነው።'),
  ('f0278944-107b-55d9-aee4-71c9f2bc88d8', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 92, 92, 'ትምህርታችሁ ከወርቅ እንደተሠራ መጋረጃ የተዘረጋ ይሁን ቃለ እግዚአብሔርንም አትደብቁ በወንጌል እኔን ከሚያምነና ከሚከተሉ አንዱን አታቃልሉ ተብሏልና።'),
  ('60877227-aa01-56b5-ae42-1a75e80b7bbc', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 93, 93, 'ትልቁን የቤተክርስቲያን ሹመት (ጵጵስናም ይሁን ሊቀጵጵስና) ተቀብሎ ተሹሞ እያለ ሌላ ከሱ በላይ ካልተሰጠኝ በዚሁ መፅናት የለብኝም የሚል ቢገኝ ከቅድስት ቤተክርስቲያን ሹመት ይመተር።'),
  ('8210cdfa-e608-5b9e-aac4-26f38f722788', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 94, 94, 'ከቤተክርስቲያን መዓርጉ ይመተር ያልንበት ምክንያት የተሠጠው መዓርግ የእግዚአብሔርን መንጋዎች እንዲጠብቅበት ብቻ እንጂ እንዲከብርበት ሥልጣን ስላልተሠጠው ነው። ስሕተት ፈፀመ ተብሎም ከነበረበት ቦታ ወደሌላ እንዲዛወር አያስፈልግም ስሕተት ከፈፀመ የእግዚአብሔርን መንጋዎች መጠበቅ ስለማይችል መንፈሳዊ ሥልጣን ትልቅ ትንሽ አይልምና መባረር ነው ያለበት።'),
  ('24fb0ac4-7232-5bb2-a43e-ea9e2034a61b', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 95, 95, 'በየትም ደረጃ ይሁን የተረከበውን ሥልጣን በትክክል የእግዚአብሔርን መንጋዎች ሳይመራበት ጥቅምን በመፈለግ በየትም መዛዋወር የለበትም የቤተክርስቲያን ቀኖና ለሁከት አይደለችም ለመንፈሳዊ ፀጥታና ርጋታ እንጂ የሕይወት ፀጥታም ስለሆነች ወደጌታችን መድሐኒታችን ኢየሱስ ክርስቶስ ታደርሳለች። አስቀድመን እንደገለፅነው ዓለም ባሕር ናት ሞገዶቹም ህሊናዎች ናቸው እነዚህም ህሊናህዎች ሰዎችን ከማወቅ ወዳለማወቅ ያሠጥሙታል።'),
  ('5b1de001-805d-545b-a2c1-4d1f7d065d26', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 96, 96, 'እኛ የቤተክርስቲያንን ልጆች ወደጌታችን ኢየሱስክርስቶስና ወደደስታ ገነት እናደርሳቸዋለን ወንድሞቻችን ሆይ ከእግዚአብሔር ትእዛዝ እንዳትወጡ በእግዚአብሔር መታመን አለባችሁ። ባለንጀሮቻችሁንም ከክፉ መንገድ ይርቁ ዘንድ ቃለእግዚአብሔርን አስተምሩዋቸው በመሽራው ሠርግም እንዲደሰቱ አድርጉ።'),
  ('347422e5-ab80-5047-a998-c13b99bd3e71', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 97, 97, 'ዳግመኛም እግዚአብሔርን እንዳይበድሉ በቅድስት ቤተክርስቲያን ቀኖና ይጠበቁ በሰማያት ላለችው ሀገር የዓይን ምሥክሮች እኛ ነንና።'),
  ('ca7cecf9-6c2a-589f-a3f4-245cf9c3a214', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 98, 98, 'ሰማያዊት አገር የተባለችውም ቅድስት ቤተክርስቲያን ናት ወደሷ ለሚገሰግሱ ሁሉ ወደእግዚአብሔር ትማፀንላቸዋለችና እነዚህ የኔ ልጆች ናቸው እነዚህ ልጆቼ መሐይምናን ጊዜ ሳይለዩ በየጊዜው ወደኔ ይገሰግሳሉና በማለትም ለጌታችን ኢየሱስ ክርስቶስ ታስረክባለችና።'),
  ('25eb215d-20c6-545a-a345-a5716235b5dc', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 99, 99, 'ጳጳስ ይሁን ቄስ ዲያቆን ይሁን ሕዝባዊ ጥዋትና ማታ በቤተክርስቲያን እየተገኘ ትምህርትን ማግኘት አለበት ከዚሁ ወደኋላ ካለ ግን ቅጣት ይፈፀምበት በሥጋደዌ ሳይያዝ መምጣት ከተወ ደግሞ ከቤተክርስቲያን ይወገዝ በቤተክርስቲያን ጥዋትና ማታ እየተገኘ ቃለእግዚአብሔርን መስማት ሲተው ጋኔን ያንቀዋል።'),
  ('5a38986d-612b-59d0-a2bf-5a775791f0e5', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 100, 100, 'በሥጋደዌ በመያዙ ምክንያት በእግዚአብሔር መማፀኑን ትቶ ወደሥራይ ሰዎች የአጋንንትን ኃይል ከሚተማመኑ ሰዎች እርዳታ ከጠየቀ ይወገዝ።'),
  ('f36685d7-bcd4-5b23-a520-e9106d6b34fe', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 101, 101, 'በእግዚአብሔር ተማፀነ ወደቅድስት ቤተክርስቲያንም ተጠጉ ከሷ አትራቁ እሷም ስለእናንተ ወደእግዚአብሔር ትለምናለች ወደቅድስት ቤተክርስቲያን የተጠጋ ሁሉ አያፍርም ወደሷ ቃለእግዙአብሔርን ለመስማት የሚገሰግሰውንም ሁሉ ደስታ ታቀዳጀዋለች እግዚአብሔር በሷ ላይ ነውና።'),
  ('25e4ce0c-d0ca-5059-a828-a50c1c74c61d', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 102, 102, 'ሌት ተቀን ኀዎትና ማታ ወደ እግዚአብሔር ለሚጮኽና ድሕነትህን እፈልጋለሁ አትተወኝ እያለ ለሚጸልይ ሁሉ ፀሉቱን ይቀበለዋል።'),
  ('099b9821-4371-5eee-a69a-12c69eb96a19', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 103, 103, 'የክርስቲያን ወገኖች የሆን ሁሉ ወደቅድስት ቤተክርስቲያን እንገሥግሥ እግዚአብሔር ምሕረቱን በሷ በኩል ይልክልናል። የሐጢአት ማስተሥርያ እሷ ናትና ጠላታችን ከሆነው ጋኔንንም እንድንድን እግዚአብሔር በቤተክርስቲያን አማካይነት ምሕረቱን ይልክልናል አጋንንት ግን ከቅድስት ቤተክርስቲያን መዓርጋችን ሊያወርዱን ይጥራሉ ጌታችን ደግሞ ከነሱ ይታደገናል።'),
  ('c96043d7-a8fb-5e4d-a3c0-4aa7ae243861', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 104, 104, 'በቀናች ሃይማኖት ፀንታችሁ ኑሩ። መልካም ሥራን መሥራትንም አታጓድሉ ይህም ሁልጊዜ ይሁን ከሞት 238 ወደሕይወት ትሻገሩ ዘንድ የተጻፈው ሁሉ እኛን ለማስተማር ለመምከርና ለመገሠፅ የተፃፈ ነው። ይህ ከሌለ ግን አጋንንት እያሳቱን ልንወድቅ እንችላለን የእግዚአብሔር ቃልም ይረሳናል።'),
  ('77b080d5-726f-5fc5-ae08-a89aa0e18b21', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 105, 105, 'እግዚአብሔር ትሕትናን። የዋህነትንና ባለእንጀራን መውደድ ለኛ አዟል ቀማኛነትንና አታላይነትን በጠቅላላ የአመዕ ሥራን ሁሉ ይጠላል በተጠቀሱት መጥፎ ሥራዎች ሕይወቱን የሚመራ ካለ ከቤተክርስቲያን ይሠደድ ይባረረም።'),
  ('480af0e5-202b-56ae-a50d-410880cd7140', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 106, 106, 'የእግዚአብሔርን ቃል ለነሱ መጥፎ ሥራ እንዲመቻቸው የሚናገሩት አሉ ቃሉንም ይንቁታል እንደፍላጎታቸውንም ይተረጉሙታል ለክፉ ተግባራቸው የተስማማ ለማስመሰልም ብዙ ይጥራሉ እግዚአብሔር ግን በፈቀደው ጊዜ ዋጋቸውን ይከፍላቸዋል እነዚህ ክፉዎች ሰዎች ብቻቸው አይጠፉም ብዙዎችን አሳስተውና አታልለው እንደነሱ ለማድረግ ይጥራሉ።'),
  ('a1b39a43-79fa-5e39-a7e7-2a44a5ebaf90', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 107, 107, 'መጥፎ ነገር ወደሰው ልቡና ከገባ ሰው ከመምህራነ ቤተክርስቲያን የተማረውን መልካም ትምህርት ያጠፋበታል ያስረሳዋልም ጥቂት ትእጉሥታር የማርን ጣዕም እንደሚያበላሽ ክፉ ነገርም ወደሰው ልቡና ከገባ ሃይማኖትን ያስጠፋል ስለዚህም አስቀድመን መጥፎ ነገር ሃይማኖትን ከሰው ልቡና ሊያጠፋ ይችላል ማለታችን ስለዚህ ነው።'),
  ('f67ef1d1-be6b-55ca-aea8-2ce5032de823', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 108, 108, 'ቅንዓትና ፍትወት የጠቢባንን ልቡና°°°ያሳብዳሉና የእግዚአብሔርን ቃል መዳፈርና ችላ ማለት ለነፍስ ጠቃሚነት 239 የለውም የእግዚአብሔርን ቃል መዳፈር ከመልካም መንገድ መንሸራተት ነውና ሙሴ ህዝቦቹን ከእግዚአብሔር መንገድ እንዳይወጡ ሲያስጠነቅቅ እሳትንና ውሃን አቅርቤላችሁ አለሁ እጃችሁን ወደመረጣችሁት ክተቱ አለ።'),
  ('3b6a1af5-44f0-593b-ae15-fc07617807d9', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 109, 109, 'እናንተ የማትፈፅሙትንና የማታደርጉትን ለሕዝብ አታስተምሩ ይህ ከሆነ እነሱ በጣታቸው ሊነኩት የማይፈልጉትን ባንገታችን ላይ የብረት ሰንሰለት ያስገቡብናል ይህን እኛ ልንሸከመው የማንችለው ነው እነሱ ሊሠሩት የማይችሉትን ሁሉ ያሸክሙናል እንዳይሉ።'),
  ('ae454f5c-3660-5d4f-ad65-b20496fac899', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 110, 110, 'እኛን ወደማናውቀው መንገድ ይወስዱናል እነሱ ግን እኛ በምናውቀው ሰፊው መንገድ ይጓዛሉ በእግዚአብሔር ያልተፈቀደውንም ይፈፅማሉ እንዳይሉን በጥንቃቄ እንጓዝ።'),
  ('dafb0858-8a2f-51e7-a264-f20aa2138a4f', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 111, 111, 'እኛ ግን መንገዳችንን እናስተካክል የአምላካችን እግዚአብሔር ወገኖች ለመሆን አንድንችል የእግዚአብሔር ቤተሰቦችም እንድንሆን ከሱ ፊት በደረስን ጊዜ ወገኖቼ ሸክም የከበዳችሁ እናንተ ወደኔ ኑ እኔም አሳርፋችሁ አለሁ። እንዲለን በቀላል ምክንያት ነፍሳችሁን አትጕዱ የዚህ ዓለም ኑሮ ኃላፊ ነውና።'),
  ('4df7cdac-3d05-5490-a41e-940c6c13f2af', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 112, 112, 'የእግዚአብሔር መንፈስ በናንተ ላይ ካለ ትክክለኛውን የሚያምረውንና የሚያስደስተውን መንገድ ታውቃላችሁ መንፈሰ እግዚአብሔር የተለየው ሰው ግን ሁሉን ይረሳል እናንተም እንዲሁ ልትሆኑ ትችላላችሁ የእግዚአብሔርንም ህግ እስከመርሳት ትደርሳለችሁ በዝንጉዎች መንገድ ያልሄደ ብጹዕ ነው ብሏል ዳዊት።'),
  ('4fdda08e-3d3e-5680-a426-040906defa93', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 113, 113, 'በሱ ላይ ያደረው መንፈስ ቅዱስ ይመራዋል ይረዳዋል አስተዋይነትንም ይሠጠዋል ይረዳዋልም እንደመልካም ምንጭዎ ይሆናል ከአፉም ምስጋና እግዚአብሔርን መማፀን ብቻ ይወጣል እግዚአብሔርም ይቅርታንና ምሕረትን ይሠጠዋል። በመንፈሰ እግዚአብሔር የሚመራ የተቀደሰ ሰው ነው እግዚአብሔርን 1 ማመስገንና ከፍ ከፍ ማድረግ ከአፉ አያቋርጥም።'),
  ('73b1b7be-0bfa-5d11-a4c8-d93bf0f8bc6e', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 114, 114, 'መንፈስቅዱስ ያደረበት ስመእግዚአብሔርን በጠራ ቁጥር ወድያው መልስ ያገኛል እኔ አለሁልህ የሚል ቃልንም በእግዚአብሔር ይሰማል በቅድስት ቤተክርስቲያን ሥርዓት የማይሄደውን አውግዛችሁ ከሷ አባረሩት።'),
  ('8a7196d6-f5bd-50c7-ad01-c98ead034407', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 115, 115, 'ቤተክርስቲያን በነቢያት በሐዋርያት በጻድቃንና በሰማዕት ቃል የተሸለመች ሙሽራ ናት ከሁሉ በበለጠ ግን ሐዋርያት ዓለምን ንቀውና የዚህ ዓለምንም ሀብት ትተው ከናትካባታቸው ተለይተው ኢየሱስክርስቶስን ተከተሉ እሱን ለማግኘት ነውና ዓላማቸው ከማንኛውም የዚህ ዓለም ኃብት ፍቅረእግዚአብሔር ይበልጣል።'),
  ('fcf3fd45-272f-597f-adaa-bf8b307042d4', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 116, 116, 'የእግዚአብሔርን ፍቅር የሚመስለው የለም ከወርቅና ከብር ክምችት እሱ ይበልጣል ከማርና ከስኳርም የበለጠ ጣፋጭነት አለው። ከወይን የበለጠ የልብ ደስታም ለሰው ይሠጣል ከብዙ ምርኮ ውጤትም እሱ ብልጫ አለው። ለዓይን አይታይም እንጂ አስደናቂ ነው።'),
  ('e50094dc-061c-5078-a552-500e50dd8f28', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 117, 117, 'የእግዚአብሔር ፍቅር በዓይነመንፈስ ይታያል በመንፈስ ጆሮም ይሰማል እግዚአብሔር ሁሉን የያዘ መሆኑንም ያውቃሉ አውቀውም እግዚአብሔርን ያመሰግኑታል የነሱን ማመስገን የሚያዩ የቤተክርስቲያን ልጆችም ዕጥፍ ድርብ ምስጋናን ያቀርባሉ።'),
  ('f3377c7a-9221-5832-ae82-cdb2780446cc', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 118, 118, 'ወደሰማይ ቢያንጋጥጡ ፀሐይን። ጨረቃንና ከዋክብትን እንዲሁም በነሱ የተመሠረተ የዘመናት አቈጣጠርን ይመለከታሉ ይህንንም የተመለከቱ ሁሉ እግዚአብሔርን ያመሰግኑታል።'),
  ('f575bcaa-0b41-5070-a5ee-8129df70dee8', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 'c23e93a9-544b-580d-aa18-f880a77c07f6', 119, 119, 'ሐጢአተኞችን አስተምራችሁ ወደንስሐ ወልሱ የሐጢአተኛን ንስሐ እግዚአብሔር ይቀበላልና። ጻድቃንን ደግሞ ወደኋላ ተመልሰው ሐጢአትን እንዳይሠሩና እስከእለተሞታቸው እንዲጠበቁ ምከሩዋቸው።'),
  ('2c2161eb-e4fe-5444-a5bb-62413eed8956', '69f47165-ee4e-57f0-a19c-b3f0d97605c7', 'fe781be7-7a55-562a-a8fd-9ec6bfefd777', 1, 1, 'በደብረ ዘይት ከጌታችን ኢየሱስ ክርስቶስ ለቅዱስ ጴጥሮስ የተነገረ የቤተክርስቲያን ሥርዓት ይህ ነው ጴጥሮስም ከጌታችን የተነገረውን ሥርዓት ለቀሌሚንጦስ ነግሮታል ጴጥሮስ በሙሴ ቀሌሚንጦስ በአሮን ይመሰላሉ።'),
  ('edd244d6-ade4-5c13-afb4-851692fc06d7', '69f47165-ee4e-57f0-a19c-b3f0d97605c7', 'fe781be7-7a55-562a-a8fd-9ec6bfefd777', 2, 2, 'የቅድስት ድንኳንን አመራር ጌታችን ለሙሴ በደብረሲና ነገረው ለጴጥሮስ ደግሞ የቅድስት ቤተክርስቲያንን ሥርዓት በደብረዘይት ነገረው።'),
  ('8b742ea6-2b53-56b3-a069-d48be81a3d77', '69f47165-ee4e-57f0-a19c-b3f0d97605c7', 'fe781be7-7a55-562a-a8fd-9ec6bfefd777', 3, 3, 'አንተ ካህን መብልን የምታበዛ አትሁን ጥንብ አንሳ አሞራዎች ለሆዳቸው ሲሉ በወጥመድ ይያዛሉ አንተም እንደነሱ በወጥመድ እንዳትያዝ ተጠንቀቅ ትሕትና ፍቅር የዋህነት ትዕግሥት።'),
  ('b7408185-68d2-565b-af9f-0976aed2f7e5', '69f47165-ee4e-57f0-a19c-b3f0d97605c7', 'fe781be7-7a55-562a-a8fd-9ec6bfefd777', 4, 4, 'ለድሓ መራራትና ምፅዋት መሥጠት ናቸው የመንግሥተ ሰማያት ቁልፎች በመባል የሚታወቁት።'),
  ('6a49ba4a-efa6-5618-a0d4-50056e45e3c6', '69f47165-ee4e-57f0-a19c-b3f0d97605c7', 'fe781be7-7a55-562a-a8fd-9ec6bfefd777', 5, 5, 'ካህን ሆይ አስቀድመህ ራስህን ንፁሕ አድርግ በወንጌል አስቀድመህ በራስህ ዓይን ያለውን ጉድፍ አውጣ የተባለውንም አትዘንጋ ይህንን ባታደርግ ግን ጌታ በግርማ መንግሥቱ መጥቶ ለሁሉ እንደየሥራው ሲከፍለው የገዛ ቃልህ የሚያጋልጥህ ትሆናለህ።'),
  ('48896132-b358-58c0-af16-65212c81ebb0', '69f47165-ee4e-57f0-a19c-b3f0d97605c7', 'fe781be7-7a55-562a-a8fd-9ec6bfefd777', 6, 6, 'በንሥሐ የሚመለሱትን ተቀበላቸው የዘለዓለማዊው ሕይወት ተስፋንም አብሥራቸው የእግዚአብሔርንም ትእዛዝ እንዲጠብቁ አደራ በላቸው ሌት ተቀንም ጐብኛቸው።'),
  ('0a54fd70-88f9-56a7-a393-4d7666236137', '69f47165-ee4e-57f0-a19c-b3f0d97605c7', 'fe781be7-7a55-562a-a8fd-9ec6bfefd777', 7, 7, 'ካህን ሆይ ከላይ ወደታች ራስህን አታውርድ ወደዓለምም ሐሳብህን ዝቅ አታድርግ ላይ የተባለችው ቅድስት ቤተክርስቲያን ናት ዓለም የተባለውም ሐጢአት የሠሩ ሰዎች የሚገቡበት ሲኦል ነው።'),
  ('2eba9c02-7063-5e6a-a176-4bb2c813694d', '69f47165-ee4e-57f0-a19c-b3f0d97605c7', 'fe781be7-7a55-562a-a8fd-9ec6bfefd777', 8, 8, 'ከእግዚአብሔር ፈቃድ ውጭ በራሳቸው ፈቃድ ለሚኖሩ ሰዎች ሠይጣን እያታለለ ገደል ይከታቸዋል እግዚአብሔር አክአብን በተጣላው ጊዜ ሠይጣን ነቢያትን የሐሰትን መንፈስ በአፋቸው እያናገርኩ አስታቸዋለሁ ብሎ ነበር።'),
  ('d2ff71ec-6bc3-5702-a72f-7d48501be76a', '69f47165-ee4e-57f0-a19c-b3f0d97605c7', 'fe781be7-7a55-562a-a8fd-9ec6bfefd777', 9, 9, 'እግዚአብሔር ከአዳም ልጆች ክህነትን ይፈቅዳል ክህነታቸውም እንደሱራፌልና እንደኪሩቤልም የካህናትን ምሥጋና ይቀበላል። ኪሩቤል ዘወትር እግዚአብሔርን ማመሥገን ብቻ ነው ። ሥራቸው።'),
  ('1c3ae3c1-1e1f-5119-a75d-2cb3fd8dce8a', '69f47165-ee4e-57f0-a19c-b3f0d97605c7', 'fe781be7-7a55-562a-a8fd-9ec6bfefd777', 10, 10, 'በዚህ ምድር ምዕመናንን እንዲመሩ ካህናት የሆኑ ሰዎች ። ብርንና ወርቅን መሸለም ወይም በነዚህ ማጌጥ የለባቸውም። ልጄ ቀሌሚንጦስ ሆይ ስማ ካህናት ተብለው የመምህራንን ምክር የማይቀበሉ ከሆነ በራሳቸውም ፈቃድ ከተመሩ ሠይጣን ያቸንፋቸዋል። በወርቅና በብር ማጌጥ ልምዳቸውን አድርገው ። ወደዘፈን ቦታ ከሄዱ ከሥልጣን ይወገዱ።'),
  ('6e0a5d64-73e7-5225-a9fb-5be59410411f', '69f47165-ee4e-57f0-a19c-b3f0d97605c7', 'fe781be7-7a55-562a-a8fd-9ec6bfefd777', 11, 11, 'የካህናት ሽልማት የመፃሕፍትን ቃላት ማጥናት። መፃሕፍትን መተርጐምና የሃይማኖትን ቃል መዝራት ነው።'),
  ('5fd5ced5-9873-593a-afc3-a4e7d907ea3a', '69f47165-ee4e-57f0-a19c-b3f0d97605c7', 'fe781be7-7a55-562a-a8fd-9ec6bfefd777', 12, 12, 'ካህን በዚህ መንገድ ብቻ መመራት አለበት የሐጢአተኛን ንሥሐ የማይቀባል ካህን ካህን አይደለም ጌታችን ከማርያም በለበሰው ሥጋ ወልድ የዓለምን ሐጢአት እንደተሸከመ አስቡ። ሐጢአተኞችንም እናንተ ሸክማችሁ የከበደ ወደኔ ኑ እኔም አሳርፋችሁ አልሁ አለ ዳግመኛም ሐጢአተኛን ከሐጢአቱ እስኪመለስ ድረስ እታገሰዋለሁ ብሏል።'),
  ('3e87fb94-64df-5f30-ac58-558cc1073192', '69f47165-ee4e-57f0-a19c-b3f0d97605c7', 'fe781be7-7a55-562a-a8fd-9ec6bfefd777', 13, 13, 'ሳያውቅ ሰውን የገደለ የሰባት ሱባዔ ቀኖና ይሠጠው አውቆ ሰውን ለገደለ ሰባ የንሥሐ ሱባዔ ይሠጠው ሰባውን ከደረቅ 244 244 እንጀራና ውሃ በቀር የጣመ በቅቤ የተጣፈጠ አይመገብም ሁልጊዜም እስከዘጠኝ ሰዓት ይፆማል።'),
  ('a46932c2-6436-561a-a9b9-769e1531e8b5', '69f47165-ee4e-57f0-a19c-b3f0d97605c7', 'fe781be7-7a55-562a-a8fd-9ec6bfefd777', 14, 14, 'ለጴጥሮስ ከእግዚአብሔር በተሠጠው ፀጋ መሠረት ራዕይ ተገለፀለት ጴጥሮስ ጌታ ከመወለዱ በፊት አርባ ዓመት ነራል ጌታችን ተወልዶ የሠላሳ ሦስት ዓመት ዕድሜ ሲኖረው ደግሞ ለጴጥሮስ ሰባሦስት ዓመት ሆነው።'),
  ('80289583-03d3-51b3-aa80-28f8cf3c6267', '69f47165-ee4e-57f0-a19c-b3f0d97605c7', 'fe781be7-7a55-562a-a8fd-9ec6bfefd777', 15, 15, 'ለቅዱስ ጴጥሮስ ራእይ እስከተገለፀለት ድረስ የእግዚአብሔር ሀብትና ራእይ ቀርቶ ነበር። ትንቢትና የእግዚአብሔር ፀጋም ከሰው ርቆ ነበር። ሰዎች ተንቀው ነበር። ደካማዎችና ሠነፎች ሆኑ ለዚህ ዓለም ጥበብ እግዚአብሔር አሳብዷታልና ብልሀተኞች ነን የሚሉም ሰነፎች ሆኑ።'),
  ('69d4b97e-c967-5c18-ab4e-fe531257bbf9', '69f47165-ee4e-57f0-a19c-b3f0d97605c7', 'fe781be7-7a55-562a-a8fd-9ec6bfefd777', 16, 16, 'በዚህ ዓለም ክቡራን ነን የሚሉ የተዋረዱ ናቸው (በእግዚአብሔር ዘንድ) ራሳቸውን በዚህ ዓለም የሚያፀድቁ ሐጢአተኞች (በእግዚአብሔር ዘንድ) ናቸው። ከዚህም የተነሳ ቅዱስ ጴጥሮስና ቅዱስ እንድርያስ ፃድቃን ሁነው ሳለ እስከ ጌታችን መድሐኒታችን ኢየሱስ ክርስቶስ መምጣት ድረስ ክቡራን አልተባሉም መምህራን ተብለውም አልተጠሩም ዓሣ አጥማጆች ተባሉ እንጂ።'),
  ('4ca073dc-71cb-524a-a562-0e8601e7361f', '69f47165-ee4e-57f0-a19c-b3f0d97605c7', 'fe781be7-7a55-562a-a8fd-9ec6bfefd777', 17, 17, 'አሣ አጥማጂዎች ድሆች ናቸው አዲስ መረብም አልነበራቸውም የነበራቸው መረብ አሮጌ ነው የተቀደደም ነው የእግዚአብሔር ፀጋ ይታይ ዘንድ ይህ ሆነ ።።'),
  ('7be75c77-c5f0-5555-a92a-5ca9bb532170', '69f47165-ee4e-57f0-a19c-b3f0d97605c7', 'fe781be7-7a55-562a-a8fd-9ec6bfefd777', 18, 18, 'ቀዳማዩ ህግ ለሙሴ ተሠጠ ሁለተኛውና እውነተኛው ህግ ደግሞ ለቅዱስ ጴጥሮስ ተሠጠ።'),
  ('a7ffe565-0d00-5702-a030-e0898b5291a4', '69f47165-ee4e-57f0-a19c-b3f0d97605c7', 'fe781be7-7a55-562a-a8fd-9ec6bfefd777', 19, 19, 'ይህ ቅዱስ ጴጥሮስ በዚሁም በቅድስት ቤተክርስቲያን ህግ ለሚመሩ ክርስቲያን መሐይምናን ሥርዓትን ሠራላቸው። ይህም ንሥሐ ለገቡ የተሠጠ ነው።'),
  ('c3c6a6bb-4bee-54d5-a9be-fb7a13054a0b', '69f47165-ee4e-57f0-a19c-b3f0d97605c7', 'fe781be7-7a55-562a-a8fd-9ec6bfefd777', 20, 20, 'ከልባቸው እያለቀሱ ወደእግዚአብሔር ሰዎች ከተመለሱ ሐጢአታቸው ይሠረያል በደላቸውም ይደመሰሳል። እግዚአብሔርን አስደስታለሁ ብሎ የብዙ መሲናዎችና ፍሪዳዎች ደም ከማፍሠሥና ከመሠዋት ከሕሊና በመነጨ የምትነጥበው የአንዲት ዕንባ ጠብታ ተበልጣለች።'),
  ('5bfeb2ea-345d-52a4-a73b-66ffb3a5d6c1', '69f47165-ee4e-57f0-a19c-b3f0d97605c7', 'fe781be7-7a55-562a-a8fd-9ec6bfefd777', 21, 21, 'ከንሥሐ ተመሥርቶ የሚፈሰው የሐጢአተኛ እንባ ሰማዕታት ለእግዚአብሔር ለመመሥከር ከሚያፈሱት ዕንባ ጋር መመት ይመሳሰላል።'),
  ('2313cc36-659f-5952-abca-d8907a61790f', '69f47165-ee4e-57f0-a19c-b3f0d97605c7', 'fe781be7-7a55-562a-a8fd-9ec6bfefd777', 22, 22, 'የንሥሐ ዋናው አርእስትና ጥቅሙ ተመልሶ ወደቀድሞው ሐጢአት አለመግባት ነው። ካህናትን በማቃለል መንፈስ ቅዱስን ከሰደበ ከበደሉም በፀፀት ከተመለሰ ዘጠኝ ሱባዔንና ሰባት ወሮችን የቀኖና ጊዜ ሥጡት ይህም ቀን መቶ ሥግደትን ሌሊት መቶ ሥግደትን እየሠገደ ከልብ በመነጨ ወደፈጣሪው ተመልሶ በልቅሶና በሰቆቃ ሊሆን ይገባል።'),
  ('90f3dfcf-341f-5b39-a17c-0f2aa8422c9b', '69f47165-ee4e-57f0-a19c-b3f0d97605c7', 'fe781be7-7a55-562a-a8fd-9ec6bfefd777', 23, 23, 'የዚህ ዓለም ንብረት ሐላፊ ነው በዚህ ዓለም የምናገኘው 246 ። ደስታም እጅግ ጥቂት ነው ጊዜውም እጅግ አጭር ነው። እየተዋቡ መታየት ይቀራል የተፈጥሮውበትም ይጠፋል የዘመድ አዝማድ የልጅ ፍቅር ጨርሶ ይረሳል ይጠፋል።'),
  ('44143660-3a6b-5b14-ad57-71d0c2035999', '69f47165-ee4e-57f0-a19c-b3f0d97605c7', 'fe781be7-7a55-562a-a8fd-9ec6bfefd777', 24, 24, 'የዚህን ዓለም ከንቱነት እስኪ ቆም ብላችሁ አስተውሉት። በመጠጥ ብዛትም ልባችሁ እንዳይደነድን ተጠበቁ ከዚሁም ደስታን አትጠብቁ ንሥሐ ሳትገቡ ጊዜያችሁ እንዳትደርስ ተጠንቀቁ አሁን አጥንተን ለመፈወስና ከሐጢአት በሽታችሁም ለማዳን የሚችል ንሥሐ አለላችሁ ከሁሉ በማብለጥ ከባለንጀራችሁ ጋር ያለችውን ፍቅር አጥብቃችሁ ያዟት። በዚህ እግዚአብሔር ይደሰታል። ንስሐችሁም ይቀበላል መላእክትም በናንተ ንሥሐ መግባት ይደሰታሉ።'),
  ('cf28b0aa-59f2-5854-a190-63ef4e198fa5', '69f47165-ee4e-57f0-a19c-b3f0d97605c7', 'fe781be7-7a55-562a-a8fd-9ec6bfefd777', 25, 25, 'ዘወትር በንፁሕ ሕሊና እየሆናችሁ ወደእግዚአብሔር ጸልዩ በዚሁም ከሠይጣን ጠብና ወጥመዱ ልትድኑ ትችላላችሁ ሠይጣን ወደእግዚአብሔር እንዳትመለሱና ንሥሐ እንዳትገቡ እናንተን በስንፍና ይይዛቹኋል።'),
  ('d9f537ba-ef98-5024-a405-195b57159107', '69f47165-ee4e-57f0-a19c-b3f0d97605c7', 'fe781be7-7a55-562a-a8fd-9ec6bfefd777', 26, 26, 'ነፍስ ከቅዱስ ቁርባን በቀር የሚጠቅመኝ የለም ከሥጋ ከተለየሁ ዕረፍት የለኝም ዕረፍት የማገኘው ቅዱስ ቁርባን በሚፈፀምበት ጊዜ ብቻ ነው ቅዱስ ቁርባን ሲፈፀምና መሥዋዕት ሲያርግ ከመላ ቤተሰቦቼ ጋር እደሰታለሁ ሙሽራ ተውቦና ተሸልሞ እንደሚደሰትም በሠርጉ ጊዜ ከመላ ቤተሰቡም ደስታውን እንደሚገልፅ እሆናለሁ ትላለች።'),
  ('0e19b4c3-626a-5923-ac46-734ed55abd31', '69f47165-ee4e-57f0-a19c-b3f0d97605c7', 'fe781be7-7a55-562a-a8fd-9ec6bfefd777', 27, 27, 'በገነት የፃድቃን ነፍሳት የሚመገቡዋቸው ዕፀዋት አሉ የያንዳንዱ ዛፍ ግንድ ሰላሳ አንድ ሥሮች አሉት ተመሳሳይ ቅርንጫፎችም አሉት በያንዳንዱ ቅርንጫፍም አንድ ሺ እልፍ ሐረጎች አሉ። በያንዳንዱ ሐረግ አሥር ሺ ፍሬዎች አሉ። በያንዳንዱ ፍሬ ደግሞ አሥራ ሁለት እልፍ ነፍሳት ይሰበሰባሉ።'),
  ('c07f9dec-3f42-51fa-ac95-c707bb1f5dfa', '69f47165-ee4e-57f0-a19c-b3f0d97605c7', 'fe781be7-7a55-562a-a8fd-9ec6bfefd777', 28, 28, 'በፀሎት የሙትን ነፍስ ስታስታውስ በገነት ያለችው የሙት ነፍስ ካለችበት የገነት ዕፅ ሁና እየፀለየች በዚህ ዓለም ያለውን ሰው መንፈሳዊ ደስታ ታጐናፅፈዋለች እሷም ካለችበት ሁና ስለሱ ትፀልያለችና።'),
  ('1c3948db-f694-59cd-a370-c6cc926c851f', '69f47165-ee4e-57f0-a19c-b3f0d97605c7', 'fe781be7-7a55-562a-a8fd-9ec6bfefd777', 29, 29, 'የንሥሐ ዋናው ትርጉም ያለፈውን ሐጢአት በመቲረፈቃድ መተው ነው በደልን ፈፅሞ ቈይቶ የሠራውን ሐጢአት በወታሉ ምንም ሳይደብቅ ከተናገረ በጥብአትም ከተመለሰ ምንም ሐጢአት የለውም።'),
  ('951c4c02-c32a-5b94-afb9-16b166dc8ad0', '69f47165-ee4e-57f0-a19c-b3f0d97605c7', 'fe781be7-7a55-562a-a8fd-9ec6bfefd777', 30, 30, 'ሰማያዊው ደስታ ኃብትን በማግኘት በዚህ ዓለም እንደሚያደርገው ደስታ አይደለም ፍፁም በሆነ ደስታ ዘወትር እግዚአብሔርን ማመስገን ነው።'),
  ('ca2a2718-b55b-589c-acfa-c5240b4f92e3', '69f47165-ee4e-57f0-a19c-b3f0d97605c7', 'fe781be7-7a55-562a-a8fd-9ec6bfefd777', 31, 31, 'በግልፅ ልንገራችሁ ወንድሞቼ ሆይ ምንም ማድረግ የማንችልበት ሰዓትና ጊዜ ይመጣል መናገር የማይቻልበትና ጉረሮ የሚዘጋበት ዕለት ይመጣል ማየት የማይቻልበት ዕለት ይመጣል መስማት የማይቻልበት ዕለትም ይመጣል ቤተሰብ በልቅሶ ሲፋጅ መስማት የማይቻልበት ጊዜ ይመጣል።'),
  ('d2c68915-e878-566e-a599-15cfb520e1db', '69f47165-ee4e-57f0-a19c-b3f0d97605c7', 'fe781be7-7a55-562a-a8fd-9ec6bfefd777', 32, 32, 'ወንድሞችና እህቶች ሆይ ልቡናችሁን ወደእግዚአብሔር መልሱ ስለ ኋለኛው ሕይወታችሁም አስቡ። ስለነፍሳችሁ እወቁበት። የመጨረሻዋ ሰዓት መቼ እንደሆነች አታውቁምና ተዘጋጅታችሁ ነሩ የማይጠቅመውን ልቅሶ በኋላ ከማልቀስ አሁኑኑ ስለሐጢአታችሁ አልቅሱ።'),
  ('512fec9b-640d-5777-affb-3cdb1837fe4f', '69f47165-ee4e-57f0-a19c-b3f0d97605c7', 'fe781be7-7a55-562a-a8fd-9ec6bfefd777', 33, 33, 'በኩነኔ ያለችው ነፍስ ከጭንቀትና መከራ ብዛት የተነሳ ለማረፍ ትፈልጋለች ነገር ግን ለሰኮንድ ጊዜ እንኳ ዕረፍት ልታገኝ አትችልም ይህንን በዚህ ዓለም እያለች አላስታወሰችውምና ሟች መሆንዋን ከመዘንጋት የተነሳም በሕይወት እያለች ንስሐ አልገባችምና በፍርሐትና በመጨነቅም ፍርዷን ከእግዚአብሔር ትቀበላለች።'),
  ('bcdc52f0-c65f-57e8-a8d1-bd3fe649c94e', '69f47165-ee4e-57f0-a19c-b3f0d97605c7', 'fe781be7-7a55-562a-a8fd-9ec6bfefd777', 34, 34, 'ይህንን ሁሉ ሰምታችሁ ልቡናችሁን ወደኔ መልሱ ይላል እግዚአብሔር በኋላ የሚመጣባችሁን አትዘንጉ የመሞቻችሁ ሰዓት ሳትደርስ ይህን ከንቱ ዓለም ተበለጡ እወቁበትም ንሥሐችሁና ፀፀታችሁ ከሞት በኋላ እንዳይሆን ተጠንቀቁ ከሞት በኋላ ንሥሐ ዋጋን አያሠጥም ከንቱ ነው መልካም ሥራን ለመሥራት ተሽቀዳደሙ በሕይወት እያላችሁ ሳይመሽ ተዘጋጁ ፍሬ ሳይኖራት በከንቱ እንደደረቀች ዛፍ ተቈርጣችሁ ወደእሳት እንዳትጣሉ አሁኑኑ እወቁበት።'),
  ('2bee3158-ba9f-53c5-ad44-77f0a2c73ecb', '69f47165-ee4e-57f0-a19c-b3f0d97605c7', 'fe781be7-7a55-562a-a8fd-9ec6bfefd777', 35, 35, 'ለንሥሐ ጊዜ አትሥጡ ተሉ ንሥሐ ግቡ የሃይማኖት ትምህርት ስትሰሙ የድካም ፍሬ መሆኑን አትርሱ ከእንጠ ጋር ተመገቡት እንጂ ከመዓዛው ጣዕም ትጠግባላችሁ ይህን ቃል ደግሜ እነግራችሁ አለሁ ሁላችሁ ምክሬን በመስማት ንሥሐ ትገቡ ዘንድ ከመጥፎ ባህላችሁም እንድትመለሱ የሰው ልጅ ትልቁ ውድቀቱ ንሥሐ ሳይገባ መሞቱ ነው።'),
  ('6a99f772-364f-5e92-a2d7-c04aca9645df', '69f47165-ee4e-57f0-a19c-b3f0d97605c7', 'fe781be7-7a55-562a-a8fd-9ec6bfefd777', 36, 36, 'ጠላት በዚህ ዓለም ወደእግዚአብሔር እንዳይመለሱ የብዙዎችን ልብ አሳውራል። እግዚአብሔር ንፁሕን ነገር ፈጠረ ዲያብሎስ ደግሞ ርኩስ ነገርን ፈጠረ። የሚሉ አሉ ይህ ታላቅ ስሕተት ነው ካንዱ እግዚአብሔር በቀር ሌላ ፈጣሪ የለም ሁሉን እግዚአብሔር ሲፈጥር ንፁሕ እንዲሆን በመፍቀድ ነው ግን ራሱ ሰው ሊረክስ ይችላል።'),
  ('b6c64adb-0af2-52d1-a8b6-a5700110fc55', '69f47165-ee4e-57f0-a19c-b3f0d97605c7', 'fe781be7-7a55-562a-a8fd-9ec6bfefd777', 37, 37, 'መንፈስ ቅዱስ በመንፈስ ርኩስ ሊረክስ ይችላል የሚል ካለ የተወገዘ ይሁን መንፈስ ቅዱስ የረከሰውን ይቀድሳልና ሁሉንም ያነፃል የሰው ልጆች ነፍስ የእግዚአብሔር ቤተመቅደስ ናት አንተ ሰነፍ ሐጢአትህን ሁሉ ለካህን መናገርን አትፈር አንተ በንሥሐ ዘርዝረህ ሐጢአታቸውን የምትነግራቸው ካህናት እንዳንተ ሟቾች ናቸው።'),
  ('289db4bd-405c-5bf8-a6d2-8abc7e9559e4', '69f47165-ee4e-57f0-a19c-b3f0d97605c7', 'fe781be7-7a55-562a-a8fd-9ec6bfefd777', 38, 38, 'ለማያምኑብኝ ሁሉ ያላሰማሁት ቃሌ የለም ቃሌን ሰምተው ንሥሐ የገቡ ሁሉ ከኔ ጋር መንግሥቴን ይወርሳሉ በምድር ሳሉ ንሥሐ ገብተዋልና በዚች ምድር እያላችሁ ንስሐ ለመግባት ተሽቀዳደሙ በዚሁ ከሞት ወደ ሕይወት ትሽጋገራላችሁ።'),
  ('d703dca6-e010-5615-a3ba-af2777f04139', '69f47165-ee4e-57f0-a19c-b3f0d97605c7', 'fe781be7-7a55-562a-a8fd-9ec6bfefd777', 39, 39, 'በዚህ ዓለም እያለህ የሠራኸውን ሐጢአት በንሥሐ ምንም ሳታስቀር ከነገርክ ምንም አሳፋሪ ነገር አይገጥምህም በትንሣኤ ጊዜ ትደሰታለህ እንጂ። በዚህ ዓለም እያሉ ሐጢአታቸውን በንሥሓ ያልጨረሱ የሚረሳ አይምሰላቸው ሐዘንና መከራ ብቻ ይጠብቃቸዋል ወንድሜሆይ ዕለተሞትህን አስብ የእግዚአብሔር ትእዛዛትንም ጠብቅ በእግዚአብሔር ዘንድ ፊት መመለስና አድልዎ የለም።'),
  ('18bbaca8-0d10-5443-a134-bea70fcc5121', '69f47165-ee4e-57f0-a19c-b3f0d97605c7', 'fe781be7-7a55-562a-a8fd-9ec6bfefd777', 40, 40, 'በዚህ ዓለም ብዙ ንብረትን አከማችታችሁ ብትሞቱ የሚሠጣችሁ ጥቅም የለም ዘመዶቻችሁ ከሚቀራቀመቱት በቀር ስለዚህ ስንቅ ሁኖ በወድያኛው ዓለም እንዲጠብቃችሁ ምፅዋትን አስቀድሙ የሥጋውን ፈቃድ የሚከተል ፍሬው መጥፎ ይሆናል የነፍሱን ፈቃድ የሚከተል ፍሬው መልካም ይሆናል።'),
  ('a9a440d6-230f-570f-a78a-e12b0a277af9', '69f47165-ee4e-57f0-a19c-b3f0d97605c7', 'fe781be7-7a55-562a-a8fd-9ec6bfefd777', 41, 41, 'ሥጋ በዚሁ ምድር ደስታንና ዕረፍትን ትወዳለች። ነፍስ ግን ድካምንና ጸሎትን ትወዳለች ሥጋ መጠጥንና እንቅልፍን ትወዳለች ነፍስ ግን ትጋትንና ንሥሐን ትወዳለች ሥጋ ትዕቢትንና በዚች ምድር የሚመነጨውን የልብ ትዝሕርት ትወዳለች ነፍስ ግን ትሕትናን። የዋህነትንና እርስ በርስ መፈቀርን ከፀጋ ጋር ትወዳለች።'),
  ('357f97be-b360-5e78-ac1e-2fe5f3eb7cb3', '69f47165-ee4e-57f0-a19c-b3f0d97605c7', 'fe781be7-7a55-562a-a8fd-9ec6bfefd777', 42, 42, 'በደብር ቅዱስ ስለነበሩና በበዓተ መዛግብት ስለተቀበሩ አበው ያስታወስንበትን መጽሐፍ ጻፍን አባታችን አዳም ሚያዝያ ሰባት ቀን በዕለተ ዓርብ በሦስት ሰዓት ዓረፈ የአዳም ልጅ ሴት ታሕሣሥ አሥር ቀን በዕለተ ሰሉስ ዓረፈ ኄኖስ ወልደሴት በዕለተ ቀዳሚት ጥቅምት ሰባት ቀን ዐረፈ።'),
  ('893bab78-5b10-5220-afd7-15bb575edaa9', '69f47165-ee4e-57f0-a19c-b3f0d97605c7', 'fe781be7-7a55-562a-a8fd-9ec6bfefd777', 43, 43, 'ቃይናን የኄኖስ ልጅ በዕለተረቡዕ ሰኔ አሥራ ሦስት ቀን ዓረፈ የቃይናን ልጅ መላልኤል በእለተ እሁድ ሚያዝያ ሁለት ቀን ሞተ የመላልኤል ልጅ ያሬድ ግንቦት አሥራ ሁለት ቀን በዕለተ ዓርብ ሞተ የሞተውም በሶስት ሰዓት ነው የሄኖክ ልጅ ማቱሳላ መጋቢት አንድ ቀን ከእለተ እሁድ ሞተ።'),
  ('75e7eb33-b7d5-5c83-af81-9294f075174f', '69f47165-ee4e-57f0-a19c-b3f0d97605c7', 'fe781be7-7a55-562a-a8fd-9ec6bfefd777', 44, 44, 'የማቱሳላ ልጅ ላሜህ መሥከረም ሃያ አንድ ቀን ሞተ የላሜኀ ልጅ ኄኖኅ በዕለተ ረቡዕ ጥር ስድስት ቀን ሞተ።'),
  ('5972eb2a-7e4e-5f79-a88b-2a3e044d6994', '69f47165-ee4e-57f0-a19c-b3f0d97605c7', 'fe781be7-7a55-562a-a8fd-9ec6bfefd777', 45, 45, 'እነዚህ ቅዱሳን በደብር ቅዱስ የነበሩ ናቸው:: የተቀበሩትም በበዓተ መዛግብት ነው ኖኅ ግን በበዓተ መዛብት አልተቀበረም ታቦትን ይሠራ ዘንድ ወዳዘዘው ወደምድር ወረደ እንጂ በነዚህ አባቶች ጸሎት በሁላችን ላይ ትደር አሜን።'),
