  ('81f05587-251b-5e3f-a6fc-db7c697cde20', '8377ae17-37d8-5410-a023-b06e4cea890e', '8f64219b-8140-517c-a1d3-77a25c8de42b', 2, 2, 'የቤተ ፡ ክርስቲያንን ፡ የሹመቶች ፡ መዓርግ ፡ በሰማያት ፡ ባለው ፡ አምሳል ፡ እንደዚህ ፡ አዘዝን ።'),
