  ('21e79cd0-5257-5414-a33e-b821ba7f1739', '55adff54-76f0-5571-ab4f-23871210bb68', '79b16f8e-9c75-5f79-a161-416b208b607d', 22, 22, 'እርሱ ፡ ማንንም ፡ ቸል ፡ አይበል ። ከታላላቆች ፡ ጋርም ፡ አይወዳጅ ። ሁለት ፡ ልብና ፡ ሁለት ፡ አንደበት ፡ ያለው ፡ አይሁን ። መኳንንቱንም ፡ አይከተል ። እግዚአብሐርን ፡ ይፍራ ። በሌላውም ፡ ላይ ፡ በሐሰት ፡ ነገር ፡ ሥራን ፡ አይስማ ። ጾምንም ፡ ቸል ፡ አይበል ። ለመብላትም ፡ ምክንያት ፡ አያድርግ ። አሕዛብ ፡ ለመብላት ፡ ለመጠጣት ፡ ተድላ ፡ ደስታ ፡ ለማድረግ ፡ በዓልን ፡ ምክንያት ፡ እንዲያደርጉ ፡ «ዛሬ ፡ በዓል ፡ ነው ፡ እንብላ» ፡ አይበል ።'),
  ('8d1767b8-11a4-50fc-abf7-21cd27dac69e', '55adff54-76f0-5571-ab4f-23871210bb68', '79b16f8e-9c75-5f79-a161-416b208b607d', 23, 23, 'ነገር ፡ ግን ፡ ጥቅም ፡ የሌለው ፡ የስንፍና ፡ ምኞትን ፡ ከእርሱ ፡ ያርቅ ። ይህ ፡ ሁሉ ፡ በእግዚአብሔር ፡ ዘንድ ፡ የተጠላ ፡ በአጋንንት ፡ ዘንድ ፡ የተወደደ ፡ ነውና ።'),
  ('2bc60a31-4af8-5f87-ae75-bdee46a4000a', '55adff54-76f0-5571-ab4f-23871210bb68', '79b16f8e-9c75-5f79-a161-416b208b607d', 24, 24, 'ለኤጲስ ፡ ቆጶስ ፡ ይህንን ፡ ሁሉ ፡ ሥራ ፡ ከእነርሱ ፡ ያርቅ ፡ ዘንድ ፡ ሊያዝዛቸውና ፡ ሊመክራቸው ፡ ይገበዋል ። ነገር ፡ ግን ፡ እሱን ፡ ይመስሉ ፡ ዘንድ ፣ ፡ እካሄዱንም ፡ በቅንነት ፡ ይከተሉ ፡ ዘንድ ፡ ይገስጻቸውና ፡ ያስተምራቸው ፡ እንጂ ። እግዚአብሔር ፡ የእስራኤልን ፡ ልጆች ፡ ሕጌን ፡ ሥርዓቴንና ፡ ትእዛዜን ፡ ጠብቁ ፡ ብሎአቸዋልና ። እርሱ ፡ ጌታችን ፡ አምላካችን ፡ ኢየሱስ ፡ ክርስቶስም ፡ በጎ ፡ ሥራን ፡ ሁሉ ፡ አስቀደመ ። እርሱንም ፡ እንመስል ፡ ዘንድ ፡ አስማረን ።'),
  ('a293ef4b-e126-5058-ad46-a511eeb533b8', '55adff54-76f0-5571-ab4f-23871210bb68', '79b16f8e-9c75-5f79-a161-416b208b607d', 25, 25, 'ስለዚህም ፡ የሚያስተምረውን ፡ የሚሠራ ፡ ሰው ፡ በመንግሥተ ፡ ሰማያት ፡ ታላቅ ፡ ይሆናልና ፡ ይላል ።'),
  ('01907126-81c5-5ec3-aac4-064607acd9f1', '55adff54-76f0-5571-ab4f-23871210bb68', '79b16f8e-9c75-5f79-a161-416b208b607d', 26, 26, 'ኤጲስ ፡ ቆጶሳት ፡ ሕዝቡን ፡ አስተምራችሁ ፡ ከስሕተት ፡ ታድኖአቸው ፡ ዘንድ ፡ ለእናንተ ፡ ይገባል ። ክርስቶስ ፡ ለእናንተ ፡ እንደሰጣችሁ ፡ መጠን ።'),
  ('aae252f7-6384-586a-ab72-29848d36d3dc', '55adff54-76f0-5571-ab4f-23871210bb68', '79b16f8e-9c75-5f79-a161-416b208b607d', 27, 27, 'እግዚአብሔር ፡ በነቢዩ ፡ በሕዝቅኤል ፡ ቃል ፡ «የሰው ፡ ልጅ ፡ ሆይ ፡ ቃሌን ፡ ከእኔ ፡ አፍ ፡ ሰምተህ ፡ በቃሌ ፡ ትገሥጻቸውና ፡ ትመክራቸው ፡ ዘንድ ፡ ለእስራኤል ፡ ወገኖች ፡ ጉበኛ ፡ አደረግሁህ ፡ » ፡ ብሎ ፡ ተናግሮአልና ።'),
  ('ebbca3b4-96d4-580c-a335-dcd2b152ec78', '55adff54-76f0-5571-ab4f-23871210bb68', '79b16f8e-9c75-5f79-a161-416b208b607d', 28, 28, 'እግዚአብሔርም ፡ አለ ፣ ፡ ኃጥኡን ፡ ሞትን ፡ ትሞታለህ ፡ ባልሁት ፡ ጊዜ ፣ ፡ ንስሐ ፡ እንዲገባና ፡ ከክፉ ፡ መንገዱ ፡ እንዲመለስ ፡ ባትነግረውና ፡ ባትገሥጸውም ፡ ያም ፡ ኃጥእ ፡ በኃጢአቱ ፡ ሳለ ፡ ቢሞት ፡ ደሙን ፡ ከአንተ ፡ እፈልጋለሁ ፡ ይላል ፡ እግዚአብሔር ።'),
  ('dd32ac2c-8a78-5648-ab2f-aa48a67ef7ef', '55adff54-76f0-5571-ab4f-23871210bb68', '79b16f8e-9c75-5f79-a161-416b208b607d', 29, 29, 'ኃጥኡን ፡ ግን ፡ መክረኸውና ፡ ገሥፅኸው ፡ ሳይመለስ ፡ በበደሉ ፡ እንዳለ ፡ ቢሞት ፡ አንተ ፡ ነፍስህን ፡ አድን ።'),
  ('73fdcf77-0b25-55f8-a792-81a13709b697', '55adff54-76f0-5571-ab4f-23871210bb68', '79b16f8e-9c75-5f79-a161-416b208b607d', 30, 30, 'ጻድቁም ፡ ከጻድቅነቱ ፡ ወጥቶ ፡ ኀጢአትን ፡ ቢሠራ ፡ በፊቱ ፡ መቅሰፍቴን ፡ እያሳየሁት ፡ በበደሉ ፡ እንዳለ ፡ ይሞት ፡ ዘንድ ፡ ባትመክረው ፣ ባትገሥፀወም ፡ እርሱም ፡ ያደረገውን ፡ ጽድቁን ፡ አላስብለትም ፡ ደሙን ፡ ከአንተ ፡ እጅ ፡ እፈልጋለሁ ።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('0b94eb2f-37e3-53ee-a12a-fdf84d70e0c5', '55adff54-76f0-5571-ab4f-23871210bb68', '79b16f8e-9c75-5f79-a161-416b208b607d', 31, 31, 'ጸድቁን ፡ ግን ፡ እንዳይበድል ፡ ብትገሥጸው ፡ ብትመክረው ፡ እርሱ ፡ ከሞት ፡ ይድናል ። አንተም ፡ ነፍስህን ፡ አዳንህ ።'),
  ('4b1471dd-ebdb-5880-ab64-f10f8974bde4', '55adff54-76f0-5571-ab4f-23871210bb68', '79b16f8e-9c75-5f79-a161-416b208b607d', 32, 32, 'እንደዚሁም ፡ በሕዝቡ ፡ መካከል ፡ ጦርነትና ፡ ውጊያ ፡ በተደረገ ፡ ጊዜ ፡ እነርሱ ፡ ይጠበቁ ፡ ዘንድ ፡ የሚነግራቸው ፡ ጉበኛን ፡ ይፈልጋሉ ፣ ፡ ከሞት ፡ ይድኑ ፡ ዘንድ ፣ ፡ ባይነግራቸው ፡ ግን ፡ ደሙ ፡ በራሱ ፡ ላይ ፡ ነው ፡ የመለከት ፡ ድምጽን ፡ አልሰሙምና ።'),
  ('ea553b69-15b7-5a21-a868-71d2ac36a7e8', '55adff54-76f0-5571-ab4f-23871210bb68', '79b16f8e-9c75-5f79-a161-416b208b607d', 33, 33, 'ነገር ፡ ግን ፡ በሀገር ፡ ላይ ፡ የምትመጣ ፡ ጦርን ፡ ያየ ፡ ለሠራዊቱ ፡ ምልክት ፡ መለከትን ፡ ቢነፋ ፣ ፡ የመለከቱን ፡ ድምፅ ፡ ሰምቶ ፡ ገለል ፡ ባይል ፣ ፡ ጦርም ፡ መጥታ ፡ ብታገኘው ፣ ፡ ደሙ ፡ በራሱ ፡ ላይ ፡ ነው ። የመለከቱን ፡ ድምፅ ፡ ሰምቶ ፡ ገለል ፡ አላለምና ፡ ደሙ ፡ በላዩ ፡ ላይ ፡ ይመለሳል ። እርሱ ፡ ግን ፡ ገለል ፡ ብሏልና ፡ ነፍሱን ፡ አዳነ ።'),
  ('ab169c52-23b8-5228-af11-6b178f5d5eca', '55adff54-76f0-5571-ab4f-23871210bb68', '79b16f8e-9c75-5f79-a161-416b208b607d', 34, 34, 'እንደዚሁም ፡ ኤጲስ ፡ ቆጶሱ ፡ የሕይወትን ፡ ቃል ፡ ወንጌልን ፡ ቢያስተምር ፡ የዘለዓለም ፡ ሕይወትን ፡ ያገኛል ። ጦሩም ፡ የዘለዓለም ፡ ፍዳ ፡ ነው ። የመለከቱም ፡ ድምፅ ፡ ቅዱስ ፡ ወንጌል ፡ ነው ። ጉበኛ ፡ ሰላዩም ፡ የቅድስት ፡ ቤተ ፡ ክርስቲያን ፡ ኤጲስ ፡ ቆጶስ ፡ ነው ፣ ፡ ኤጲስ ፡ ቆጶሱ ፡ ስለ ፡ ፍርድም ፡ እያስፈራ ፡ ቃሉንም ፡ እያጠና ፡ ያስተምርና ፡ ይጠብቅ ፡ ዘንድ ፡ ይባል ። ስለዚህም ፡ ነገር ፡ ባለማወቅ ፡ የሚኖሩትን ፡ ሰዎች ፡ ይምከራቸው ። ገልጾም ፡ ያስረዳቸው ። የማያውቁትን ፡ ያስተምራቸው ። የሚያውቁትንም ፡ ያጽናቸው ። የተበተኑትንም ፡ ይሰብስባቸው ። ሁልጊዜም ፡ ስለድኅነታቸው ፡ ይንገራቸው ። ይህን ፡ ተግሣጽ ፡ በሰሙ ፡ ጊዜ ፡ በጎ ፡ ሥራን ፡ ይሠሩ ፡ ዘንድ ።'),
  ('f1a8f6d2-1c45-5272-a219-1d00fb012c65', '55adff54-76f0-5571-ab4f-23871210bb68', '79b16f8e-9c75-5f79-a161-416b208b607d', 35, 35, 'እግዚአብሔር ፡ በነቢዩ ፡ አድሮ ፡ «ከዚህ ፡ ሕዝብ ፡ ላይ ፡ አዳኝበታለሁ ። ምን ፡ አልባት ፡ ከኀጢአታቸው ፡ ቢመለሱ ፡ ንስሐ ፡ ገብተውም ፡ ቢድኑ ፡ ኃጢአታቸውን ፡ ንገራቸው» ፡ ብሏልና ።'),
