  ('6f34956d-4815-5209-a237-d5e4b4adf5dd', 'e86bb63d-0a27-5c02-a6f1-cad3d11dbb4f', 'a10eb387-1ecd-535b-aa58-ed7ca82b5afa', 12, 12, 'ቀድሞ ፡ ነገሥታቱ ፡ የሰውን ፡ ሥጋ ፡ ይጠብቁና ፡ ያድኑ ፡ ዘንድ ፡ ሠራዊታችውን ፡ አስነሥተውና ፡ ገብተው ፡ የሚዋጉ ፡ ከሆነ ፣ ፡ በእግዚአብሔር ፡ ዘንድ ፡ የክህነት ፡ ሹመትን ፡ የተቀበሉና ፡ ነፍስና ፡ ሥጋን ፡ ከቅጣት ፡ የሚያድኑማ ፡ ይልቁን ፡ እንዴት ፡ አይጠብቁ? ፡ ነፍስ ፡ ከሥጋ ፡ ትበልጣለችና ፡ ክህነትም ፡ ከመንግሥት ፡ ትበልጣለችና ፡ ይህችም ፡ ሹመት ፡ ቅጣት ፡ የሚገባቸውን ፡ የምታስር ፣ ፡ ሥርየት ፡ የሚፈልጉትንም ፡ የምትፈታ ፡ ናት ።'),
  ('9ca950a5-fbe6-58eb-a501-5e2ed0ca9421', 'e86bb63d-0a27-5c02-a6f1-cad3d11dbb4f', 'a10eb387-1ecd-535b-aa58-ed7ca82b5afa', 13, 13, 'ስለዚህም ፡ ኤጲስ ፡ ቆጶሱን ፡ እንደ ፡ አባት ፡ ታከብሩትና ፡ ትወዱት ፡ ዘንድ ፡ እንደ ፡ ንጉሥም ፡ ትፈሩትና ፡ እንደ ፡ እግዚአብሔር ፡ ታምኑት ፡ ዘንድ ፡ ይገባል ፣ ፡ ለእርሱ ፡ እጅ ፡ መንሻችሁን ፡ የእጃችሁም ፡ ሥራ ፡ ግብራችሁን ፣ ፡ ስዕለታችሁን ። የስንዴውንና ፡ የወይኑን ፣ ፡ የዘይቱን ፣ ፡ የባዘቶውንም ፡ መጀመሪያ ፡ አቅርቡለት ።'),
  ('1ee498aa-e62c-5392-a771-60fc6f19f113', 'e86bb63d-0a27-5c02-a6f1-cad3d11dbb4f', 'a10eb387-1ecd-535b-aa58-ed7ca82b5afa', 14, 14, 'ስለዚህ ፡ ቍርባናችሁ ፡ በፈጣሪያችሁ ፡ በእግዚአብሔር ፡ ፊት ፡ እንደ ፡ በጎ ፡ የዕጣን ፡ መዐዛ ፡ የተመረጠና ፡ የተወደደ ፡ ይሆን ፡ ዘንድ ፡ በእናንተ ፡ ላይ ፡ ይባርካሉ ። እግዚአብሔርም ፡ የእጃችሁን ፡ ሥራ ፡ ይባርካል ፣ ፡ ያማሩ ፡ የምድራችሁ ፡ ፍሬዎችንም ፡ ያዛል ። የእግዚአብሔር ፡ በረከት ፡ ምሕረትን ፡ በሚያደርጉ ፡ በጻድቃን ፡ እራሶች ፡ ላይ ፡ ነውና ።'),
  ('1768c0b4-f661-5fbd-acd3-b9a96c5f71e8', 'e86bb63d-0a27-5c02-a6f1-cad3d11dbb4f', 'a10eb387-1ecd-535b-aa58-ed7ca82b5afa', 15, 15, 'እነሆ ፡ እግዚአብሔር ፡ ከኦሪት ፡ መርገም ፡ አውጥቶ ፡ እረኛ ፡ እንደሌላቸው ፡ በጎችና ፡ መናገር ፡ እንደማይችል ፡ እንስሳ ፡ እኛ ፡ የተበተን ፡ የወደቅን ፡ ስንሆን ፡ ወደ ፡ ሕይወት ፡ እንደ ፡ መለሰን ፡ ዕወቁ ።'),
  ('15944ab2-f21b-5a5e-a1b1-469b5ee860d8', 'e86bb63d-0a27-5c02-a6f1-cad3d11dbb4f', 'a10eb387-1ecd-535b-aa58-ed7ca82b5afa', 16, 16, 'ከኀጢአታችን ፡ ከበደላችን ፡ ምን ፡ ያህል ፡ አዳነን? ፡ መሥዋዕትንም ፡ ለካህናት ፡ እናቀርብ ፡ ዘንድ ፡ ምንም ፡ ለሌላቸው ፡ ድሆች ፡ እንመጸውት ፡ ዘንድ ፡ አዘዘን ፣ ፡ ጌታችን ፡ በወንጌል ፡ ከፈሪሳውያንና ፡ ከጸሐፍት ፡ አብልጣችሁ ፡ ጽድቅን ፡ ካልሠራችሁ ፡ ወደ ፡ መንግሥተ ፡ ሰማያት ፡ መግባት ፡ አትችሉም ፡ ብሏልና ።'),
  ('2e6e059d-3b79-59c0-ade2-654c994e7b18', 'e86bb63d-0a27-5c02-a6f1-cad3d11dbb4f', 'a10eb387-1ecd-535b-aa58-ed7ca82b5afa', 17, 17, 'ላካህናት ፣ ፡ ለባልቴቶች ፣ ፡ እናትና ፡ አባት ፡ ለሞቱባቸው ፡ ልጆችም ፡ መስጠትን ፡ ብታስቡ ፡ እነሆ ፡ ገንዘቡን ፡ ለድኃ ፡ በተነ ፣ ፡ ሰጠውም ፣ ፡ ጽድቁም ፡ ለዘለዓለም ፡ ይኖራል ፡ ተብሎ ፡ እንደ ፡ ተጻፈ ፣ ፡ ግዳጃችሁን ፡ ፈጸማችሁ ፡ በእውነትና ፡ በቸርነት ፡ ኀጢአት ፡ ይሰረያልና ፡ ንጽሕት ፡ ቡርክት ፡ ሰውነት ፡ እግዚአብሔርን ፡ ደስ ፡ የምታሰኘው ፡ ስለሆነ ፣ ፡ እንግዲህ ፡ እንደዚህ ፡ ያለ ፡ ጽድቅን ፡ ሥራ ። እግዚአብሔርም ፡ እንደ ፡ አዘዘ ፡ ለካህናት ፡ ስጥ ። ከወይን ፡ መጭመቂያና ፡ ከእህል ፡ ዐውድማ ፡ የተገኘውን ፡ መጀመሪያውን ፡ ለካህናት ፡ መስጠት ፡ የሚገባ ፡ እንደሆነ ።'),
  ('334307bc-8927-539d-a1be-90c99fc59de1', 'e86bb63d-0a27-5c02-a6f1-cad3d11dbb4f', 'a10eb387-1ecd-535b-aa58-ed7ca82b5afa', 18, 18, 'እነርሰ ፡ ለተቸገረው ፡ ሁሉ ፡ ይሰጡ ፡ ዘንድ ፡ የሰለጠኑ ፡ ናቸውና ፣ ፡ በቤተ ፡ ክርስቲያን ፡ ሥራ ፡ ሁሉ ፡ ላይም ፡ ሥልጣን ፡ አላቸው ።'),
  ('75b5da59-9fd9-5cca-a349-6e454c11aa50', 'e86bb63d-0a27-5c02-a6f1-cad3d11dbb4f', 'a10eb387-1ecd-535b-aa58-ed7ca82b5afa', 19, 19, 'ምን ፡ ጊዜ ፡ ይህን ፡ ሠራ? ፡ ለማንስ ፡ ሰጠ? ፡ መቸስ ፡ ጨረሰ? ፡ ወደምን ፡ ቦታስ ፡ ወሰደ? ፡ እያላችሁ ፡ ኤጲስ ፡ ቆጶሳቱን ፡ በሥራቸው ፡ ሁሉ ፡ አታስተሐቅሯቸው ።'),
  ('147b3d08-913f-5f1b-a50d-f0ca7cb4bb3d', 'e86bb63d-0a27-5c02-a6f1-cad3d11dbb4f', 'a10eb387-1ecd-535b-aa58-ed7ca82b5afa', 20, 20, 'በጎ ፡ ሥራን ፡ ቢሠራ ፣ ፡ ወይም ፡ ክፉ ፡ ሥራን ፡ ቢሠራ ፣ ፡ በሚገባቢያ ፡ ደርግ ፣ ፡ ያለ ፡ አግባብም ፡ ሲያደርግ ፣ ፡ ለካህናት ፡ ሹመትንና ፡ ታላቅ ፡ ማዕርግን ፡ የሰጣቸው ፡ ፈጣሪ ፡ እግዚአብሔር ፡ ከእነርሱ ፡ አብልጦ ፡ ይመራ ፡ መረዋልና ።'),
  ('02de198e-2840-5ab2-aa6e-85a8a4616612', 'e86bb63d-0a27-5c02-a6f1-cad3d11dbb4f', 'a10eb387-1ecd-535b-aa58-ed7ca82b5afa', 21, 21, 'አንተ ፡ ግን ፡ በዐይኖችህ ፡ ፊት ፡ እግዚአብሔርን ፡ መፍራት ፡ አድርግ ። እንዲህም ፡ የሚለውን ፡ ቃል ፡ ሁል ፡ ጊዜ ፡ አስብ ፣ ፡ አምላክህ ፡ እግዚአብሔርን ፡ በፍጹም ፡ ልብህና ፡ በፍጹም ፡ ኀይልህ ፡ ውደደው ፣ ፡ ወደ ፡ ጣዖታት ፡ የምትወስደውንም ፡ መንገድ ፡ አትከተል ፣ ፡ ነፍስ ፡ የሌላቸውን ፣ እነዚህን ፡ የመሳሰለውን ፡ ሁሉ ፡ አትከተል ፣ ፡ የአጋንንት ፡ ትምህርትን ፣ ፡ ክርስቶስ ፡ ያላዘዘውን ፡ ባዕድ ፡ ፍጥረትን ፡ አትከተል ።')
