  ('c1d1683e-4567-576f-a813-3e74e6e05434', 'e86bb63d-0a27-5c02-a6f1-cad3d11dbb4f', 'a10eb387-1ecd-535b-aa58-ed7ca82b5afa', 22, 22, 'ነገር ፡ ግን ፡ አንተ ፡ የፈጣሪህ ፡ የእግዚአብሔር ፡ ሕግ ፡ የሚሆን ፡ የመጻሕፍት ፡ ንባብን ፡ መርምር ። በየጊዜውም ፡ መጻሕፍቱን ፡ ማንበብ ፡ አታቋርጥ ፡ የሚቃወም ፡ ክፋትን ፡ ሁሉ ፡ በሕግ ፡ ያልታዘዘ ፡ ዋዛንና ፡ ቍጣን ፡ ዝብብትንም ፡ ከአንተ ፡ አርቅ ፣ ፡ ነገር ፡ ግን ፡ በሥጋ ፡ የወለዱህን ፡ አባትህንና ፡ እናትህን ፡ አክብር ፣ ፡ ባልንጀራህንም ፡ እንደራስህ ፡ ውደድ ፣ ፡ ድሆችንም ፡ መጽውት ። ጥቅም ፡ ከሌለውም ፡ ከሐሰት ፡ መሐላ ፡ ራቅ ።'),
  ('0129678f-7ee4-5323-ac8d-e3d2574f4a98', 'e86bb63d-0a27-5c02-a6f1-cad3d11dbb4f', 'a10eb387-1ecd-535b-aa58-ed7ca82b5afa', 23, 23, 'አንተ ፡ ግን ፡ ከክርስቶስ ፡ ቤተ ፡ ክርስቲያን ፡ አትራቅ ፣ ፡ ነገር ፡ ግን ፡ ሁልጊዜ ፡ ወደ ፡ እርሷ ፡ ገሥግሥ ፣ ፡ ሕይወትን ፡ ስለሰጣቸው ፡ እግዚአብሔርን ፡ እያመሰገኑት ፡ በሌሊትና ፡ ቀን ፡ ከማይተኙት ፡ ትሑታን ፡ ሰዎች ፡ ጋርም ፡ አመስግን ።'),
  ('9c8e8a87-188d-5e0d-a84f-7a4351e398c7', 'e86bb63d-0a27-5c02-a6f1-cad3d11dbb4f', 'a10eb387-1ecd-535b-aa58-ed7ca82b5afa', 24, 24, 'በእጆችህ ፡ ሥራ ፡ ኑር ፡ ፣ እንደተ ፡ ቻለህ ፡ መጠን ፡ ካለህ ፡ ገንዘብ ፡ ለእግዚአብሔር ፡ አቅርብ ። ከነዳያን ፡ ጋርም ፡ ወዳጅ ፡ ሁን ። ነቀዝና ፡ ብል ፡ የማያበላሸውንና ፡ ሌባ ፡ የማያገኘውን ፡ መንግሥተ ፡ ሰማያትን ፡ ገንዘብ ፡ አድርግ ።'),
  ('27fbcb00-e66e-5d49-a709-9abaa2d8ac84', 'e86bb63d-0a27-5c02-a6f1-cad3d11dbb4f', 'a10eb387-1ecd-535b-aa58-ed7ca82b5afa', 25, 25, 'ነፍስህን ፡ ልታድን ፡ ከወደድህስ ፡ ከኤጲስ ፡ ቆጶሱ ፡ ጋራ ፣ ፡ ከወንድምህ ፡ ከሕዝባዊውም ፡ ጋራ ፣ ፡ ከወዳጅህም ፡ ጋራ ፡ በዐመፅ ፡ አትከራከር ። በማይገባ ፡ ከእርሱ ፡ ጋር ፡ ብትከራከር ፡ ግን ፡ የሚያስገድድህ ፡ ሳይኖር ፡ በደልንና ፡ ኀጢአትን ፡ ወደራስህ ፡ ሳብህ ፣ ፡ ለሕዝባዊ ፡ ያይደለ ፡ ለካህናት ፡ ፍርድ ፡ ተሰጥቷቸዋልና ፣ ፡ እግዚአብሔር ፡ በእውነትና ፡ በቅንነት ፡ ፍረዱ ፣ ፡ የሕዝቡ ፡ ሹሞችም ፡ አስተውሉ ፣ ፡ ለእያንዳንዱም ፡ ፍረዱ ፡ ብሏልና ።'),
  ('6c61957f-a234-5163-a36a-94f48dafb4fb', 'e86bb63d-0a27-5c02-a6f1-cad3d11dbb4f', 'a10eb387-1ecd-535b-aa58-ed7ca82b5afa', 26, 26, 'ለእናንተ ፡ ግን ፡ የካህናት ፡ ሹመት ፡ ለሌላቸውም ፡ በማንም ፡ ላይ ፡ ትፈርዱ ፡ ዘንድ ፡ አልተፈቀደላችሁም ። የክህነት ፡ ሹመት ፡ በሌላቸው ፡ አትፍረዱ ፣ ፡ ፍርዳችሁም ፡ አይወደድላችሁም ፡ ብሏቸዋልና ፣ ፡ ነገር ፡ ግን ፡ ኤጲስ ፡ ቆጶሱ ፡ በሚገባ ፡ ይፍረድ ፣ ፡ እንዲህ ፡ የሚል ፡ ተጽፏልና ። ለችግረኛውና ፡ እናትና ፡ አባት ፡ ለሞቱበት ፡ ልጅ ፡ ፍረዱ ፣ ፡ ለተገፋውና ፡ ለምስኪኑ ፡ ጽድቅን ፡ አድርጉ ፣ ፡ ብቸኛውንና ፡ ችግረኛውን ፡ አድኑ ፡ የሚል ፡ እንደ ፡ ተጻፈ ። ዳግመኛም ፡ በመካከላችሁ ፡ በእውነት ፡ ለምን ፡ አትፈርዱም? ፡ ብሏል ።'),
  ('169e5620-2005-54ca-a387-b7a567aea9de', '69d8e037-ce9d-56e6-adb7-75470f7dcd39', '6d51f407-4a44-568b-a115-fb23a823dc0f', 1, 1, 'ደጋጎች ፡ ዐዋቆችና ፡ አስተዋዮች ፡ እንደሆኑት ፡ እንደ ፡ ቀደሙት ፡ አባቶች ፡ ንጹሓን ፡ ሁኑ ፣ ፡ ከእናንተም ፡ ክፉ ፡ ሥርዐትንና ፡ ክፉ ፡ ልማድን ፡ አርቁ ፣ ፡ ነገር ፡ ግን ፡ የሕይወት ፡ ጐዳናን ፡ ለእናንተ ፡ ምረጡ ፡ እንጂ ።'),
  ('79a84115-1a3c-566f-ab2f-636911706ce7', '69d8e037-ce9d-56e6-adb7-75470f7dcd39', '6d51f407-4a44-568b-a115-fb23a823dc0f', 2, 2, 'ኤጲስ ፡ ቆጶሱ ፡ በዚች ፡ ጎዳና ፡ ይሔድ ፡ ዘንድ ፡ እንደሚገባውም ፡ ይሠራ ፡ ዘንድ ፡ ከክፉ ፡ ምግባርም ፡ ተለይቶ ፡ በጎውን ፡ ሥራ ፡ ይሠራ ፡ ዘንድ ፡ አግባብ ፡ ነው ።'),
  ('c5ea0a0a-aee8-5cc4-aa06-05399ea553b6', '69d8e037-ce9d-56e6-adb7-75470f7dcd39', '6d51f407-4a44-568b-a115-fb23a823dc0f', 3, 3, 'ንስሐ ፡ የሚወዱ ፡ ድውያንንም ፡ ያድናቸው ። አንመለስም ፡ ያሉትን ፡ ግን ፡ ይለያቸው ፣ ፡ በባቢሎን ፡ ሁለቱ ፡ ረበናት ፡ በሶስና ፡ ላይ ፡ እንዳደረጉ ፣ ፡ የግብጽ ፡ ሴትም ፡ በዮሴፍ ፡ ላይ ፡ እንዳደረገች ፡ እያመካኙ ፡ በቅንአት ፡ የሚያጠምዱና ፡ ነገር ፡ የሚሠሩ ፡ ብዙዎች ፡ አሉና ።'),
  ('d59535c9-9576-55db-a420-dc3f2e74c080', '69d8e037-ce9d-56e6-adb7-75470f7dcd39', '6d51f407-4a44-568b-a115-fb23a823dc0f', 4, 4, 'አንተ ፡ የእግዚአብሔር ፡ ሰው ፡ ግን ፡ እኒህ ፡ እንዳደረጉት ፡ አታድርግ ። ነገር ፡ ግን ፡ ደግና ፡ የምትራራ ፡ ሁን ። ንስሐ ፡ የሚገቡትንም ፡ ተቀበላቸው ። ለኀጢአተኛው ፡ አታድላ ። ጻድቁንም ፡ አትግደል ።'),
  ('1a4f5bf2-419b-59c5-a806-480c380f88d9', '69d8e037-ce9d-56e6-adb7-75470f7dcd39', '6d51f407-4a44-568b-a115-fb23a823dc0f', 5, 5, 'ንስሐ ፡ የሚገቡትን ፡ የማይቀበል ፡ ኀጢአተኞችንም ፡ የማይመልስ ፡ ግን ፡ የቀጣ ፡ አባት ፡ ነው ። ሰላምም ፡ የለውም ፡ ቍጣ ፡ ካለበት ፡ ቦታ ፡ እግዚአብሔር ፡ አያድርምና ።'),
  ('3173f4b8-fb1f-553d-a680-7aed2ea37453', '69d8e037-ce9d-56e6-adb7-75470f7dcd39', '6d51f407-4a44-568b-a115-fb23a823dc0f', 6, 6, 'አንተ ፡ ግን ፡ በሐሰተኞች ፡ ወን ፡ ድማማቾች ፡ መካከል ፡ የሚንቀሳቀስ ፡ የስይጣን ፡ ወዳጅ ፡ ነህ ። ለእርሱም ፡ ሰላም ፡ የለውም ፡ በቤተ ፡ ክርስቲያንም ፡ ክርክርን ፡ ያደርጋል ።'),
  ('f73c50fa-42cd-502d-aedf-bec1ae3d698f', '69d8e037-ce9d-56e6-adb7-75470f7dcd39', '6d51f407-4a44-568b-a115-fb23a823dc0f', 7, 7, 'እንግዲህ ፡ አስተውሉ ። በክፋት ፡ ደስ ፡ የሚላቸው ፡ አላዋቆችንም ፡ መንገድ ፡ አትከተሉ ። ቃላቸውንም ፡ አትስሙ ። ነገር ፡ ግን ፡ ከእነርሱ ፡ ተጠበቁ ። ቂምና ፡ ቅንአት ፡ ነው ፡ እንጂ ፡ በዐይናቸው ፡ ፊት ፡ እግዚአብሔርን ፡ መፍራት ፡ የለምና ፡ ክፉዎች ፡ ሰዎች ፡ በደል ፡ የሌላቸውን ፡ ደጎችን ፡ ይከሱዋቸዋልና ። ክፉ ፡ ነገርንም ፡ በእነርሱ ፡ ያመጡባቸዋልና ፡ ወደጽኑ ፡ መቅሠፍትና ፡ መከራ ፡ ያዉርዱዋቸዋልና ።'),
